export const recipes: CountryRecipe[] = [{"country":"tw","id":"popcorn-chicken","slug":"popcorn-chicken","title":{"zh-TW":"經典台灣鹽酥雞","en":"Classic Taiwanese Popcorn Chicken","ja":"本場台湾の塩唐揚げ（塩酥鶏）","ko":"대만식 팝콘 치킨 (옌수지)","vi":"Gà lắc muối tiêu Đài Loan"},"subtitle":{"zh-TW":"九層塔香氣爆發・粗地瓜粉極致酥脆","en":"Bursting with Thai Basil Aroma & Coarse Tapioca Crunch","ja":"台湾バジルの香りと粗挽きさつまいも粉の極上ザクザク感","ko":"바질 향 폭발・굵은 고구마 전분의 바삭함","vi":"Húng quế thơm lừng & Giòn rụm bột khoai lang"},"tagline":{"zh-TW":"台灣夜市靈魂霸主，每走三步就有一攤的國民宵夜","en":"The undisputed king of Taiwanese night markets","ja":"台湾夜市の王道。3歩歩けば屋台に出会う国民的夜食","ko":"대만 야시장의 대표 간식이자 국민 야식","vi":"Ông vua ẩm thực chợ đêm Đài Loan"},"heroImage":"/images/tw/popcorn-chicken.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":420,"category":"fried","dietaryTags":["classic","halal"],"supportedCookware":["traditional","airFryer"],"culture":{"originCity":{"zh-TW":"台北 / 台南","en":"Taipei / Tainan","ja":"台北 / 台南","ko":"타이베이 / 타이난","vi":"Đài Bắc / Đài Nam"},"famousNightMarkets":[{"zh-TW":"士林夜市","en":"Shilin Night Market","ja":"士林夜市","ko":"스린 야시장","vi":"Chợ đêm Shilin"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"},{"zh-TW":"樂華夜市","en":"Lehua Night Market","ja":"樂華夜市","ko":"러화 야시장","vi":"Chợ đêm Lehua"}],"historyStory":{"zh-TW":"鹽酥雞誕生於1970年代的台南，最初是攤販為了不浪費肉塊，將雞肉切成一口大小，裹上粗顆粒地瓜粉油炸。起鍋前一把新鮮九層塔的高溫油爆，創造出無法複製的台味靈魂香氣。","en":"Invented in Tainan during the 1970s, street vendors sliced chicken thighs into bite-sized pieces and coated them with coarse sweet potato starch. The signature finish of flash-frying fresh Thai basil creates an unmistakable aroma.","ja":"1970年代の台南発祥。一口大の鶏もも肉に粗粒さつまいも粉をまぶしてカリッと揚げ、仕上げにサッと素揚げした台湾バジルを合わせるのが本場の味です。","ko":"1970년대 대만 남부 타이난에서 시작된 국민 야식입니다. 한 입 크기의 닭고기를 굵은 고구마 전분에 묻혀 튀겨내고, 갓 튀긴 바질 잎과 특제 후추 소금을 곁들입니다.","vi":"Ra đời từ những năm 1970 tại Đài Nam, gà được cắt miếng vừa ăn, lăn qua bột khoai lang hạt to chiên giòn tan cùng lá húng quế tươi."},"taiwaneseHokkien":"Kiâm-soo-ke (ㄐㄧㄢˊ ㄙㄨ ㄍㄟ)","mandarinPinyin":"Yánsūjī (ㄧㄢˊ ㄙㄨ ㄐㄧ)","audioPronunciationText":"鹽酥雞，要辣加九層塔"},"ingredients":[{"id":"chicken-thigh","name":{"zh-TW":"去骨帶皮雞腿肉","en":"Boneless Chicken Thigh","ja":"鶏もも肉（皮付き）","ko":"닭다리살 (순살)","vi":"Thịt đùi gà rút xương"},"amount":400,"unitMetric":"g","unitUS":"14 oz","chineseName":"去骨雞腿肉","chinesePinyin":"Qù gǔ jī tuǐ ròu"},{"id":"sweet-potato-starch","name":{"zh-TW":"台灣粗顆粒地瓜粉 (番薯粉)","en":"Taiwanese Coarse Sweet Potato Starch","ja":"台湾産 粗粒さつまいも粉（地瓜粉）","ko":"대만산 굵은 고구마 전분","vi":"Bột khoai lang hạt to Đài Loan"},"amount":100,"unitMetric":"g","unitUS":"0.7 cup","isKeyFlavor":true,"chineseName":"粗顆粒地瓜粉","chinesePinyin":"Cū kēlì dìguā fěn","substitute":{"substituteName":{"zh-TW":"木薯粉 (樹薯粉) + 少量太白粉","en":"Tapioca Starch (or Potato Starch + Cornstarch 1:1)","ja":"タピオカ粉 または 片栗粉＋コーンスターチ（1:1）","ko":"타피오카 전분 또는 감자전분+옥수수전분(1:1)","vi":"Bột năng hoặc Bột bắp kết hợp bột khoai tây"},"ratio":"1:1","explanation":{"zh-TW":"台灣鹽酥雞表面一粒粒金黃小脆珠來自「粗顆粒」地瓜粉。若無可用木薯粉代替，但避免純玉米粉（口感會偏硬粉感重）。","en":"The iconic bumpy, super-crunchy crust comes from coarse granules. Tapioca starch is the closest substitute.","ja":"独特のザクザクした食感は粗粒粉ならでは。手に入らない場合はタピオカ粉で代用可能です。","ko":"특유의 오돌토돌하고 바삭한 크러스트는 굵은 고구마 전분에서 나옵니다. 없을 땐 타피오카 전분이 가장 가깝습니다.","vi":"Độ giòn xốp đặc trưng hạt nổi đến từ bột khoai lang hạt thô. Có thể thay bằng bột năng."},"whereToBuy":{"zh-TW":"大華超市 (99 Ranch)、H-Mart、亞超粉類專區","en":"99 Ranch Market, H-Mart, or Asian grocery flour aisle","ja":"中華物産店、アジア系スーパー、Amazon","ko":"아시안 마켓, 온라인 중국 식자재 몰","vi":"Siêu thị châu Á hoặc tiệm thực phẩm Đài Loan"}}},{"id":"thai-basil","name":{"zh-TW":"新鮮九層塔 (或羅勒)","en":"Fresh Thai Basil (or Sweet Basil)","ja":"新鮮な台湾バジル（九層塔）またはホーリーバジル","ko":"신선한 타이 바질 (구층탑)","vi":"Lá húng quế tươi"},"amount":30,"unitMetric":"g","unitUS":"1 bunch","isKeyFlavor":true,"chineseName":"九層塔","chinesePinyin":"Jiǔ céng tǎ","substitute":{"substituteName":{"zh-TW":"甜羅勒 (Sweet Basil) 或 義大利羅勒","en":"Italian Sweet Basil or Holy Basil","ja":"スイートバジル","ko":"스위트 바질","vi":"Húng quế tây (Sweet Basil)"},"ratio":"1:1","explanation":{"zh-TW":"九層塔香氣比西餐甜羅勒更辛香濃郁。油炸前必須徹底擦乾水份，否則會劇烈噴油！","en":"Thai basil has a sharper, anise-like pungency. Ensure leaves are bone-dry before frying to avoid oil splatter.","ja":"九層塔はアニスのような強い香りが特徴。油ハネを防ぐため水分を完全に拭き取ってください。","ko":"타이 바질은 향이 더 진합니다. 기름에 넣기 전 물기를 완벽히 제거해야 기름이 튀지 않습니다.","vi":"Lá phải thật khô ráo trước khi cho vào chảo dầu để tránh bắn dầu nguy hiểm."},"whereToBuy":{"zh-TW":"各國超市蔬菜冷藏區、東南亞超市","en":"Asian markets, Trader Joe's, Whole Foods herb section","ja":"アジア系スーパー、一部大型スーパー","ko":"대형 마트 허브 코너, 동남아 식료품점","vi":"Chợ tươi hoặc siêu thị địa phương"}}},{"id":"garlic","name":{"zh-TW":"大蒜 (壓泥+切碎)","en":"Garlic (Minced & Crushed)","ja":"にんにく（すりおろし＋みじん切り）","ko":"마늘 (다진 마늘)","vi":"Tỏi băm nhuyễn"},"amount":4,"unitMetric":"clove","unitUS":"4 cloves","chineseName":"大蒜","chinesePinyin":"Dà suàn"},{"id":"soy-sauce","name":{"zh-TW":"台灣純釀造醬油","en":"Taiwanese Dark Soy Sauce","ja":"醤油","ko":"진간장","vi":"Nước tương đậu nành"},"amount":25,"unitMetric":"ml","unitUS":"1.5 tbsp","chineseName":"醬油","chinesePinyin":"Jiàng yóu"},{"id":"rice-wine","name":{"zh-TW":"料理米酒 (或紹興酒)","en":"Taiwanese Rice Wine (or Shaoxing Wine)","ja":"台湾料理酒（米酒）または紹興酒","ko":"대만 요리술 (미주 또는 소흥주)","vi":"Rượu gạo nấu ăn"},"amount":15,"unitMetric":"ml","unitUS":"1 tbsp","chineseName":"料理米酒","chinesePinyin":"Liào lǐ mǐ jiǔ","substitute":{"substituteName":{"zh-TW":"清真友善：新鮮薑汁 + 蘋果醋","en":"Halal-friendly: Fresh ginger juice + splash of apple cider vinegar","ja":"生姜の搾り汁＋リンゴ酢少々","ko":"생강즙 + 사과식초 약간","vi":"Nước cốt gừng tươi + giấm táo"},"ratio":"1:1","explanation":{"zh-TW":"去腥軟化肉質。清真飲食或無酒精烹飪可使用生薑汁替代。","en":"Tenderizes chicken and removes gamey smell. Ginger juice is a great alcohol-free alternative.","ja":"肉を柔らかくし臭みを消します。ノンアルコール調理には生姜汁が最適です。","ko":"잡내를 잡고 육질을 부드럽게 합니다. 무알코올 시 생강즙으로 대체하세요.","vi":"Khử mùi và làm mềm thịt. Người ăn Halal có thể dùng nước gừng."},"whereToBuy":{"zh-TW":"超市調味品專區","en":"Supermarket vinegar/Asian aisle","ja":"スーパー調味料コーナー","ko":"일반 마트","vi":"Siêu thị"}}},{"id":"five-spice","name":{"zh-TW":"台灣五香粉","en":"Taiwanese Five-Spice Powder","ja":"五香粉（ウーシャンフェン）","ko":"오향분 (오향가루)","vi":"Bột ngũ vị hương"},"amount":3,"unitMetric":"g","unitUS":"0.5 tsp","isKeyFlavor":true,"chineseName":"五香粉","chinesePinyin":"Wǔ xiāng fěn"},{"id":"white-pepper-salt","name":{"zh-TW":"夜市特調白胡椒鹽 (鹽+白胡椒+微量肉桂+糖)","en":"Taiwanese Night Market Pepper Salt (White pepper + Salt + Hint of Cinnamon + Sugar)","ja":"特製台湾胡椒塩（塩＋白胡椒＋シナモン極微量＋砂糖）","ko":"대만식 특제 후추소금 (백후추+소금+계피 약간+설탕)","vi":"Muối tiêu trắng đặc chế Đài Loan"},"amount":8,"unitMetric":"g","unitUS":"1.5 tsp","isKeyFlavor":true,"chineseName":"胡椒鹽粉","chinesePinyin":"Hú jiāo yán fěn"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"雞肉切塊與秘製醬汁醃漬","en":"Slice & Marinate Chicken with Five-Spice","ja":"鶏肉をカットし秘伝のタレに漬け込む","ko":"닭고기 손질 및 특제 양념에 재우기","vi":"Cắt thịt và ướp với gia vị ngũ vị hương"},"instruction":{"zh-TW":"將去骨雞腿肉切成約 2.5~3 公分的一口大小。加入醬油、米酒、蒜泥、五香粉、糖與白胡椒粉，用手抓醃按摩 2 分鐘，冷藏醃漬至少 20 分鐘（醃隔夜更入味）。","en":"Cut chicken thigh into 2.5-3cm bite-sized chunks. Add soy sauce, rice wine, minced garlic, five-spice powder, sugar, and white pepper. Massage for 2 mins, then chill in fridge for at least 20 mins.","ja":"鶏もも肉を一口大（約2.5〜3cm角）に切ります。醤油、酒、ニンニク、五香粉、砂糖、白胡椒を加え、手でよく揉み込んで冷蔵庫で20分以上寝かせます。","ko":"닭다리살을 한 입 크기(2.5~3cm)로 깍둑썰기합니다. 진간장, 맛술, 다진 마늘, 오향분, 설탕, 백후추를 넣고 조물조물 2분간 마사지한 뒤 냉장고에서 최소 20분간 재워둡니다.","vi":"Thái đùi gà thành miếng vừa ăn cỡ 3cm. Cho nước tương, rượu, tỏi, ngũ vị hương, tiêu vào bóp đều 2 phút rồi ướp lạnh 20 phút."},"image":"/images/tw/popcorn-chicken-step1.jpg","durationSeconds":1200,"crucialTips":{"zh-TW":"雞腿肉比雞胸肉多汁嫩滑；醃料中加一小勺糖能幫助高溫快速上色產生美拉德焦香！","en":"Chicken thigh stays juicy and never dries out. A pinch of sugar accelerates Maillard browning in hot oil.","ja":"もも肉を使うことでジューシーに仕上がります。砂糖が油の中で香ばしい照りを生み出します。","ko":"닭다리살을 써야 육즙이 촉촉합니다. 소량의 설탕이 튀김옷의 바삭한 갈색빛을 돕습니다.","vi":"Dùng đùi gà để thịt mềm mọng. Chút đường giúp gà lên màu vàng óng đẹp mắt."}},{"stepNumber":2,"title":{"zh-TW":"裹上粗地瓜粉與「回潮」關鍵步驟","en":"Dredge in Coarse Starch & Rest for \"Hydration\"","ja":"粗挽きさつまいも粉をまぶし「粉戻し（回潮）」する","ko":"굵은 고구마 전분 묻히기 및 5분 휴지 (튀김옷 밀착 핵심)","vi":"Tẩm bột khoai lang và nghỉ cho bột ngấm ẩm (Hồi triều)"},"instruction":{"zh-TW":"將醃好的雞肉逐塊均勻裹上粗顆粒地瓜粉，輕輕按壓讓粉附著。擺在盤中「靜置 5 分鐘等待粉變潮濕（回潮）」，這一步能防止下鍋時粉肉分離、炸油變渾濁！","en":"Coat each chicken chunk thoroughly in coarse sweet potato starch. Place on a tray and WAIT 5 MINUTES for the starch to absorb moisture and turn slightly damp (\"Huichao\"). This locks the crust so it never falls off in oil!","ja":"鶏肉に粗挽きさつまいも粉をしっかりまぶします。バットに並べ「5分間そのまま置いて粉をしっとり馴染ませる（回潮）」のが最大のコツ！粉落ちを防ぎます。","ko":"닭고기 조각마다 굵은 고구마 전분을 꼼꼼히 묻힙니다. 트레이에 올리고 5분간 그대로 두어 전분이 고기 수분을 머금도록 기다립니다 (튀길 때 가루가 떨어지는 것을 완벽 방지).","vi":"Lăn từng miếng gà qua bột khoai lang hạt to. Xếp ra đĩa ĐỂ NGHỈ 5 PHÚT cho bột hút ẩm hơi sẫm màu lại. Bí quyết này giúp bột bám chặt không bị rơi rụng."},"image":"/images/tw/popcorn-chicken-step2.jpg","durationSeconds":300,"dangerWarnings":{"zh-TW":"千萬不要裹粉後立刻下鍋！未回潮的乾粉遇到滾油會大量掉落，導致油發黑產生焦味。","en":"DO NOT drop freshly dusted chicken immediately into oil! Dry starch will instantly detach and burn the oil.","ja":"粉をつけてすぐ揚げないでください！粉がはがれて油が汚れ、焦げ付きの原因になります。","ko":"가루를 묻히자마자 바로 기름에 넣지 마세요! 가루가 분리되어 기름이 타버립니다.","vi":"Tuyệt đối không thả vào chảo ngay! Bột khô sẽ bong ra làm cháy khét dầu."}},{"stepNumber":3,"title":{"zh-TW":"初次油炸：定型與熟化 (160°C)","en":"First Fry: Set Shape & Cook Through (160°C / 320°F)","ja":"1度目の揚げ：中まで火を通す（160℃・中温）","ko":"1차 튀김: 속까지 익히기 (160°C 중온)","vi":"Chiên lần 1: Làm chín thịt từ trong ra ngoài (160°C)"},"instruction":{"zh-TW":"【傳統油炸】：油溫升至 160°C（木筷插入冒細小氣泡），逐塊下雞肉，先不要翻動讓麵衣定型 1 分鐘，接著炸約 3~4 分鐘至八分熟撈出。\n【氣炸鍋模式】：噴少許油，設定 180°C (355°F) 烤 10 分鐘。","en":"Traditional Fry: Heat oil to 160°C (320°F). Drop chicken chunks one by one. Do not stir for the first minute to let crust set. Fry for 3-4 mins until light golden and cooked through. Remove and drain.\nAir Fryer: Lightly spray with oil, air-fry at 180°C (355°F) for 10 mins.","ja":"【油で揚げる場合】：油を160℃に熱し、肉を1つずつ入れます。最初の1分は触らず衣を固め、合計3〜4分揚げて一度取り出します。\n【ノンフライヤー】：油を軽く吹きかけ、180℃で10分加熱。","ko":"【기름 튀김】：기름 온도를 160°C로 맞추고 닭고기를 하나씩 넣습니다. 1분간 건드리지 않고 옷을 굳힌 뒤 3~4분간 튀겨 건져냅니다.\n【에어프라이어】：오일 스프레이를 뿌린 후 180°C에서 10분간 조리합니다.","vi":"Chiên dầu: Đun dầu 160°C, thả từng miếng gà vào không đảo trong 1 phút đầu. Chiên 3-4 phút rồi vớt ra ráo dầu.\nNồi chiên không dầu: Xịt chút dầu, nướng 180°C trong 10 phút."},"image":"/images/tw/popcorn-chicken-step3.jpg","durationSeconds":240,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 180°C (355°F) for 10 mins","instructionOverride":{"zh-TW":"在氣炸鍋炸籃底部鋪烘焙紙或刷薄油，放入回潮後的雞肉塊（不要重疊），表面均勻噴上一層食用油。以 180°C 氣炸 10 分鐘，中途 6 分鐘時翻面一次。","en":"Place chicken in single layer in air fryer basket. Generously spray oil over the starch coating. Air fry at 180°C (355°F) for 10 mins, flipping at 6 mins.","ja":"重ならないように並べ、表面全体にしっかり油をスプレーします。180℃で10分、途中で一度裏返します。","ko":"에어프라이어에 겹치지 않게 담고 표면에 식용유를 골고루 분사합니다. 180°C에서 10분간 돌리고 6분째에 한 번 뒤집어줍니다.","vi":"Xếp gà vào khay một lớp không đè lên nhau, xịt đẫm dầu lên mặt bột. Nướng 180°C 10 phút, lật mặt lúc 6 phút."}}]},{"stepNumber":4,"title":{"zh-TW":"大火復炸與九層塔高溫爆香 (190°C)","en":"Second Flash-Fry with Thai Basil for Super Crunch (190°C / 375°F)","ja":"2度目の高温揚げ＆台湾バジルの素揚げ（190℃・高温）","ko":"2차 고온 재튀김 & 바질 폭풍 투하 (190°C 크런치)","vi":"Chiên lần 2 lửa lớn & Thả húng quế giòn tan (190°C)"},"instruction":{"zh-TW":"【傳統油炸】：將油溫拉高至 190°C（大火熱油）。倒回雞肉大火復炸 45~60 秒逼出多餘油脂，起鍋前 5 秒丟入「擦乾水分的九層塔」，滋滋作響香氣爆發後立刻與雞肉一同撈出瀝油！\n【氣炸鍋模式】：轉 200°C (400°F) 復炸 3 分鐘，最後 1 分鐘加入九層塔。","en":"Traditional: Raise oil temp to 190°C (375°F). Drop chicken back in for 45-60 secs to expel oil and achieve ultra-crispiness. 5 seconds before pulling out, toss in BONE-DRY Thai basil leaves—listen to the sizzling explosion of aroma, then immediately scoop everything out!\nAir Fryer: Crank to 200°C (400°F) for 3 mins, tossing in basil for the final 1 min.","ja":"【油で揚げる場合】：油温を190℃に上げ、肉を戻して45〜60秒二度揚げ。引き上げる5秒前に「水気を切ったバジル」を一気に投入！香りが立ったら即座に引き上げます。\n【ノンフライヤー】：200℃に温度を上げ3分追加、最後の1分でバジルを加えます。","ko":"【기름 튀김】：기름 온도를 190°C로 올려 닭고기를 다시 넣고 45~60초간 고온으로 튀겨 기름을 뺍니다. 건지기 5초 전 바질 잎을 넣고 바삭한 향이 올라오면 즉시 함께 건져냅니다!\n【에어프라이어】：200°C로 올려 3분 더 굽고 마지막 1분에 바질을 넣습니다.","vi":"Chiên lần 2: Tăng nhiệt 190°C, thả gà vào chiên nhanh 45-60 giây để ép bớt dầu. 5 giây trước khi vớt, thả ngay lá húng quế khô vào đảo đều rồi vớt ra ngay!"},"image":"/images/tw/popcorn-chicken-step4.jpg","durationSeconds":60,"dangerWarnings":{"zh-TW":"⚠️ 九層塔下油鍋時會劇烈劈啪作響！請務必先用廚房紙巾徹底擦乾葉片水分，並備好鍋蓋或防濺網。","en":"⚠️ Fresh herbs splutter vigorously when dropped in hot oil! Keep hands back and use a splatter guard.","ja":"⚠️ バジル投入時に油が激しくはじけます！必ず水分を完全に拭き取り、注意して作業してください。","ko":"⚠️ 바질이 기름에 닿으면 타닥타닥 튑니다! 물기를 완벽히 닦아내고 조심하세요.","vi":"⚠️ Lá húng quế gặp dầu nóng sẽ nổ tí tách! Hãy lau thật khô và cẩn thận."},"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 200°C (400°F) for 3 mins","instructionOverride":{"zh-TW":"將氣炸鍋升溫至最高溫 200°C (400°F)，繼續氣炸 3 分鐘讓外皮金黃酥脆。最後 1 分鐘將擦乾並抹上少許油的九層塔丟入拌勻，出鍋香氣撲鼻！","en":"Increase temperature to 200°C (400°F) for 3 mins. Add oil-brushed basil leaves for the last 1 min and shake basket.","ja":"200℃の最高温に上げ3分間加熱。最後の1分で油を絡めたバジルを投入してサッと香りをまとわせます。","ko":"온도를 200°C로 높여 3분간 더 돌려 바삭함을 극대화합니다. 마지막 1분에 오일을 살짝 바른 바질을 넣고 섞어줍니다.","vi":"Tăng nhiệt 200°C nướng 3 phút. 1 phút cuối cho lá húng quế xoa chút dầu vào đảo đều thơm phức."}}]},{"stepNumber":5,"title":{"zh-TW":"撒上夜市靈魂胡椒鹽，裝袋竹籤開吃！","en":"Toss with Pepper Salt & Serve with Skewers","ja":"特製胡椒塩をたっぷり振り、竹串でいただく！","ko":"특제 후추소금 골고루 뿌려 나무꼬치로 콕 찍어 먹기!","vi":"Rắc muối tiêu đặc chế, xóc đều trong túi giấy!"},"instruction":{"zh-TW":"將炸好的鹽酥雞與酥脆九層塔放入大金屬盆中，趁熱大量撒上靈魂白胡椒鹽（喜辣者可加特細辣椒粉），雙手掂盆均勻翻滾，裝入紙袋插上竹籤，趁熱享用！","en":"Place piping-hot chicken and crispy basil in a large metal mixing bowl. Generously dust with Taiwanese pepper salt (and chili powder if desired). Toss well to coat every piece. Serve in paper bags with bamboo skewers!","ja":"ボウルに熱々の唐揚げとバジルを入れ、特製胡椒塩（辛党は一味唐辛子も）をたっぷり振って豪快にトスします。紙袋に入れ、竹串で刺してアツアツをどうぞ！","ko":"뜨거운 치킨과 바삭한 바질을 볼에 담고, 특제 후추소금(기호에 따라 고춧가루 추가)을 넉넉히 뿌려 골고루 털어 섞어줍니다. 종이봉투에 담아 나무꼬치로 즐기세요!","vi":"Cho gà nóng hổi và lá quế giòn vào âu lớn, rắc đẫm muối tiêu trắng Đài Loan, xóc đều cho bám đều rồi cho vào túi giấy cắm que tre thưởng thức!"},"image":"/images/tw/popcorn-chicken-step5.jpg","durationSeconds":30}],"troubleshooting":[{"id":"ts-pc-1","problem":{"zh-TW":"炸出來的麵衣粉粉的、容易脫落掉粉？","en":"Why is my crust powdery and falling off in oil?","ja":"衣が粉っぽく、油の中でボロボロはがれてしまう？","ko":"튀김옷이 바삭하지 않고 가루가 떨어지며 벗겨지나요?","vi":"Tại sao lớp vỏ bị bở bột và bong tróc khi chiên?"},"cause":{"zh-TW":"裹粉後沒有等待「回潮」，乾粉尚未吸收肉汁就直接下油鍋。","en":"Skipped the \"Hydration\" step. Dry powder hits hot oil and floats away instantly.","ja":"粉をつけた後の「粉戻し（回潮）」時間を取らずにすぐ揚げたためです。","ko":"전분을 묻힌 후 5분간 휴지(회조) 과정을 거치지 않고 바로 튀겼기 때문입니다.","vi":"Bỏ qua bước nghỉ hồi triều khiến bột khô chưa kịp hút ẩm bám vào thịt."},"solution":{"zh-TW":"裹完地瓜粉後務必靜置 5 分鐘，看到粉粒變深色潮濕再下鍋！","en":"Always wait 5 minutes until starch turns darker and slightly moist before frying.","ja":"粉をまぶした後、必ず5分放置して粉がしっとりしてから油に入れてください！","ko":"가루가 고기 표면에서 촉촉하게 색이 변할 때까지 반드시 5분 기다려주세요!","vi":"Bắt buộc để nghỉ 5 phút cho bột đổi màu ẩm sẫm rồi mới thả vào chiên."}},{"id":"ts-pc-2","problem":{"zh-TW":"放涼後很快變軟、不酥脆？","en":"Why does the chicken get soggy quickly after cooling down?","ja":"冷めるとすぐにフニャフニャになってしまう？","ko":"시간이 지나면 금방 눅눅해지나요?","vi":"Tại sao gà nhanh ỉu không giữ được độ giòn?"},"cause":{"zh-TW":"沒有進行「高溫大火復炸」，內部殘留油份與水氣滲出。","en":"Skipped the high-heat second flash fry to force out trapped water and oil.","ja":"2度目の高温揚げ（二度揚げ）を行わなかったため、余分な油と水分が残っています。","ko":"190°C 고온 재튀김 과정을 생략하여 수분과 기름이 겉면에 갇혔기 때문입니다.","vi":"Chưa chiên lần 2 ở nhiệt độ cao để ép hết hơi nước và dầu thừa."},"solution":{"zh-TW":"一定要以 190°C 大火復炸 45 秒，高溫逼油是持久酥脆的關鍵！","en":"Flash-fry at 190°C for 45-60 seconds. High heat forces the moisture out!","ja":"仕上げに190℃の強火で45秒サッと二度揚げすることでカリカリ感が持続します！","ko":"반드시 190°C에서 45초간 고온 재튀김을 해주세요. 바삭함이 오래 갑니다!","vi":"Nhất định phải chiên lại lần 2 ở 190°C trong 45 giây để giòn lâu cả tiếng."}}],"proTips":[{"zh-TW":"台灣地瓜粉分「粗顆粒」與「細顆粒」，做鹽酥雞一定要指名【粗顆粒】，才有夜市一粒粒立體酥脆口感！","en":"Always buy \"Coarse\" Sweet Potato Starch, not fine powder. The bumpy texture is the secret to night-market crunch.","ja":"サツマイモ粉には「粗粒」と「細粒」があります。塩酥鶏には必ず【粗粒（粗顆粒）】を選んでください！","ko":"대만 고구마 전분은 '굵은 입자'와 '고운 입자'가 있습니다. 옌수지용은 무조건 【굵은 입자】를 골라야 합니다.","vi":"Hãy chọn đúng loại bột khoai lang 【Hạt To (Coarse)】 để có lớp vỏ giòn sần sùi chuẩn chợ đêm."},{"zh-TW":"胡椒鹽中加入微量（1小撮）肉桂粉與甘草粉，就是各大排隊名攤秘而不宣的「古早味中藥胡椒鹽」秘密！","en":"Add a micro-pinch of ground cinnamon and licorice powder into your salt-pepper mix for that legendary street cart aroma.","ja":"胡椒塩にシナモンパウダーと甘草粉をほんの耳かき一杯加えると、行列有名店の秘伝の味になります！","ko":"후추소금에 계피가루 한 꼬집을 더하면 대만 현지 맛집들의 특제 비법 양념 맛이 납니다.","vi":"Thêm một xíu bột quế vào muối tiêu sẽ tạo nên mùi thơm thảo mộc gia truyền quyến rũ."}]},{"country":"tw","id":"braised-pork-rice","slug":"braised-pork-rice","title":{"zh-TW":"古早味手切香菇滷肉飯","en":"Taiwanese Hand-Cut Braised Pork Rice (Lu Rou Fan)","ja":"台湾伝統 手切り豚バラ煮込みご飯（魯肉飯）","ko":"정통 손칼 루로우판 (대만식 돼지고기 덮밥)","vi":"Cơm thịt kho tàu nấm hương Đài Loan (Lu Rou Fan)"},"subtitle":{"zh-TW":"手切帶皮五花條・慢火熬出黏嘴膠質","en":"Hand-Cut Skin-on Pork Belly & Rich Collagen Glaze","ja":"手切り皮付き豚バラとじっくり煮込んだ極上コラーゲン","ko":"손칼로 썬 오겹살과 입안에 착 감기는 진한 콜라겐 소스","vi":"Thịt ba chỉ thái tay dẻo quánh ngập tràn collagen"},"tagline":{"zh-TW":"台灣人心目中永恆的第一名 Comfort Food","en":"The ultimate Taiwanese comfort food loved across generations","ja":"台湾人の心を掴んで離さない永遠のソウルフード","ko":"대만인들의 영원한 넘버원 소울푸드","vi":"Món ăn quốc dân an ủi tâm hồn người Đài Loan"},"heroImage":"/images/tw/braised-pork-rice.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":50,"defaultServings":4,"caloriesPerServing":580,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originCity":{"zh-TW":"全台灣 / 台南・台北","en":"All Taiwan / Tainan & Taipei","ja":"台湾全土 / 台南・台北","ko":"대만 전역 / 타이난・타이베이","vi":"Toàn Đài Loan / Đài Nam & Đài Bắc"},"famousNightMarkets":[{"zh-TW":"寧夏夜市 (圓環滷肉飯)","en":"Ningxia Night Market","ja":"寧夏夜市","ko":"닝샤 야시장","vi":"Chợ đêm Ningxia"},{"zh-TW":"南機場夜市","en":"Nanjichang Night Market","ja":"南機場夜市","ko":"난지창 야시장","vi":"Chợ đêm Nanjichang"}],"historyStory":{"zh-TW":"早期台灣物資匱乏，家庭主婦將零碎五花肉切丁，加入醬油、紅蔥酥慢火慢燉，讓全家都能用少許肉汁拌下好幾碗白飯。台灣北部偏鹹香深色，南部則偏甘甜帶紅糟香。","en":"Originating from humble beginnings where every cut of meat was precious, housewives chopped pork belly scraps into small cubes, braising them with soy sauce and fried shallots so a small pot could flavor bowls of rice for the whole family.","ja":"昔、貴重だった豚肉を余すことなく使うため、細かく刻んだ豚肉を揚げエシャロットや醤油でコトコト煮詰めたのが始まり。濃厚なタレでご飯が何杯でも進みます。","ko":"가족 모두가 적은 양의 고기로 밥을 배불리 먹을 수 있도록 삼겹살을 잘게 썰어 샬롯 튀김, 간장과 함께 조려 밥 위에 얹어 먹던 지혜에서 탄생한 국민 요리입니다.","vi":"Bắt nguồn từ sự tần tảo của người phụ nữ xưa, thái vụn thịt ba chỉ kho cùng hành phi và nước tương để chan cơm nuôi sống cả gia đình."},"taiwaneseHokkien":"Lóo-bah-pn̄g (ㄌㄛˋ ㄅㄚ ㄅㄥ)","mandarinPinyin":"Lǔròufàn (ㄌㄨˇ ㄖㄡˋ ㄈㄢˋ)","audioPronunciationText":"老闆，來一碗大滷肉飯加一顆滷蛋"},"ingredients":[{"id":"pork-belly","name":{"zh-TW":"帶皮豬五花肉 (手切肉條)","en":"Skin-on Pork Belly (Hand-Cut Strips)","ja":"皮付き豚バラ肉（手切り短冊状）","ko":"껍질 붙은 통삼겹살 (손칼 썰기)","vi":"Thịt ba chỉ có bì (Thái con chì)"},"amount":600,"unitMetric":"g","unitUS":"1.3 lbs","isKeyFlavor":true,"chineseName":"帶皮五花肉","chinesePinyin":"Dài pí wǔ huā ròu"},{"id":"fried-shallots","name":{"zh-TW":"台灣純手工油蔥酥 (紅蔥酥)","en":"Crispy Taiwanese Fried Shallots","ja":"台湾産 揚げエシャロット（油葱酥）","ko":"대만산 수제 튀긴 샬롯 (유총수)","vi":"Hành tím phi giòn Đài Loan"},"amount":60,"unitMetric":"g","unitUS":"0.8 cup","isKeyFlavor":true,"chineseName":"油蔥酥","chinesePinyin":"Yóu cōng sū","substitute":{"substituteName":{"zh-TW":"新鮮紅蔥頭切碎以豬油或植物油自炸","en":"Fresh Asian shallots thinly sliced & fried in oil until golden","ja":"生のエシャロット（赤玉ねぎ）を薄切りにして油で揚げる","ko":"신선한 샬롯(적양파)을 얇게 썰어 기름에 튀겨 사용","vi":"Tự phi hành tím tươi trong dầu đến khi vàng ruộm"},"ratio":"1:1","explanation":{"zh-TW":"油蔥酥是滷肉飯的「靈魂香氣基底」，不可用西式洋蔥酥或大蒜酥替代！若買不到現成，可買新鮮紅蔥頭自己小火炸酥。","en":"Fried shallots provide 80% of Lu Rou Fan's distinctive aroma. Do not use Western French's fried onions or garlic chips.","ja":"油葱酥は味の決め手です。手に入らない場合は赤エシャロットを油でじっくり揚げて作れます。","ko":"유총수는 루로우판의 영혼입니다. 서양식 어니언 크리스피나 마늘칩으로 대체하지 말고 샬롯을 직접 튀기세요.","vi":"Hành tím phi là linh hồn của món ăn, không thể thay bằng hành tây hay tỏi phi."},"whereToBuy":{"zh-TW":"大華超市、東南亞超市、Amazon (搜尋 Fried Red Shallots)","en":"99 Ranch, H-Mart, Southeast Asian groceries, Amazon","ja":"中華食材店、Amazon","ko":"아시안 마트, 온라인 쇼핑몰","vi":"Siêu thị châu Á hoặc chợ Việt"}}},{"id":"shiitake-mushrooms","name":{"zh-TW":"台灣乾香菇 (泡水切絲，香菇水保留)","en":"Dried Shiitake Mushrooms (Soaked & Sliced, reserve water)","ja":"干し椎茸（水戻しして細切り、戻し汁も使用）","ko":"건표고버섯 (불린 후 채썰기, 버섯 우린 물 사용)","vi":"Nấm hương khô (Ngâm nở thái sợi, giữ nước ngâm)"},"amount":6,"unitMetric":"piece","unitUS":"6 pieces","chineseName":"乾香菇","chinesePinyin":"Gān xiāng gū"},{"id":"taiwan-soy-paste","name":{"zh-TW":"台灣金蘭醬油膏 (或黑龍蔭油膏)","en":"Taiwanese Thick Soy Paste","ja":"台湾とろみ醤油（醤油膏 / ソイペースト）","ko":"대만 걸쭉한 간장소스 (장유고 / 김란)","vi":"Nước tương ngọt sệt Đài Loan (Soy Paste)"},"amount":40,"unitMetric":"ml","unitUS":"2.5 tbsp","isKeyFlavor":true,"chineseName":"醬油膏","chinesePinyin":"Jiàng yóu gāo","substitute":{"substituteName":{"zh-TW":"優質生抽 2大匙 + 蠔油 1大匙 + 冰糖 1茶匙","en":"Soy Sauce (2 tbsp) + Oyster Sauce (1 tbsp) + Sugar (1 tsp)","ja":"醤油大さじ2 ＋ オイスターソース大さじ1 ＋ 砂糖小さじ1","ko":"진간장 2큰술 + 굴소스 1큰술 + 설탕 1작은술","vi":"Nước tương (2 thìa) + Dầu hào (1 thìa) + Đường phèn (1 thìa cafe)"},"ratio":"1:1","explanation":{"zh-TW":"醬油膏比普通醬油更濃稠微甜，若無可用醬油+蠔油+糖調和出相似的稠亮甜鹹感。","en":"Taiwanese soy paste is thicker and sweeter. If not found, mixing soy sauce with oyster sauce and rock sugar replicates the gloss and rich sweet-savory profile.","ja":"醤油膏は甘みととろみがあります。オイスターソースと醤油・砂糖を合わせると近い仕上がりになります。","ko":"장유고는 진하고 달콤한 맛이 있습니다. 굴소스와 진간장, 설탕을 섞으면 매우 흡사합니다.","vi":"Pha nước tương với dầu hào và chút đường phèn để tạo độ sánh ngọt."},"whereToBuy":{"zh-TW":"大華超市、亞超、Amazon","en":"Asian supermarkets (Kimlan Soy Paste), Amazon","ja":"中華スーパー、Amazon","ko":"중국 식자재 마트","vi":"Siêu thị đồ Hoa"}}},{"id":"rock-sugar","name":{"zh-TW":"黃冰糖 (炒糖色用)","en":"Yellow Rock Sugar","ja":"黄氷砂糖","ko":"황설탕 또는 빙탕","vi":"Đường phèn vàng"},"amount":30,"unitMetric":"g","unitUS":"2 tbsp","chineseName":"冰糖","chinesePinyin":"Bīng táng"},{"id":"hard-boiled-eggs","name":{"zh-TW":"剝殼水煮蛋 (入味滷蛋)","en":"Hard-Boiled Eggs (for Braising)","ja":"ゆで卵（殻をむいたもの）","ko":"삶은 달걀 (껍질 깐 것)","vi":"Trứng gà luộc bóc vỏ"},"amount":4,"unitMetric":"piece","unitUS":"4 pieces","chineseName":"水煮蛋","chinesePinyin":"Shuǐ zhǔ dàn"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"五花肉汆燙與手切肉條","en":"Blanch Pork Belly & Hand-Cut Strips","ja":"豚肉の下茹でと手切りカット","ko":"삼겹살 데치기 및 손칼 썰기","vi":"Chần sơ thịt và thái con chì"},"instruction":{"zh-TW":"整塊帶皮五花肉冷水下鍋，加入薑片與米酒汆燙 5 分鐘去腥，撈出沖冷水。接著用刀切成約 0.7 公分寬、3 公分長的長條肉丁（不要用絞肉！手切才有膠質）。","en":"Place whole pork belly in cold water with ginger and rice wine. Bring to boil for 5 mins to remove scum, rinse with cold water. Slice into 0.7cm x 3cm strips (Hand-cut is essential for collagen—do not use ground meat!).","ja":"豚バラ肉の塊を生姜・酒と共に水から茹で、5分ほど下茹でしてアクを抜き水洗い。0.7cm×3cmほどの短冊状に手切りします（ひき肉ではなく手切りが美味しさの秘訣！）。","ko":"통삼겹살을 생강, 맛술과 함께 찬물에 넣고 5분간 끓여 불순물을 제거한 뒤 찬물에 헹굽니다. 0.7cm 두께로 칼로 길쭉하게 썹니다 (다짐육 대신 손칼로 썰어야 쫀득한 식감이 살아납니다).","vi":"Luộc sơ thịt ba chỉ 5 phút với gừng và rượu, rửa sạch. Dùng dao thái miếng con chì nhỏ dài (thái tay sẽ giữ được độ béo dẻo, không dùng thịt băm)."},"image":"/images/tw/lu-rou-step1.jpg","durationSeconds":420,"crucialTips":{"zh-TW":"汆燙後泡冰水肉質會變緊實，刀子更容易切出漂亮工整的五花肉條！","en":"Chilling the blanched pork belly in ice water makes it firm and super easy to cut straight strips.","ja":"下茹で後に冷水で冷やすとお肉が締まり、綺麗に切りやすくなります。","ko":"데친 후 얼음물에 담가두면 고기가 단단해져 깔끔하게 썰기 쉽습니다.","vi":"Ngâm nước đá sau khi chần giúp thịt săn chắc, dễ thái đều đẹp."}},{"stepNumber":2,"title":{"zh-TW":"煸炒出油與冰糖炒糖色","en":"Render Pork Fat & Caramelize Sugar","ja":"豚の脂をじっくり炒め＆氷砂糖で照りを出す","ko":"삼겹살 기름 내기 및 설탕 캐러멜라이징","vi":"Xào săn thịt & Đảo đường phèn tạo màu"},"instruction":{"zh-TW":"鍋中不放油，下五花肉條中火煸炒約 6~8 分鐘，逼出多餘油脂且肉邊緣微焦香。加入冰糖一同翻炒至糖融化包裹肉條，呈現琥珀色油亮光澤。","en":"In a dry pan, stir-fry pork strips over medium heat for 6-8 mins to render out natural fat until edges are lightly browned. Add rock sugar and stir until melted and amber glossy.","ja":"油を引かずに鍋に豚肉を入れ、中火で6〜8分炒めて余分な脂を出し香ばしく炒めます。氷砂糖を加えて溶かし、全体に琥珀色の照りをまとわせます。","ko":"마른 팬에 썬 삼겹살을 넣고 중불에서 6~8분간 볶아 기름을 빼고 노릇하게 굽습니다. 빙탕(설탕)을 넣고 녹여 고기에 반짝이는 캐러멜 색을 입힙니다.","vi":"Cho thịt vào chảo không cần dầu, đảo lửa vừa 6-8 phút cho ra bớt mỡ. Cho đường phèn vào đảo tan tạo màu cánh gián óng ả."},"image":"/images/tw/lu-rou-step2.jpg","durationSeconds":480},{"stepNumber":3,"title":{"zh-TW":"爆香香菇、油蔥酥與熗醬油","en":"Add Mushrooms, Fried Shallots & Aromatics","ja":"椎茸・油葱酥・醤油を投入して香り爆発","ko":"표고버섯, 샬롯튀김, 간장 붓고 향 입히기","vi":"Thêm nấm hương, hành phi và phi thơm nước tương"},"instruction":{"zh-TW":"加入泡軟的香菇丁、蒜末炒香，沿著鍋邊淋入醬油與醬油膏熗出焦香氣。接著倒入米酒、五香粉、白胡椒粉與靈魂「油蔥酥」翻炒均勻，瞬間香氣四溢！","en":"Add diced shiitake mushrooms and garlic. Pour soy sauce and soy paste around the pan edge to scorch aroma. Add rice wine, five-spice, white pepper, and the fried shallots, stirring well.","ja":"戻した椎茸とニンニクを加え、鍋肌から醤油と醤油膏を回し入れて香ばしさを引き出します。酒、五香粉、白胡椒、そして秘伝の油葱酥を加えて一気に炒め合わせます！","ko":"불린 표고버섯과 마늘을 넣고 볶다가 팬 가장자리에 간장과 장유고를 둘러 불향을 냅니다. 맛술, 오향분, 백후추, 그리고 튀긴 샬롯을 넣고 골고루 볶아줍니다.","vi":"Cho nấm hương, tỏi vào đảo thơm. Rưới nước tương quanh thành chảo tạo mùi thơm cháy cạnh, cho rượu nấu, ngũ vị hương và hành phi vào đảo đều."},"image":"/images/tw/lu-rou-step3.jpg","durationSeconds":180},{"stepNumber":4,"title":{"zh-TW":"慢火慢燉或壓力鍋壓製 (入味軟嫩)","en":"Slow Simmer or Instant Pot (Melt-in-Mouth)","ja":"じっくりコトコト煮込み（または圧力鍋調理）","ko":"뭉근하게 끓이기 또는 압력솥 조리","vi":"Ninh nhỏ lửa hoặc dùng nồi áp suất"},"instruction":{"zh-TW":"加入香菇水與清水（淹過肉表面），放入剝殼水煮蛋。大火煮滾後轉微小火，加蓋慢火慢燉 45~60 分鐘至肉質軟爛、帶皮五花肉溶出濃稠黏嘴的膠質精華。","en":"Traditional Pot: Add reserved mushroom water and water to cover pork. Add boiled eggs. Bring to boil, then simmer on low heat for 50 mins until collagen thickens.\nInstant Pot: High Pressure for 25 mins, Natural Release.","ja":"【普通鍋】：椎茸の戻し汁と水をひたひたに加え、ゆで卵を投入。沸騰後、弱火で蓋をして45〜60分コトコト煮込みます。\n【電気圧力鍋】：高圧で25分加熱後、自然減圧。","ko":"【일반 냄비】：버섯 우린 물과 물을 고기가 잠기도록 붓고 삶은 달걀을 넣습니다. 끓어오르면 약불로 줄여 뚜껑 덮고 50분간 뭉근히 조려줍니다.\n【인스턴트팟】：고압(High Pressure)으로 25분 조리 후 자연 감압.","vi":"Nồi thường: Đổ nước ngâm nấm và nước lọc xăm xắp mặt thịt, thả trứng luộc vào. Đun sôi rồi hạ lửa nhỏ ninh 50 phút.\nNồi áp suất: Chọn High Pressure 25 phút, xả van tự nhiên."},"image":"/images/tw/lu-rou-step4.jpg","durationSeconds":3000,"cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Manual High Pressure: 25 mins + Natural Release","instructionOverride":{"zh-TW":"在 Instant Pot 內膽中先用 Sauté 模式煸肉與爆香，加水與水煮蛋後鎖上鍋蓋，設定 Meat/Stew 或 High Pressure 25 分鐘，完成後自然洩壓。打開後肉入口即化！","en":"Use Instant Pot Sauté mode to brown pork and aromatics. Add liquid and eggs. Lock lid, set High Pressure for 25 mins, then Natural Release for velvety tenderness.","ja":"Sauté（炒め）モードで具材を炒めた後、水と卵を加えて蓋をし、高圧で25分加熱。圧力が自然に抜けるまで待てば、とろける柔らかさに！","ko":"인스턴트팟 Sauté 모드로 볶은 후 물과 달걀을 넣고 뚜껑을 닫습니다. High Pressure 25분 설정 후 자연 감압하면 고기가 사르르 녹아내립니다.","vi":"Dùng chế độ Sauté xào thịt, thêm nước và trứng rồi chọn High Pressure 25 phút, để xả van tự nhiên."}}]},{"stepNumber":5,"title":{"zh-TW":"淋在熱騰騰白飯上，搭配滷蛋黃瓜！","en":"Ladle over Steamed Rice & Garnish","ja":"炊きたてご飯にたっぷりかけて召し上がれ！","ko":"따뜻한 쌀밥 위에 듬뿍 얹어 완성!","vi":"Múc chan lên cơm trắng nóng hổi và thưởng thức!"},"instruction":{"zh-TW":"盛一碗熱氣騰騰的越光米或壽司米白飯，淋上兩大勺濃郁油亮的滷肉與湯汁，切開半顆入味的滷蛋，放上黃金醃黃瓜片或燙青菜，拌勻大口享用！","en":"Scoop hot steamed jasmine/short-grain rice into a bowl. Ladle 2 generous spoonfuls of glossy braised pork sauce over top. Slice a braised egg in half, add pickled cucumber, and enjoy!","ja":"熱々のご飯の上にツヤツヤのルーローをたっぷりかけます。半分に切った煮卵とたくあん（または青菜）を添え、よく混ぜてお召し上がりください！","ko":"갓 지은 따뜻한 밥 위에 윤기 흐르는 루로우 소스를 듬뿍 얹고, 조린 달걀과 절인 오이를 곁들여 쓱쓱 비벼 드세요!","vi":"Xới bát cơm nóng dẻo, chan 2 muôi thịt kho óng ánh đậm đà, bổ đôi quả trứng ngấm sốt, ăn kèm dưa leo muối chua giải ngấy."},"image":"/images/tw/braised-pork-rice.jpg","durationSeconds":60}],"troubleshooting":[{"id":"ts-lr-1","problem":{"zh-TW":"滷肉吃起來太油膩，沒有黏嘴的膠質感覺？","en":"Why is the braised pork too greasy instead of sticky-collagen rich?","ja":"脂っこいだけで、唇にまとわりつくようなコラーゲン感が出ない？","ko":"기름지기만 하고 쫀득한 콜라겐 식감이 덜한 이유는?","vi":"Tại sao sốt thịt bị ngấy mỡ chứ không có độ keo dính môi?"},"cause":{"zh-TW":"沒有買「帶皮」五花肉，或是五花肉煸炒時間不夠，油脂未被逼出。","en":"Missing the pig skin (which contains all collagen) or didn’t render pork fat long enough at start.","ja":"「皮付き」の豚肉を使っていないか、最初の炒めで脂をしっかり出さなかったためです。","ko":"껍질이 없는 부위를 사용했거나 처음에 기름을 충분히 뽑아내지 않았기 때문입니다.","vi":"Không dùng thịt có bì (da heo là nơi chứa collagen tạo độ dẻo) hoặc chưa xào kỹ cho ra bớt mỡ."},"solution":{"zh-TW":"請務必選擇帶豬皮的五花肉；若買不到帶皮肉，可在燉煮時丟入一小塊乾木耳或豬皮丁同煮。","en":"Always ask butcher for skin-on pork belly. If skinless, add a small piece of pork rind or rehydrated wood ear fungus.","ja":"必ず皮付き豚バラを選びましょう。手に入らない場合は豚皮の小片を一緒に煮込むと解決します。","ko":"가급적 껍질이 붙은 오겹살을 선택하세요. 껍질이 없다면 물에 불린 목이버섯을 잘게 썰어 넣어도 쫀득해집니다.","vi":"Hãy chọn thịt ba chỉ có bì. Nếu không có bì, có thể cho thêm chút mộc nhĩ băm nhỏ để tạo độ sánh dính."}}],"proTips":[{"zh-TW":"滷肉飯的湯汁如果放隔夜，油脂會凝固浮在表面，撈掉白油後再加熱，味道比第一天更加濃郁醇厚！","en":"Lu Rou Fan tastes even better the next day! Refrigerate overnight, skim off solidified top fat, and reheat for richer, cleaner flavor.","ja":"一晩寝かせると余分な脂が白く固まるのでスプーンで取り除けます。2日目のほうが味が染みて格段に美味しくなります！","ko":"루로우판은 하루 숙성시켰을 때 가장 맛있습니다! 냉장고에 넣어 굳은 기름을 걷어내고 다시 데우면 담백하고 진한 맛이 납니다.","vi":"Thịt kho để qua đêm hôm sau hớt bớt mỡ đông rồi đun lại sẽ càng đậm đà thơm ngon gấp bội!"}]},{"country":"tw","id":"boba-milk-tea","slug":"boba-milk-tea","title":{"zh-TW":"手炒黑糖珍珠鮮奶茶","en":"Taiwanese Brown Sugar Boba Fresh Milk","ja":"手炒り黒糖タピオカ生ミルクティー","ko":"수제 흑당 버블 생우유 (흑당 버블티)","vi":"Sữa tươi trân châu đường đen Đài Loan"},"subtitle":{"zh-TW":"現煮手作粉圓・黑糖琥珀虎紋掛杯","en":"Warm Chewy Tapioca Pearls & Dripping Tiger Stripes","ja":"手作りモチモチ生タピオカと美しい黒糖の虎模様","ko":"갓 삶은 수제 펄과 흘러내리는 흑당 호랑이 무늬","vi":"Trân châu dẻo quánh nấu tươi & Vân hổ phách đẹp mắt"},"tagline":{"zh-TW":"風靡全世界的台灣之光，掌握熱珍珠與冰鮮奶的冰火交融","en":"The global sensation: warm caramel pearls meet ice-cold fresh milk","ja":"世界中で大ブームを巻き起こした台湾スイーツの最高峰","ko":"전 세계를 사로잡은 대만의 자부심, 따뜻한 펄과 차가운 생우유의 조화","vi":"Cơn sốt trà sữa toàn cầu đến từ Đài Loan"},"heroImage":"/images/tw/boba-milk-tea.jpg","difficulty":"hard","prepTimeMinutes":30,"cookTimeMinutes":40,"defaultServings":2,"caloriesPerServing":360,"category":"desserts","dietaryTags":["vegetarian","halal","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台中 / 台南","en":"Taichung / Tainan","ja":"台中 / 台南","ko":"타이중 / 타이난","vi":"Đài Trung / Đài Nam"},"famousNightMarkets":[{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"},{"zh-TW":"公館夜市 (陳三鼎創始地)","en":"Gongguan Night Market","ja":"公館夜市","ko":"궁관 야시장","vi":"Chợ đêm Gongguan"}],"historyStory":{"zh-TW":"珍珠奶茶源自1980年代的台中春水堂與台南翰林茶館。而「黑糖珍珠鮮奶」更是將古法炒黑糖的焦香發揮到極致，完全不加一滴茶湯，以純鮮奶的濃醇襯托黑糖蜜珍珠的溫熱軟Q。","en":"Invented in the 1980s in Taiwan, modern Brown Sugar Boba elevates the craft by caramelizing pure cane sugar with hand-rolled tapioca balls, served without tea in rich whole milk.","ja":"1980年代に台湾で誕生。黒糖タピオカミルクは茶葉を使わず、じっくり煮詰めた温かい黒糖タピオカに冷たい濃厚ミルクを注ぎ、温度差を楽しむ進化系ドリンクです。","ko":"1980년대 대만에서 탄생한 버블티의 정점입니다. 찻물 없이 진하게 졸인 따뜻한 흑당 펄에 신선한 생우유를 부어 입안에서 퍼지는 온도 차와 쫄깃함을 즐깁니다.","vi":"Ra đời từ thập niên 1980 tại Đài Loan, món sữa tươi trân châu đường đen trứ danh kết hợp trân châu ấm nóng nấu đường mía cùng sữa tươi thanh trùng mát lạnh."},"taiwaneseHokkien":"Tsin-tsu Leng-tê (ㄗㄣ ㄗㄨ ㄌㄧㄥˊ ㄉㄟˊ)","mandarinPinyin":"Zhēnzhū Nǎichá (ㄓㄣ ㄓㄨ ㄋㄞˇ ㄔㄚˊ)","audioPronunciationText":"老闆，一杯黑糖珍珠鮮奶，微冰不加糖"},"ingredients":[{"id":"tapioca-starch","name":{"zh-TW":"木薯粉 (樹薯粉 / 菱粉)","en":"Tapioca Starch (Pure Cassava)","ja":"タピオカ粉（キャッサバ粉）","ko":"타피오카 전분","vi":"Bột năng (Bột sắn củ mì)"},"amount":100,"unitMetric":"g","unitUS":"0.7 cup","isKeyFlavor":true,"chineseName":"木薯粉","chinesePinyin":"Mù shǔ fěn","substitute":{"substituteName":{"zh-TW":"泰國進口木薯粉 (Tapioca Starch)","en":"Thai Tapioca Starch / Flour","ja":"タイ産タピオカ粉","ko":"태국산 타피오카 전분","vi":"Bột năng Thái Lan"},"ratio":"1:1","explanation":{"zh-TW":"做珍珠粉圓【絕對不能用玉米粉或太白粉】替代！只有純木薯粉才能在高溫燙麵後產生水晶般的Q彈嚼勁。","en":"Must use 100% Tapioca Starch. Cornstarch or potato starch WILL FAIL to produce the chewy \"Q\" texture.","ja":"タピオカ作りには【片栗粉やコーンスターチは不可】です。必ず純タピオカ粉を使用してください。","ko":"옥수수전분이나 감자전분은 절대 안 됩니다. 오직 100% 타피오카 전분만 특유의 쫄깃한 Q감을 냅니다.","vi":"Bắt buộc dùng 100% bột năng, bột bắp hay bột khoai tây sẽ không thể dai dẻo."},"whereToBuy":{"zh-TW":"各大超市烘焙區、東南亞超市 (三象牌)","en":"Asian/Hispanic grocery baking aisle (E.g. Cock Brand, Bob's Red Mill)","ja":"業務スーパー、カルディ、アジア食材店","ko":"대형 마트 제과제빵 코너, 아시안 마켓","vi":"Các siêu thị hoặc tiệm làm bánh"}}},{"id":"taiwan-brown-sugar","name":{"zh-TW":"台灣純黑糖 (或沖繩黑糖)","en":"Taiwan Dark Brown Sugar / Muscovado","ja":"純黒糖（台湾産または沖縄黒糖）","ko":"대만 순수 흑설탕 (원당)","vi":"Đường đen nguyên chất Đài Loan"},"amount":80,"unitMetric":"g","unitUS":"0.4 cup","isKeyFlavor":true,"chineseName":"黑糖","chinesePinyin":"Hēi táng"},{"id":"fresh-whole-milk","name":{"zh-TW":"優質全脂鮮奶","en":"Whole Fresh Milk (or Oat Milk)","ja":"濃厚な成分無調整牛乳","ko":"신선한 전지 생우유","vi":"Sữa tươi thanh trùng nguyên kem"},"amount":400,"unitMetric":"ml","unitUS":"1.7 cups","chineseName":"全脂鮮奶","chinesePinyin":"Quán zhī xiān nǎi"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"煮沸黑糖水與燙麵團 (防失敗第一要訣)","en":"Boil Brown Sugar & Gelatinize Dough (Key!)","ja":"黒糖水を沸騰させて「湯ごね」する（最重要！）","ko":"흑당물 끓여 익반죽하기 (실패 방지 핵심!)","vi":"Đun sôi nước đường đen và lấy bột chín (Bí quyết cốt lõi)"},"instruction":{"zh-TW":"將 35g 黑糖與 60ml 水倒入小鍋中，大火煮至「完全滾沸」（劇烈冒大泡泡）。立刻熄火，一口氣倒入全部樹薯粉，迅速用筷子攪拌成絮狀。","en":"Combine 35g brown sugar and 60ml water in a small pot. Bring to a ROARING BOIL (big rapid bubbles). Turn off heat, dump in ALL tapioca starch immediately, and stir vigorously with chopsticks.","ja":"小鍋に黒糖35gと水60mlを入れ、強火で「完全にグラグラ沸騰」させます。火を止め、タピオカ粉を一気に全量投入して箸で手早く混ぜます。","ko":"작은 냄비에 흑설탕 35g과 물 60ml를 넣고 팔팔 끓여 완전히 기포가 올라올 때 불을 끄고, 타피오카 전분을 한 번에 부어 젓가락으로 빠르게 섞어줍니다.","vi":"Cho 35g đường đen và 60ml nước vào nồi nhỏ đun SÔI SÙNG SỤC. Tắt bếp, đổ toàn bộ bột năng vào khuấy nhanh tay."},"image":"/images/tw/boba-step1.jpg","durationSeconds":180,"dangerWarnings":{"zh-TW":"⚠️ 水溫不夠高會導致澱粉無法糊化（變成非牛頓流體水漿）。水一定要滾沸狀態立刻下粉！","en":"⚠️ The water MUST be boiling hot! If lukewarm, the starch turns into a puddle of non-Newtonian fluid instead of dough.","ja":"⚠️ お湯が沸騰していないと、粉が固まらずドロドロの液体になって失敗します。必ずグラグラ煮立った状態で粉を入れてください！","ko":"⚠️ 물이 팔팔 끓지 않은 상태에서 전분을 넣으면 반죽이 되지 않고 물처럼 풀어집니다. 반드시 100°C 끓는 물이어야 합니다!","vi":"⚠️ Nước BẮT BUỘC phải sôi sùng sục, nếu nước nguội bột sẽ bị chảy lỏng không nhồi được."}},{"stepNumber":2,"title":{"zh-TW":"揉勻麵團與搓揉珍珠粉圓","en":"Knead Dough & Roll Boba Pearls","ja":"生地をこねて小さな丸に成形する","ko":"반죽 치대기 및 동글동글 펄 빚기","vi":"Nhồi bột dẻo mịn và vo viên trân châu"},"instruction":{"zh-TW":"將麵絮倒在案板上，趁溫熱用手揉壓成光滑不黏手的深褐色麵團。搓成長細條，用切麵刀切成小丁，再用手掌心搓成直徑約 0.8 公分的小圓球，撒少許乾粉防黏。","en":"Turn dough onto board while warm. Knead into a smooth, elastic dark brown dough. Roll into long skinny ropes, cut into small cubes, and roll between palms into 0.8cm boba balls. Dust lightly with dry starch.","ja":"温かいうちに手で滑らかになるまでこねます。細長い棒状に伸ばして包丁で小さくカットし、手のひらで直径0.8cmの丸い粒に丸めます。くっつかないよう粉をまぶします。","ko":"따뜻할 때 손으로 매끄럽고 찰진 반죽이 될 때까지 치댑니다. 얇고 길게 늘여 작은 큐브 모양으로 자른 뒤, 손바닥으로 굴려 0.8cm 구슬 모양으로 빚고 덧가루를 뿌려둡니다.","vi":"Nhồi bột khi còn ấm đến khi mịn không dính tay. Se thành sợi dài, cắt hạt lựu và vo tròn cỡ 0.8cm. Áo một lớp bột khô chống dính."},"image":"/images/tw/boba-step2.jpg","durationSeconds":600},{"stepNumber":3,"title":{"zh-TW":"煮珍珠與悶煮 (Q彈關鍵)","en":"Boil & Steam Pearls (The Q-Bounce)","ja":"タピオカを茹でてしっかり蒸らす（モチモチの秘訣）","ko":"펄 삶기 및 뜸 들이기 (쫄깃함의 완성)","vi":"Luộc và ủ trân châu (Bí quyết dẻo quánh)"},"instruction":{"zh-TW":"鍋中加入大半鍋水（約珍珠量的8倍）煮滾，下珍珠輕輕攪拌防黏底。大火煮 20 分鐘後熄火，加蓋悶 20 分鐘。撈出過冷開水沖洗瀝乾，口感瞬間變得超級Q彈！","en":"Bring a large pot of water (8x pearl volume) to boil. Add pearls, stirring gently. Boil on medium-high for 20 mins, turn off heat, cover and let STEAM for 20 mins. Rinse under ice-cold water to lock in chewy texture!","ja":"たっぷりの湯（タピオカの8倍）を沸かし、タピオカを入れて底にくっつかないよう混ぜます。中火で20分茹でた後、火を止め蓋をして20分蒸らします。冷水でサッと洗って水気を切ります。","ko":"넉넉한 물을 끓여 펄을 넣고 가볍게 저어줍니다. 중불에서 20분간 삶은 후 불을 끄고 뚜껑 덮어 20분간 뜸을 들입니다. 찬물에 헹궈 탱글탱글한 식감을 살립니다.","vi":"Đun nhiều nước sôi, thả trân châu vào khuấy nhẹ. Luộc lửa vừa 20 phút, tắt bếp đậy vung ủ 20 phút. Vớt ra xả nước đá lạnh cho trân châu giòn dẻo."},"image":"/images/tw/boba-step3.jpg","durationSeconds":2400},{"stepNumber":4,"title":{"zh-TW":"黑糖蜜慢熬蜜珍珠","en":"Simmer in Thick Brown Sugar Syrup","ja":"黒糖シロップで濃厚に煮絡める","ko":"흑당 시럽에 졸여 펄에 당 입히기","vi":"Nấu trân châu với siro đường đen sệt"},"instruction":{"zh-TW":"小鍋中加入剩餘 45g 黑糖與 50ml 水煮溶，倒入瀝乾的珍珠。以小火慢熬翻煮約 5~8 分鐘，直到黑糖漿變得濃稠如蜂蜜般包裹住每顆珍珠。","en":"In a pan, melt 45g brown sugar with 50ml water. Add the cooked pearls and simmer over low heat for 5-8 mins until the syrup becomes thick and glossy like liquid honey.","ja":"鍋に残りの黒糖45gと水50mlを熱して溶かし、タピオカを加えます。弱火で5〜8分コトコト煮詰めて、ハチミツのように濃厚にとろみがつくまで絡めます。","ko":"팬에 남은 흑설탕 45g과 물 50ml를 넣고 끓이다가 삶은 펄을 넣습니다. 약불에서 5~8분간 졸여 시럽이 꿀처럼 걸쭉하게 코팅되도록 만듭니다.","vi":"Đun 45g đường đen với 50ml nước cho tan, trút trân châu vào rim lửa nhỏ 5-8 phút đến khi siro sánh kẹo bám đều."},"image":"/images/tw/boba-step4.jpg","durationSeconds":480},{"stepNumber":5,"title":{"zh-TW":"旋轉掛杯、注入鮮奶！","en":"Swirl Tiger Stripes & Pour Cold Milk","ja":"カップを傾けて虎模様を作り、ミルクを注ぐ！","ko":"컵 벽면에 호랑이 무늬 두르고 차가운 우유 붓기!","vi":"Tạo vân đường đen hổ phách và rót sữa tươi!"},"instruction":{"zh-TW":"趁溫熱舀入兩大勺濃稠黑糖珍珠至玻璃杯底，將杯子傾斜 45 度旋轉一圈，讓黑糖漿在杯壁流淌出絕美「虎紋」。加入滿滿冰塊，倒入冰涼全脂鮮奶，大功告成！","en":"Spoon 2-3 big scoops of warm brown sugar pearls into cup. Tilt and rotate glass 45° so sticky syrup drips down cup walls forming \"Tiger Stripes\". Add ice cubes to brim, pour ice-cold fresh milk, and enjoy!","ja":"温かいタピオカをカップの底に入れ、カップを傾けて回しながら側面にシロップの「虎模様」を描きます。氷をたっぷり入れ、冷たい牛乳を注いで完成！","ko":"따뜻한 흑당 펄을 컵 바닥에 담고, 컵을 기울여 돌려가며 벽면에 흑당 시럽 무늬를 만듭니다. 얼음을 가득 채우고 차가운 생우유를 부어주면 완성!","vi":"Múc trân châu ấm nóng vào ly, nghiêng ly lăn tròn tạo vân hổ phách. Thêm đá viên đầy miệng ly rồi rót sữa tươi không đường lạnh vào."},"image":"/images/tw/boba-milk-tea.jpg","durationSeconds":120}],"troubleshooting":[{"id":"ts-bb-1","problem":{"zh-TW":"麵團加水後變成一灘水漿，完全無法成團？","en":"Why did my dough turn into a liquid puddle instead of a solid ball?","ja":"粉に水分を加えたらドロドロの液体になってまとまらない？","ko":"반죽이 뭉쳐지지 않고 물처럼 흘러내리나요?","vi":"Tại sao bột bị chảy lỏng không nhồi thành khối được?"},"cause":{"zh-TW":"黑糖水溫度不夠高（未達到100°C沸騰即下粉），木薯澱粉未能完成預糊化。","en":"The liquid was not at a roaring boil. Tapioca starch needs near 100°C heat to gelatinize.","ja":"黒糖水がしっかり沸騰していなかったため、タピオカ粉が糊化（α化）しなかったのが原因です。","ko":"흑당물이 100°C로 팔팔 끓지 않은 상태에서 전분을 부어 전분이 호화되지 못했습니다.","vi":"Nước đường chưa sôi sùng sục đã đổ bột vào khiến bột không chín nở."},"solution":{"zh-TW":"挽救法：將整鍋濕漿放回瓦斯爐上，開極小火快速攪拌 15 秒，澱粉遇熱會瞬間抱團，立刻離火揉捏！","en":"Rescue Fix: Put saucepan back on ultra-low heat, stir continuously for 15s until it instantly solidifies into elastic dough!","ja":"救済法：鍋を極弱火にかけ、ヘラで素早く混ぜると15秒ほどで急に固まってまとまります！","ko":"응급 처치：냄비를 약불에 올리고 15초간 빠르게 저어주면 순식간에 덩어리로 뭉쳐집니다!","vi":"Cứu bột: Đặt lại nồi lên bếp lửa thật nhỏ, đảo nhanh 15 giây bột sẽ đặc quánh lại ngay."}}],"proTips":[{"zh-TW":"黑糖珍珠一定要「現煮現吃」，溫熱的珍珠遇到冰鮮奶會在外層形成一層脆彈保護膜，咬下去又軟又糯！","en":"Serve warm pearls fresh! The hot-and-cold shock against iced milk creates that legendary heavenly mouthfeel.","ja":"黒糖タピオカは温かいうちに冷たいミルクと合わせるのが鉄則。温度差で極上の食感が生まれます！","ko":"흑당 펄은 갓 만들어 따뜻할 때 차가운 우유와 만나야 겉은 탱글하고 속은 부드러운 극상의 맛이 납니다.","vi":"Thưởng thức khi trân châu còn ấm với sữa lạnh để cảm nhận độ dẻo mềm hoàn hảo."}]},{"country":"tw","id":"oyster-omelet","slug":"oyster-omelet","title":{"zh-TW":"夜市招牌蚵仔煎","en":"Taiwanese Night Market Oyster Omelet","ja":"夜市名物 台湾風牡蠣オムレツ（蚵仔煎）","ko":"대만 야시장 대표 굴전 (오아젠)","vi":"Hàu chiên trứng sốt hồng Đài Loan (Oyster Omelet)"},"subtitle":{"zh-TW":"邊緣焦脆粉漿軟Q・特製粉紅甜辣醬","en":"Crispy Lace Edges, Chewy Starch & Special Pink Sauce","ja":"フチはカリカリ中はモチモチ＆特製ピンク甘辛ダレ","ko":"가장자리는 바삭 속은 쫀득＆특제 분홍 칠리소스","vi":"Viền giòn rụm bột dai dẻo & Sốt hồng chua ngọt thần thánh"},"tagline":{"zh-TW":"米其林必比登夜市小吃常客，肥美鮮蚵與青菜的完美交融","en":"Michelin Bib Gourmand regular featuring plump ocean oysters","ja":"ミシュラン・ビブグルマン常連。プリプリの牡蠣とシャキシャキ青菜の共演","ko":"미슐랭 빕구르망 단골 메뉴, 싱싱한 굴과 채소의 황금 조합","vi":"Món ăn đạt chuẩn Michelin Bib Gourmand với hàu tươi béo ngậy"},"heroImage":"/images/tw/oyster-omelet.jpg","difficulty":"medium","prepTimeMinutes":15,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":380,"category":"mains","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台南安平 / 台北","en":"Tainan Anping / Taipei","ja":"台南・安平 / 台北","ko":"타이난 안핑 / 타이베이","vi":"Đài Nam An Bình / Đài Bắc"},"famousNightMarkets":[{"zh-TW":"寧夏夜市 (圓環邊蚵仔煎)","en":"Ningxia Night Market","ja":"寧夏夜市","ko":"닝샤 야시장","vi":"Chợ đêm Ningxia"},{"zh-TW":"士林夜市","en":"Shilin Night Market","ja":"士林夜市","ko":"스린 야시장","vi":"Chợ đêm Shilin"}],"historyStory":{"zh-TW":"相傳1661年鄭成功攻打荷蘭人時缺糧，軍隊就地取材以沿海鮮蚵、地瓜粉水與雞蛋煎熟裹腹，演變至今成為全台夜市代表性美食。靈魂粉紅海山醬是由番茄醬、味噌、醬油膏與糖調製而成。","en":"Legend has it that in 1661, General Koxinga faced food shortages while besieging Dutch forces, mixing coastal oysters with sweet potato slurry to feed his army. The signature pink sweet-chili sauce is a blend of ketchup, miso, and soy paste.","ja":"1661年、鄭成功の軍隊が食料不足の際に沿岸の牡蠣とさつまいも粉を水で溶いて焼いたのが起源と伝えられます。ピンク色の甘辛ダレ（海山醤）が美味しさを引き立てます。","ko":"1661년 정성공 장군 군대의 식량 부족을 해결하기 위해 해안가의 굴과 고구마 전분을 섞어 부쳐 먹은 것에서 유래했습니다. 특유의 달콤매콤한 분홍 소스가 일품입니다.","vi":"Tương truyền năm 1661 khi thiếu lương thực, tướng Trịnh Thành Công đã dùng hàu biển và bột khoai lang tráng bánh nuôi quân, tạo nên món ăn trứ danh."},"taiwaneseHokkien":"Ô-á-tsian (ㄛˊ ㄚˋ ㄐㄧㄢ)","mandarinPinyin":"Kē Zǎi Jiān (ㄎㄜ ㄗˇ ㄐㄧㄢ)","audioPronunciationText":"老闆，一份蚵仔煎，醬多一點菜多一點"},"ingredients":[{"id":"fresh-oysters","name":{"zh-TW":"新鮮鮮蚵 (生蠔肉)","en":"Fresh Shucked Oysters","ja":"生牡蠣（加熱用または生食用）","ko":"싱싱한 생굴","vi":"Ruột hàu tươi sống"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"chineseName":"鮮蚵","chinesePinyin":"Xiān kē"},{"id":"sweet-potato-starch-powder","name":{"zh-TW":"地瓜粉 (番薯粉)","en":"Sweet Potato Starch","ja":"さつまいも粉（地瓜粉）","ko":"고구마 전분","vi":"Bột khoai lang"},"amount":30,"unitMetric":"g","unitUS":"3 tbsp","isKeyFlavor":true,"chineseName":"地瓜粉","chinesePinyin":"Dì guā fěn"},{"id":"potato-starch","name":{"zh-TW":"太白粉 (馬鈴薯澱粉)","en":"Potato Starch","ja":"片栗粉","ko":"감자 전분","vi":"Bột khoai tây / Bột năng"},"amount":10,"unitMetric":"g","unitUS":"1 tbsp","chineseName":"太白粉","chinesePinyin":"Tài bái fěn"},{"id":"eggs","name":{"zh-TW":"新鮮雞蛋","en":"Fresh Eggs","ja":"卵","ko":"달걀","vi":"Trứng gà tươi"},"amount":2,"unitMetric":"piece","unitUS":"2 pieces","chineseName":"雞蛋","chinesePinyin":"Jī dàn"},{"id":"bok-choy","name":{"zh-TW":"小白菜 (或茼蒿 / 豆芽菜)","en":"Bok Choy or Crown Daisy (Tong Ho)","ja":"チンゲン菜 または 春菊","ko":"청경채 또는 쑥갓","vi":"Cải thìa hoặc rau cúc tần"},"amount":100,"unitMetric":"g","unitUS":"1 cup","chineseName":"小白菜","chinesePinyin":"Xiǎo bái cài"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製黃金比例粉漿與特製醬汁","en":"Mix Starch Batter & Special Pink Sauce","ja":"黄金粉漿と特製ソースを準備する","ko":"황금 전분물 및 특제 소스 만들기","vi":"Pha bột vàng và nấu sốt hồng"},"instruction":{"zh-TW":"碗中混合地瓜粉 30g、太白粉 10g、水 100ml、少許鹽與白胡椒攪勻備用。\n【醬汁調製】：小鍋中將番茄醬 2匙、味噌 1茶匙、糖 1.5匙、醬油膏 1匙與水 80ml 煮滾，勾薄芡備用。","en":"Mix 30g sweet potato starch, 10g potato starch, 100ml water, pinch of salt. For Sauce: Boil 2 tbsp ketchup, 1 tsp miso, 1.5 tbsp sugar, 1 tbsp soy paste, and 80ml water. Thicken with starch slurry.","ja":"ボウルにサツマイモ粉30g、片栗粉10g、水100ml、塩胡椒少々を混ぜておきます。ソース：ケチャップ大さじ2、味噌小さじ1、砂糖大さじ1.5、水80mlを一煮立ちさせ水溶き片栗粉でとろみをつけます。","ko":"볼에 고구마전분 30g, 감자전분 10g, 물 100ml, 소금 후추를 섞어둡니다. 소스：케첩 2스푼, 된장 1작은술, 설탕 1.5스푼, 물 80ml를 끓여 전분물로 걸쭉하게 만듭니다.","vi":"Pha 30g bột khoai lang, 10g bột năng, 100ml nước. Sốt: Đun sôi 2 thìa ketchup, 1 thìa cafe miso, 1.5 thìa đường, 80ml nước và làm sệt bằng chút bột năng."},"image":"/images/tw/oyster-omelet-step1.jpg","durationSeconds":300},{"stepNumber":2,"title":{"zh-TW":"熱鍋煎蚵仔與淋下粉漿","en":"Sear Oysters & Pour Batter","ja":"牡蠣をサッと炒め、生地を回し入れる","ko":"굴 굽기 및 전분 반죽 붓기","vi":"Áp chảo hàu và rưới bột"},"instruction":{"zh-TW":"平底鍋倒入 2 大匙油大火燒熱，放入洗淨擦乾的蚵仔煎 30 秒至表面緊縮微出香氣。立刻將粉漿再次攪勻，由外向內均勻淋在蚵仔上方。","en":"Heat 2 tbsp oil in a flat skillet over high heat. Add oysters and sear for 30s. Restir the starch slurry and pour evenly around and over the sizzling oysters.","ja":"フライパンに油大さじ2を強火で熱し、水気を切った牡蠣を入れて30秒サッと炒めます。よく混ぜ直した生地を一気に回し入れます。","ko":"팬에 식용유 2큰술을 두르고 굴을 넣어 30초간 빠르게 볶습니다. 다시 잘 저은 전분물을 굴 위로 둥글게 둘러 부어줍니다.","vi":"Đun nóng 2 thìa dầu, cho hàu vào đảo nhanh 30 giây. Khuấy đều bột rồi rưới tròn phủ kín hàu."},"image":"/images/tw/oyster-omelet-step2.jpg","durationSeconds":90},{"stepNumber":3,"title":{"zh-TW":"打入雞蛋與鋪上鮮嫩青菜","en":"Crack Egg & Lay Fresh Greens","ja":"卵を割りほぐし、青菜をたっぷり乗せる","ko":"달걀 터뜨리기 및 채소 얹기","vi":"Đập trứng và rải rau xanh"},"instruction":{"zh-TW":"當粉漿邊緣變透明微脆時，打入一顆雞蛋並用鍋鏟劃破蛋黃推勻。鋪上滿滿的小白菜段。","en":"When the batter edges turn translucent and crisp, crack an egg directly on top, puncture yolk and spread. Cover generously with chopped greens.","ja":"生地のフチが透明に透き通ってきたら、卵を割り落として黄身を崩して広げます。その上にたっぷりの青菜を乗せます。","ko":"반죽 가장자리가 투명해지면 달걀을 깨뜨려 노른자를 터뜨려 펼치고, 위에 썰어둔 청경채를 듬뿍 올립니다.","vi":"Khi mép bột trong lại, đập trứng gà dằm vỡ lòng đỏ thoa đều, rải ngập cải thìa lên trên."},"image":"/images/tw/oyster-omelet-step3.jpg","durationSeconds":90},{"stepNumber":4,"title":{"zh-TW":"帥氣翻面！煎至雙面金黃脆皮","en":"The Flip & Crisping the Crust","ja":"思い切ってひっくり返し、両面をカリッと焼く","ko":"뒤집기 및 양면 노릇하게 굽기","vi":"Lật mặt bánh chiên giòn đều hai mặt"},"instruction":{"zh-TW":"用鍋鏟由下方推動，俐落翻面！轉中大火繼續煎約 1~2 分鐘，讓青菜斷生、底部的粉漿邊緣呈現誘人的金黃焦脆。","en":"Slide spatula underneath and flip boldly in one motion! Cook for 1-2 more mins until greens wilt and the bottom crust becomes golden and crisp.","ja":"フライ返しを一気に差し込み、思い切って裏返します！中強火で1〜2分焼き、野菜に火を通し底面をカリカリに仕上げます。","ko":"뒤집개를 깊숙이 넣어 한 번에 착 뒤집어줍니다! 중강불에서 1~2분간 더 구워 채소 숨을 죽이고 가장자리를 바삭하게 굽습니다.","vi":"Luồn xẻng lật dứt khoát một lần. Chiên lửa vừa 1-2 phút cho rau chín và viền bột giòn xém vàng."},"image":"/images/tw/oyster-omelet-step4.jpg","durationSeconds":120},{"stepNumber":5,"title":{"zh-TW":"起鍋淋上滿滿粉紅甜辣醬！","en":"Plate & Drown in Pink Sauce","ja":"お皿に盛り、特製ピンクだれをたっぷりかけて完成！","ko":"접시에 담고 분홍 소스를 듬뿍 뿌려 완성!","vi":"Cho ra đĩa và rưới ngập sốt hồng đặc trưng!"},"instruction":{"zh-TW":"滑入大盤中，淋上 3 大匙溫熱的特製海山甜辣醬，趁熱用筷子撕開拉絲享用！","en":"Slide onto a large plate. Generously ladle warm pink sweet chili sauce all over. Dig in while sizzling hot!","ja":"お皿に滑らせるように盛り付け、温めた特製だれをたっぷり回しかけて熱々のうちに召し上がれ！","ko":"접시에 담고 따뜻한 특제 분홍 소스를 듬뿍 끼얹어 바로 드세요!","vi":"Trượt ra đĩa lớn, rưới đẫm 3 muỗng sốt hồng chua ngọt ấm nóng và thưởng thức ngay khi còn nóng hổi."},"image":"/images/tw/oyster-omelet.jpg","durationSeconds":30}],"troubleshooting":[{"id":"ts-oy-1","problem":{"zh-TW":"翻面時粉皮破裂碎掉、蚵仔散開？","en":"Why does the omelet break apart when flipping?","ja":"ひっくり返す時に生地が破れてボロボロになってしまう？","ko":"뒤집을 때 반죽이 찢어지고 굴이 흩어지나요?","vi":"Tại sao bánh bị vỡ nát khi lật?"},"cause":{"zh-TW":"太早翻面（底部粉漿尚未透明凝固成膜），或者鍋子油不夠熱。","en":"Flipped too early before the bottom starch fully set into a translucent cohesive sheet.","ja":"底の生地がまだ固まりきっていないうちに触ってしまったのが原因です。","ko":"바닥의 전분이 투명하게 굳어 막을 형성하기 전에 너무 일찍 뒤집었기 때문입니다.","vi":"Lật bánh quá sớm khi lớp bột đáy chảo chưa kịp đông kết thành màng dai."},"solution":{"zh-TW":"看到邊緣煎出金黃微捲脆邊、中間完全透明時，用大平鏟一氣呵成俐落翻面！","en":"Wait until edges are golden crispy and center is fully translucent, then slide spatula deeply and flip in one swift movement.","ja":"フチがカリッとして全体が透き通るまでじっくり待ってから、一気に裏返しましょう！","ko":"가장자리가 바삭하게 익고 전체가 투명해졌을 때 뒤집개를 깊숙이 넣어 과감하게 뒤집으세요.","vi":"Chờ đến khi viền giòn vàng và giữa trong suốt, dùng xẻng to lật dứt khoát."}}],"proTips":[{"zh-TW":"調粉漿時加入少許太白粉（比例 3:1），能讓蚵仔煎外脆內軟Q，既不黏爛也不死硬！","en":"Mixing sweet potato starch with potato starch (3:1) gives the optimal balance of crispy lace edge and chewy center.","ja":"サツマイモ粉に少量の片栗粉（3:1）を混ぜると、外はカリッ、中はモチモチの絶妙な食感になります！","ko":"고구마전분과 감자전분을 3:1 비율로 섞어주면 바삭함과 쫀득함이 동시에 살아납니다.","vi":"Pha bột khoai lang với bột năng theo tỷ lệ 3:1 để đạt độ giòn ngoài dẻo trong đỉnh nhất."}]},{"country":"tw","id":"sweet-potato-balls","slug":"sweet-potato-balls","title":{"zh-TW":"夜市巨型空心地瓜球","en":"Taiwanese Hollow QQ Sweet Potato Balls","ja":"夜市名物 巨大中空さつまいもボール（地瓜球）","ko":"대만 야시장 속 빈 고구마볼 (디과추)","vi":"Bánh khoai lang viên rỗng ruột giòn rụm (QQ Balls)"},"subtitle":{"zh-TW":"連續按壓排氣膨脹・外極酥脆內極Q彈","en":"The Repetitive Pressing Technique for Giant Puffy Spheres","ja":"何度も油の中で押し潰して膨らませる！外カリ中モチの極上食感","ko":"연속 꾹꾹 누르기 기법으로 풍선처럼 부풀리는 바삭 쫀득 스낵","vi":"Kỹ thuật ép dầu liên hoàn giúp bánh nở phồng giòn rỗng ruột"},"tagline":{"zh-TW":"夜市排隊人手一包的療癒小吃，掌握連續按壓的膨脹魔法","en":"The most addictive night market snack with a magical puffing technique","ja":"夜市で行列が絶えない国民的人気スイーツ。膨らむ魔法の食感","ko":"줄 서서 먹는 대만 야시장의 힐링 간식, 팽창의 마법","vi":"Món ăn vặt gây nghiện nhất mọi chợ đêm Đài Loan"},"heroImage":"/images/tw/sweet-potato-balls.jpg","difficulty":"hard","prepTimeMinutes":25,"cookTimeMinutes":15,"defaultServings":3,"caloriesPerServing":280,"category":"desserts","dietaryTags":["vegan","vegetarian","halal","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台中 / 高雄","en":"Taichung / Kaohsiung","ja":"台中 / 高雄","ko":"타이중 / 가오슝","vi":"Đài Trung / Cao Hùng"},"famousNightMarkets":[{"zh-TW":"逢甲夜市 (巨無霸地瓜球)","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"},{"zh-TW":"瑞豐夜市","en":"Ruifeng Night Market","ja":"瑞豊夜市","ko":"루이펑 야시장","vi":"Chợ đêm Ruifeng"}],"historyStory":{"zh-TW":"地瓜球（又稱QQ蛋）是台灣夜市最受歡迎的手工小吃之一。老闆拿著大漏勺在熱油中不斷用力按壓剛炸熱的生胚，利用空氣進出讓地瓜球如氣球般越壓越大、形成外殼極脆內部空心的神奇口感。","en":"A mesmerizing Taiwanese night market specialty where vendors use large perforated skimmers to repeatedly mash the frying dough balls against the wok. This pumps air inside, expanding them into giant hollow, crispy golden globes.","ja":"夜市の屋台で職人が大きな穴あきお玉で何度もギュッギュッと押し潰しながら揚げるのが特徴。空気が入って風船のように膨らみ、外はサクサク、中は空洞でモチモチになります。","ko":"대만 야시장에서 국자로 튀김을 꾹꾹 누르며 튀기는 모습으로 유명한 간식입니다. 누를수록 공기가 들어가 풍선처럼 부풀어 올라 겉은 바삭하고 속은 텅 빈 쫄깃한 식감이 완성됩니다.","vi":"Đặc sản chợ đêm Đài Loan với kỹ thuật dùng vá thủng ép liên tục trong chảo dầu để bánh nở phồng to như quả bóng giòn rụm."},"taiwaneseHokkien":"Han-tsû-kiû (ㄏㄢ ㄐㄧˊ ㄍㄧㄨˊ)","mandarinPinyin":"Dìguāqiú (ㄉㄧˋ ㄍㄨㄚ ㄑㄧㄡˊ)","audioPronunciationText":"老闆，大包地瓜球一份，黃色紫色都要"},"ingredients":[{"id":"sweet-potato","name":{"zh-TW":"黃肉或紅肉地瓜 (去皮蒸熟)","en":"Yellow/Orange Sweet Potato (Steamed & Peeled)","ja":"さつまいも（皮をむいて蒸したもの）","ko":"고구마 (껍질 벗겨 찐 것)","vi":"Khoai lang vàng hoặc tím (Hấp chín nghiền nhuyễn)"},"amount":250,"unitMetric":"g","unitUS":"9 oz","isKeyFlavor":true,"chineseName":"地瓜","chinesePinyin":"Dì guā"},{"id":"tapioca-starch-spb","name":{"zh-TW":"木薯粉 (樹薯粉)","en":"Tapioca Starch (Cassava Flour)","ja":"タピオカ粉（樹薯粉）","ko":"타피오카 전분","vi":"Bột năng"},"amount":100,"unitMetric":"g","unitUS":"0.7 cup","isKeyFlavor":true,"chineseName":"木薯粉","chinesePinyin":"Mù shǔ fěn"},{"id":"sugar-spb","name":{"zh-TW":"細白砂糖","en":"Granulated Sugar","ja":"上白糖またはグラニュー糖","ko":"백설탕","vi":"Đường cát trắng"},"amount":40,"unitMetric":"g","unitUS":"3 tbsp","chineseName":"細砂糖","chinesePinyin":"Xì shā táng"},{"id":"frying-oil","name":{"zh-TW":"耐高溫植物油 (油炸用)","en":"High-Heat Frying Oil","ja":"揚げ油（サラダ油または米油）","ko":"식용유 (튀김용)","vi":"Dầu ăn chiên rán"},"amount":500,"unitMetric":"ml","unitUS":"2 cups","chineseName":"食用油","chinesePinyin":"Shí yòng yóu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"蒸熟地瓜並趁熱壓泥拌糖","en":"Steam Sweet Potato & Mash with Sugar","ja":"さつまいもを蒸して熱いうちに砂糖とマッシュする","ko":"고구마 찌기 및 뜨거울 때 설탕 넣고 으깨기","vi":"Hấp chín khoai lang và nghiền nhuyễn với đường"},"instruction":{"zh-TW":"地瓜去皮切厚片，大火蒸 15 分鐘至竹籤可輕易穿透。趁熱倒入大盆中，加入 40g 砂糖，用壓泥器或叉子壓成細膩無顆粒的地瓜泥。","en":"Peel and slice sweet potato. Steam for 15 mins until fork-tender. Transfer to a bowl while steaming hot, add 40g sugar, and mash into a smooth lump-free puree.","ja":"さつまいもの皮をむいて輪切りにし、15分蒸します。熱いうちにボウルに入れ、砂糖40gを加えてフォークやマッシャーでなめらかに潰します。","ko":"고구마 껍질을 벗겨 썰어 15분간 찝니다. 뜨거울 때 볼에 담고 설탕 40g을 넣어 포크나 매셔로 덩어리 없이 곱게 으깨줍니다.","vi":"Khoai gọt vỏ thái khoanh hấp 15 phút cho chín mềm. Cho vào âu dằm nhuyễn lúc còn nóng cùng 40g đường."},"image":"/images/tw/spb-step1.jpg","durationSeconds":900},{"stepNumber":2,"title":{"zh-TW":"分次加地瓜粉揉團，分切搓圓","en":"Knead with Starch & Roll into Balls","ja":"タピオカ粉を加えてこね、一口大の丸に成形する","ko":"타피오카 전분 섞어 반죽 후 동글동글 빚기","vi":"Nhồi bột năng và vo viên tròn đều"},"instruction":{"zh-TW":"趁微溫分次加入 100g 木薯粉，用手揉捏成「耳垂般柔軟、不黏手」的光滑麵團。搓成長條，切成約 10~12g 的小劑子，雙手搓成圓滑小球。","en":"Add 100g tapioca starch gradually to warm puree. Knead into a soft, smooth dough (like earlobe texture). Roll into long cylinders, divide into 10g nuggets, and roll into smooth spheres.","ja":"温かいうちにタピオカ粉100gを少しずつ加え、耳たぶくらいの柔らかさにこねます。棒状に伸ばして10gずつに切り分け、丸く成形します。","ko":"미온일 때 타피오카 전분 100g을 나누어 넣으며 귓볼처럼 부드럽고 매끄러운 반죽을 만듭니다. 길게 늘여 10g씩 자르고 둥글게 빚어줍니다.","vi":"Cho bột năng vào nhồi thành khối dẻo mịn như dái tai không dính tay. Chia thành viên 10g vo tròn."},"image":"/images/tw/spb-step2.jpg","durationSeconds":600},{"stepNumber":3,"title":{"zh-TW":"溫油下鍋微炸浮起 (120°C)","en":"Gentle Fry in Warm Oil until Floating (120°C / 250°F)","ja":"ぬるめの油（120℃）に入れ、浮き上がるまで静かに揚げる","ko":"저온 기름(120°C)에 넣고 떠오를 때까지 서서히 튀기기","vi":"Thả vào chảo dầu ấm 120°C chiên nhẹ đến khi nổi"},"instruction":{"zh-TW":"鍋中倒入足量油，冷油開小火升溫至約 120°C（筷子周圍有微小氣泡）。下地瓜球生胚，先不要攪動，等約 2~3 分鐘地瓜球定型並「全數浮在油面上」。","en":"Heat oil over low flame to 120°C (250°F). Gently slide sweet potato balls in. Do not stir for first 2-3 mins until all balls naturally puff slightly and float to the surface.","ja":"油を低温（約120℃）に熱し、生地を静かに入れます。触らずに2〜3分待ち、生地がすべて油の上にプカプカ浮いてくるのを待ちます。","ko":"기름을 약불에서 120°C로 은은하게 데운 후 반죽을 넣습니다. 2~3분간 건드리지 않고 모든 볼이 기름 위로 둥둥 떠오를 때까지 기다립니다.","vi":"Đun dầu lửa nhỏ 120°C, thả viên khoai vào. Để yên 2-3 phút cho khoai tự nổi lên mặt dầu."},"image":"/images/tw/spb-step3.jpg","durationSeconds":180},{"stepNumber":4,"title":{"zh-TW":"靈魂！大漏勺連續按壓排氣膨脹","en":"The Magic Press: Repetitively Squeeze with Mesh Ladle","ja":"魂の技！穴あきお玉でギュッギュッと押し潰して巨大化！","ko":"핵심 비법! 국자로 꾹꾹 눌러 풍선처럼 부풀리기","vi":"Bí quyết ép xả khí liên tục giúp bánh nở phồng khổng lồ"},"instruction":{"zh-TW":"看到浮起後，拿大漏勺用力將地瓜球「往下、往鍋壁按壓擠扁」，鬆開後地瓜球會吸入空氣立刻彈回並變大！連續重複「按壓→放開→翻滾」至少 6~8 次，地瓜球會膨脹成 3 倍大的巨型空心球！","en":"Once floating, use a large perforated ladle to press the balls firmly against the wok bottom/side, flattening them. Release, and watch them pop back even bigger! Repeat \"Press -> Release -> Roll\" 6-8 times to balloon them into giant hollow spheres!","ja":"浮いてきたら、穴あきお玉の背で生地を鍋肌にギューッと押し潰します！離すと空気を吸い込んで一回り大きく膨らみます。「潰す→離す」を6〜8回繰り返すと、3倍の大きさに膨張します！","ko":"떠오르면 구멍 뚫린 국자로 고구마볼을 냄비 바닥에 꾹 눌러 납작하게 찌그러뜨립니다. 손을 떼면 공기가 들어가며 더 크게 부풀어 오릅니다! 이 과정을 6~8회 반복하면 3배 크기로 거대해집니다.","vi":"Dùng muôi lỗ ép dẹp viên khoai vào thành chảo, buông ra khoai sẽ hút khí phồng to hơn. Lặp lại 6-8 lần bánh sẽ nở gấp 3 lần rỗng ruột giòn tan!"},"image":"/images/tw/spb-step4.jpg","durationSeconds":300,"crucialTips":{"zh-TW":"越敢用力按壓，地瓜球就膨脹得越大、裡面就越空心酥脆！不要怕壓破，麵團有極強彈性。","en":"Press boldly! The harder and more frequently you press, the thinner and crunchier the hollow shell becomes.","ja":"恐れずにしっかり力を入れて押し潰すのがコツです！潰すほど中が空洞になりサクサクになります。","ko":"과감하게 꾹 눌러주세요! 많이 누를수록 껍질은 얇고 바삭해지며 속은 완벽하게 비어있게 됩니다.","vi":"Càng ép mạnh tay thì bánh càng nở to rỗng ruột giòn xốp."}},{"stepNumber":5,"title":{"zh-TW":"大火逼油撈出，金黃酥脆出鍋！","en":"High-Heat Oil Expel & Serve Crispy","ja":"強火で油切りして完成！黄金のサクサクボール","ko":"강불로 기름 빼고 노릇하게 건져 완성!","vi":"Tăng lửa ép dầu và vớt ra vàng giòn rụm!"},"instruction":{"zh-TW":"起鍋前轉大火炸 30 秒逼出多餘油脂，外殼呈現金黃硬脆手感。用漏勺撈起瀝乾油份，裝入紙袋搖晃，趁熱咬下一口聽見喀滋酥脆聲！","en":"Turn heat to high for the final 30 secs to expel oil. Scoop up in a strainer and shake off excess oil. Serve hot in paper bags for maximum crunch!","ja":"最後に強火で30秒揚げて油をカラッと切ります。ザルに上げて油を切り、紙袋に入れて熱々のサクサク感を楽しみましょう！","ko":"건지기 전 30초간 강불로 올려 기름을 쫙 빼줍니다. 채망으로 건져 기름을 털어내고 종이봉투에 담아 따뜻할 때 바삭하게 드세요!","vi":"Bật lửa to 30 giây cuối ép sạch dầu thừa, vớt ra xóc ráo dầu và thưởng thức khi còn nóng hổi."},"image":"/images/tw/sweet-potato-balls.jpg","durationSeconds":60}],"troubleshooting":[{"id":"ts-sp-1","problem":{"zh-TW":"炸出來的地瓜球扁扁的、沒有膨脹成空心？","en":"Why did my balls turn out dense and flat instead of puffy hollow?","ja":"ペタンコのままで中が空洞に膨らまない？","ko":"부풀지 않고 속이 꽉 찬 떡처럼 딱딱한가요?","vi":"Tại sao bánh không nở rỗng ruột mà bị đặc xẹp?"},"cause":{"zh-TW":"油溫太高（外皮太快定型變硬無法伸展），或者炸的時候沒有用力連續按壓。","en":"Oil was too hot initially (crust set too fast to expand) or didn’t press hard enough with ladle.","ja":"最初の油温が高すぎたか、お玉での押し潰しが足りなかったためです。","ko":"처음 기름 온도가 너무 높아 껍질이 일찍 굳었거나, 국자로 충분히 누르지 않았기 때문입니다.","vi":"Dầu quá nóng làm vỏ cứng sớm không giãn nở được, hoặc chưa ép đủ lực."},"solution":{"zh-TW":"一定要從 120°C 低溫慢炸，等浮起後「毫不留情地反覆用力壓扁」！","en":"Start strictly at 120°C low heat. Once floating, mash and compress them vigorously multiple times!","ja":"必ず120℃の低温からスタートし、浮いてきたら思い切り何度も押し潰してください！","ko":"반드시 120°C 저온에서 시작하고, 떠오르면 사정없이 국자로 꾹꾹 눌러주세요!","vi":"Bắt đầu ở nhiệt 120°C và ép liên tục sau khi khoai nổi."}}],"proTips":[{"zh-TW":"若想要做出夜市常見的「黃紫雙色地瓜球」，可分別準備黃地瓜與紫地瓜，兩種麵團交錯或單獨搓圓下鍋，視覺超吸睛！","en":"For two-tone night market style, make batches with both yellow and purple sweet potatoes!","ja":"黄色と紫色のさつまいもを両方使うと、夜市で大人気の「2色地瓜球」が作れます！","ko":"호박고구마와 자색고구마를 함께 쓰면 야시장 명물인 알록달록 2색 고구마볼을 만들 수 있습니다.","vi":"Dùng cả khoai lang vàng và tím để làm đĩa bánh 2 màu tuyệt đẹp chuẩn chợ đêm."}]},{"country":"tw","id":"sausage-in-rice","slug":"sausage-in-rice","title":{"zh-TW":"炭烤經典大腸包小腸","en":"Taiwanese Sausage in Sticky Rice (Rice Hot Dog)","ja":"炭火焼き 台湾式ライスホットドッグ（大腸包小腸）","ko":"대만식 숯불 라이스 핫도그 (다창바오샤오창)","vi":"Xôi bọc xúc xích nướng than Đài Loan"},"subtitle":{"zh-TW":"炭烤糯米腸夾高粱香腸・酸菜九層塔蒜片極致夾心","en":"Grilled Sticky Rice Bun, Kaoliang Sausage & Pickled Greens","ja":"香ばしいもち米ソーセージ×高粱酒ソーセージの絶品サンド","ko":"숯불 찹쌀 소시지에 대만 수제 소시지와 갓절임, 마늘의 환상 궁합","vi":"Xôi nướng kẹp xúc xích tươi cùng dưa chua, lá quế thơm lừng"},"tagline":{"zh-TW":"逢甲夜市排隊傳奇！台灣最霸氣的台式熱狗堡","en":"The iconic Taiwanese rice dog born in Fengjia Night Market","ja":"逢甲夜市で行列を作る伝説の屋台グルメ！台湾版ホットドッグ","ko":"펑자 야시장의 전설적인 줄 서는 맛집 대표 메뉴","vi":"Huyền thoại chợ đêm Fengjia với phiên bản hotdog gạo Đài Loan đỉnh cao"},"heroImage":"/images/tw/sausage-in-rice.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":520,"category":"fried","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originCity":{"zh-TW":"台中逢甲 / 花蓮","en":"Taichung Fengjia / Hualien","ja":"台中・逢甲 / 花蓮","ko":"타이중 펑자 / 화롄","vi":"Đài Trung Fengjia / Hoa Liên"},"famousNightMarkets":[{"zh-TW":"逢甲夜市 (官芝霖 / 百佳)","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"},{"zh-TW":"花蓮東大門夜市","en":"Dongdamen Night Market","ja":"東大門夜市","ko":"둥다먼 야시장","vi":"Chợ đêm Dongdamen"}],"historyStory":{"zh-TW":"大腸包小腸源自台灣南部與東部的傳統農村點心，1990年代在台中逢甲夜市發揚光大。將體積較大的「糯米腸」（大腸）切開，抹上蒜蓉醬油膏，夾入體積較小的「高粱酒黑豬肉香腸」（小腸），再塞入炒酸菜、小黃瓜、九層塔與生蒜片，一口咬下雙重肉感與米香爆發！","en":"Invented as a rural farmer snack, it was popularized in Taichung's Fengjia Night Market in the 1990s. A grilled sticky rice sausage serves as the bun, cradling a sweet grilled Taiwanese pork sausage, loaded with sour pickled greens, raw garlic slices, fresh Thai basil, and sweet garlic soy paste.","ja":"1990年代に台中の逢甲夜市で大ブレイクした台湾風ホットドッグ。もち米を詰めた太い米ソーセージ（大腸）をパンに見立てて切り込みを入れ、甘辛い豚肉ソーセージ（小腸）と高菜、生ニンニク、台湾バジルを贅沢に挟み込みます。","ko":"1990년대 타이중 펑자 야시장에서 시작되어 대만 전역을 사로잡은 길거리 음식입니다. 찹쌀을 채운 굵은 찹쌀 소시지를 반으로 갈라 숯불에 구운 달콤한 돼지고기 소시지와 볶은 갓절임, 생마늘 편, 바질을 가득 채워 먹습니다.","vi":"Ra đời từ những năm 1990 tại chợ đêm Fengjia Đài Trung. Dùng thanh xôi nếp lạp xưởng nướng rạch đôi làm vỏ bánh, kẹp xúc xích thịt heo nướng than cùng dưa cải chua, tỏi sống thái lát và sốt tương tỏi ngọt đậm đà."},"taiwaneseHokkien":"Tuā-tn̂g pau sió-tn̂g (ㄉㄨㄚˇ ㄉㄥˊ ㄅㄠ ㄒㄧㄜˋ ㄉㄥˊ)","mandarinPinyin":"Dà cháng bāo xiǎo cháng (ㄉㄚˋ ㄔㄤˊ ㄅㄠ ㄒㄧㄠˇ ㄔㄤˊ)","audioPronunciationText":"老闆，一份大腸包小腸，蒜味加辣"},"ingredients":[{"id":"sticky-rice-sausage","name":{"zh-TW":"台灣古早味糯米腸 (大腸)","en":"Taiwanese Sticky Rice Sausages (Large)","ja":"台湾風もち米ソーセージ（糯米腸）","ko":"대만식 찹쌀 소시지 (롸미창)","vi":"Xôi lạp xưởng gạo nếp Đài Loan"},"amount":2,"unitMetric":"piece","unitUS":"2 links","isKeyFlavor":true,"chineseName":"糯米腸","chinesePinyin":"Nuò mǐ cháng","substitute":{"substituteName":{"zh-TW":"自製蒸熟調味糯米飯 (用保鮮膜捏成香腸條狀)","en":"Steamed seasoned sticky rice pressed into sausage shape using plastic wrap","ja":"もち米ご飯（醤油と油葱酥で味付け）をラップでソーセージ状に成形","ko":"양념 찹쌀밥을 랩으로 소시지 모양으로 뭉쳐 사용","vi":"Xôi nếp dẻo trộn hành phi nắm thành hình thanh xúc xích"},"ratio":"1:1","explanation":{"zh-TW":"糯米腸主要由圓糯米、油蔥酥與花生製成。若買不到現成糯米腸，可將蒸熟糯米飯加醬油、紅蔥酥拌勻後塑形。","en":"Sticky rice sausage contains glutinous rice, shallots, and peanuts. You can replicate it by shaping cooked seasoned sticky rice into a bun.","ja":"中華スーパーの冷凍コーナーにあります。なければ味付けもち米ご飯で代用可能です。","ko":"아시안 마트 냉동 코너에서 구매할 수 있으며, 없을 시 양념 찹쌀밥으로 대체 가능합니다.","vi":"Có thể mua sẵn ở khu đông lạnh siêu thị châu Á hoặc tự đồ xôi nếp nắm lại."},"whereToBuy":{"zh-TW":"大華超市 (99 Ranch)、亞超冷凍麵點區、生鮮市場","en":"99 Ranch Market, H-Mart freezer aisle, Asian grocery markets","ja":"中華物産店、アジア系スーパー冷凍コーナー","ko":"중국 식자재 마트 냉동 코너","vi":"Khu đông lạnh siêu thị châu Á"}}},{"id":"taiwan-pork-sausage","name":{"zh-TW":"台灣高粱黑豬肉香腸 (小腸)","en":"Taiwanese Sweet Pork Sausages (Kaoliang flavored)","ja":"台湾黒豚ソーセージ（台湾香腸）","ko":"대만식 달콤한 돼지고기 소시지 (샹창)","vi":"Xúc xích ngọt Đài Loan (Lạp xưởng tươi)"},"amount":2,"unitMetric":"piece","unitUS":"2 links","isKeyFlavor":true,"chineseName":"台灣香腸","chinesePinyin":"Tái wān xiāng cháng"},{"id":"pickled-mustard-greens","name":{"zh-TW":"客家酸菜 (切碎炒香)","en":"Taiwanese Pickled Mustard Greens (Finely chopped & sautéed)","ja":"台湾高菜漬け（酸菜・炒めたもの）","ko":"대만식 볶은 갓절임 (쏸차이)","vi":"Dưa cải chua xào giòn"},"amount":50,"unitMetric":"g","unitUS":"0.3 cup","isKeyFlavor":true,"chineseName":"酸菜","chinesePinyin":"Suān cài"},{"id":"raw-garlic-slices","name":{"zh-TW":"生大蒜片 (靈魂辛辣去膩)","en":"Raw Garlic Cloves (Thinly Sliced)","ja":"生ニンニク（薄切りスライス）","ko":"생마늘 편","vi":"Tỏi sống thái lát mỏng"},"amount":4,"unitMetric":"clove","unitUS":"4 cloves","chineseName":"蒜片","chinesePinyin":"Suàn piàn"},{"id":"taiwan-sweet-chili","name":{"zh-TW":"甜辣醬 + 蒜蓉醬油膏","en":"Sweet Chili Sauce & Garlic Soy Paste","ja":"台湾とろみ醤油（醤油膏）＋スイートチリソース","ko":"장유고(마늘간장소스) + 스위트 칠리소스","vi":"Sốt tương tỏi ngọt + Tương ớt ngọt Đài Loan"},"amount":30,"unitMetric":"ml","unitUS":"2 tbsp","chineseName":"蒜蓉醬油膏","chinesePinyin":"Suàn róng jiàng yóu gāo"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"備料與糯米腸縱向劃開","en":"Prep Ingredients & Slit Sticky Rice Sausage","ja":"具材を準備し、もち米ソーセージに切り込みを入れる","ko":"재료 준비 및 찹쌀 소시지 가운데 가르기","vi":"Chuẩn bị nguyên liệu và rạch đôi xôi lạp xưởng"},"instruction":{"zh-TW":"大蒜切薄片，客家酸菜切碎加少許糖炒乾水分。將糯米腸在案板上用刀從上方中央縱向劃開一條深縫（約切入 2/3 深，底部保持相連），形成如熱狗麵包般的開口。","en":"Thinly slice raw garlic. Finely chop pickled mustard greens and stir-fry with a pinch of sugar. Place sticky rice sausages on board and slice lengthwise down the center (about 2/3 deep, keeping bottom intact like a hot dog bun).","ja":"ニンニクを薄切りにし、高菜漬けは刻んで少量の砂糖と乾煎りします。もち米ソーセージの中央に縦に2/3ほどの深さの切り込みを入れ、ホットドッグ用のパンのように開きます。","ko":"생마늘을 편 썰고, 갓절임은 잘게 썰어 설탕 약간과 함께 마른 팬에 볶아 수분을 날립니다. 찹쌀 소시지 중앙을 칼로 2/3 깊이로 길게 갈라 핫도그 빵 모양으로 벌려줍니다.","vi":"Tỏi thái lát mỏng, dưa cải chua băm nhỏ xào khô cùng chút đường. Dùng dao rạch dọc lưng thanh xôi nếp sâu 2/3 không làm đứt đáy như bánh hotdog."},"image":"/images/tw/sausage-step1.jpg","durationSeconds":180},{"stepNumber":2,"title":{"zh-TW":"炭烤或氣炸高粱香腸與糯米腸","en":"Grill or Air Fry Sausages to Sizzling Perfection","ja":"ソーセージともち米ソーセージを香ばしくグリルする","ko":"소시지와 찹쌀 소시지 숯불/에어프라이어에 노릇하게 굽기","vi":"Nướng xúc xích và xôi lạp xưởng thơm nức giòn bì"},"instruction":{"zh-TW":"【炭烤/平底鍋】：烤網或平底鍋刷薄油，中小火慢烤香腸與糯米腸約 8~10 分鐘，香腸外皮滋滋流油、糯米腸外皮微酥金黃。\n【氣炸鍋模式】：180°C (355°F) 氣炸 10 分鐘，中途 5 分鐘翻面一次。","en":"Charcoal Grill/Skillet: Lightly grease grill or pan. Grill pork sausages and sticky rice sausages over medium-low heat for 8-10 mins until pork sausages are sizzling with slight char and rice casing is golden crispy.\nAir Fryer: 180°C (355°F) for 10 mins, flipping halfway.","ja":"【グリル・フライパン】：薄く油を引き、中弱火で8〜10分じっくり焼きます。肉汁が弾け、もち米の皮がカリッと香ばしくなるまで。\n【ノンフライヤー】：180℃で10分、途中で裏返します。","ko":"【그릴/팬】：기름을 살짝 두르고 중약불에서 8~10분간 굴려가며 굽습니다. 소시지 육즙이 터져 나오고 찹쌀 소시지 겉면이 바삭해질 때까지 구워줍니다.\n【에어프라이어】：180°C에서 10분간 조리, 5분 뒤 뒤집기.","vi":"Nướng than/Chảo: Quét dầu nướng lửa vừa 8-10 phút cho xúc xích tứa mỡ xém vàng và vỏ xôi giòn rụm.\nNồi chiên không dầu: 180°C trong 10 phút, lật mặt lúc 5 phút."},"image":"/images/tw/sausage-step2.jpg","durationSeconds":600,"cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 180°C (355°F) for 10 mins","instructionOverride":{"zh-TW":"將香腸表面用牙籤戳幾個小孔防爆裂，與糯米腸一同放入氣炸鍋。設定 180°C 氣炸 10 分鐘，香腸香氣四溢、糯米腸外脆內軟糯！","en":"Prick sausages with toothpick to prevent bursting. Place in air fryer at 180°C for 10 mins until golden and aromatic.","ja":"ソーセージに爪楊枝で数カ所穴を開け、180℃で10分ノンフライヤー調理。外カリ中モチに仕上がります！","ko":"소시지 껍질에 이쑤시개로 구멍을 몇 개 낸 뒤 180°C에서 10분간 에어프라이어에 굽습니다.","vi":"Dùng tăm xăm vài lỗ nhỏ trên xúc xích, cho vào nồi chiên 180°C trong 10 phút."}}]},{"stepNumber":3,"title":{"zh-TW":"刷上靈魂蒜味油膏與甜辣醬","en":"Brush Garlic Soy Paste & Sweet Chili Sauce","ja":"特製にんにく醤油膏とチリソースをたっぷり塗る","ko":"특제 마늘 간장소스와 칠리소스 듬뿍 바르기","vi":"Quét đẫm sốt tương tỏi và tương ớt ngọt"},"instruction":{"zh-TW":"趁熱拿起烤好的糯米腸，用醬料刷在切開的內部兩側均勻刷上一層厚厚的「蒜味醬油膏」與「甜辣醬」，讓濃醇鹹甜醬汁滲入熱騰騰的糯米縫隙中。","en":"While hot, gently pry open the sticky rice sausage. Use a brush to generously coat the inside with savory garlic soy paste and Taiwanese sweet chili sauce so the sauce sinks into the hot glutinous rice.","ja":"焼き上がった熱々のもち米ソーセージの切り口を開き、刷毛でにんにく醤油膏とスイートチリソースをたっぷり塗り込みます。","ko":"갓 구워 뜨거운 찹쌀 소시지의 벌어진 안쪽에 붓으로 마늘 장유고 소스와 칠리소스를 듬뿍 발라 밥알 사이사이로 스며들게 합니다.","vi":"Mở rộng khe xôi nếp nướng lúc còn nóng hổi, dùng cọ quét đẫm sốt tương tỏi và tương ớt ngọt vào thành trong."},"image":"/images/tw/sausage-step3.jpg","durationSeconds":60},{"stepNumber":4,"title":{"zh-TW":"塞滿酸菜、九層塔、油蔥酥與生蒜片","en":"Stuff Pickled Greens, Basil & Garlic Slices","ja":"炒め高菜・バジル・揚げエシャロット・生ニンニクをぎっしり詰める","ko":"볶은 갓절임, 바질, 샬롯튀김, 생마늘 편 가득 채우기","vi":"Nhồi ngập dưa cải chua, lá quế, hành phi và tỏi sống"},"instruction":{"zh-TW":"用小夾子在切口底部鋪滿炒香的客家酸菜、酥脆油蔥酥、新鮮九層塔葉與生大蒜薄片（敢吃辣者可加醃薑片與辣椒醬），配料堆滿如山！","en":"Using small tongs, pack the bottom of the rice pocket with stir-fried pickled greens, crispy fried shallots, fresh Thai basil leaves, and raw garlic slices.","ja":"トングを使い、切り込みの底に香ばしい高菜漬け、油葱酥、生バジル、生ニンニクスライスを隙間なくぎっしり詰め込みます！","ko":"작은 집게로 볶은 갓절임, 바삭한 샬롯 튀김, 신선한 바질 잎, 알싸한 생마늘 편을 가득 채워 넣습니다.","vi":"Dùng kẹp gắp nhồi đẫm dưa cải chua xào, hành phi giòn, lá húng quế tươi và tỏi sống thái lát vào đáy khe xôi."},"image":"/images/tw/sausage-step4.jpg","durationSeconds":90},{"stepNumber":5,"title":{"zh-TW":"塞入多汁香腸，捲紙袋旋轉開吃！","en":"Nestle Grilled Sausage & Spin the Paper Wrapper","ja":"熱々の台湾ソーセージを挟み、紙袋でくるっと巻いて完成！","ko":"육즙 가득 소시지 쏙 넣고 종이봉투로 돌려 먹기!","vi":"Kẹp xúc xích vào giữa, cuộn túi giấy xoay ăn chuẩn điệu!"},"instruction":{"zh-TW":"將熱騰騰的炭烤黑豬肉香腸用力壓入糯米腸中間，裝入防油紙袋中。像夜市老饕一樣，將紙袋底部旋轉向上推擠，大口咬下爆汁香腸、軟糯米香與蒜辣酸菜的無敵三重奏！","en":"Firmly press the sizzling hot Taiwanese pork sausage into the stuffed rice pocket. Slide into a paper sleeve. Twist the bottom of the wrapper like a night market pro to push it up and take a giant, crunchy, juicy bite!","ja":"アツアツの台湾ソーセージを中央にグッと挟み込み、耐油紙袋に入れます。紙袋の底をくるくる回して押し出しながら、豪快にかぶりつきましょう！","ko":"뜨거운 소시지를 가운데 꽉 눌러 끼워 넣고 종이봉투에 담습니다. 야시장 프로처럼 봉투 밑을 돌려가며 위로 밀어 올려 한 입 가득 베어 물어 드세요!","vi":"Ấn chặt thanh xúc xích nướng nóng hổi vào chính giữa rồi cho vào túi giấy chống dầu. Xoay tròn đáy túi đẩy lên cắn ngập miệng đầy thỏa mãn!"},"image":"/images/tw/sausage-in-rice.jpg","durationSeconds":30}],"troubleshooting":[{"id":"ts-sr-1","problem":{"zh-TW":"糯米腸切開時散成碎米粒？","en":"Why did my sticky rice sausage crumble into loose rice when sliced?","ja":"切る時にもち米ソーセージがバラバラに崩れてしまう？","ko":"찹쌀 소시지를 자를 때 밥알이 부서져 흐트러지나요?","vi":"Tại sao thanh xôi bị tơi vỡ vụn khi rạch dao?"},"cause":{"zh-TW":"糯米腸還是完全冰冷狀態下刀，或者刀子不夠鋒利。","en":"Sliced while cold straight out of fridge, or using a dull serrated knife.","ja":"冷たいまま切ったか、包丁の切れ味が悪いためです。","ko":"냉장 상태에서 차가울 때 잘랐거나 칼이 무디기 때문입니다.","vi":"Cắt lúc xôi còn lạnh ngắt trong tủ lạnh hoặc dao cùn."},"solution":{"zh-TW":"先微烤或微波加熱 30 秒至微溫軟糯，刀刃抹微量香油，一刀滑順切開即可！","en":"Warm sausage in microwave for 30s first. Wipe knife blade with a drop of oil for a clean cut.","ja":"レンジで30秒ほど温めて柔らかくし、包丁に薄く油を塗ってから切ると綺麗に切れます！","ko":"전자레인지에 30초 돌려 살짝 따뜻하게 만든 후, 칼에 기름을 살짝 발라 자르면 부서지지 않습니다.","vi":"Quay lò vi sóng 30 giây cho ấm mềm, thoa chút dầu lên dao rồi rạch dứt khoát."}}],"proTips":[{"zh-TW":"大蒜一定要「現切新鮮生大蒜片」，大蒜的天然辛辣素能完美中和五花肉香腸的油脂，是台灣夜市不外傳的解膩神技！","en":"Freshly sliced raw garlic is mandatory! The sharp allicin cuts through the rich pork fat like magic.","ja":"生のニンニクスライスは絶対に欠かせません！ニンニクの辛味がソーセージの脂っこさを爽やかにリセットしてくれます。","ko":"갓 썬 생마늘 편은 필수입니다! 생마늘의 알싸함이 기름진 맛을 완벽하게 잡아줍니다.","vi":"Tỏi sống thái lát tươi là linh hồn bắt buộc phải có để khử ngấy mỡ xúc xích cực đỉnh."}]},{"country":"tw","id":"beef-noodle-soup","slug":"beef-noodle-soup","title":{"zh-TW":"台北川味紅燒半筋半肉牛肉麵","en":"Taiwanese Braised Beef Shank & Tendon Noodle Soup","ja":"台北名物 絶品紅焼牛肉麺（牛スネ肉＆牛すじ）","ko":"대만 정통 홍샤오 뉴러우멘 (우육면)","vi":"Mì bò sốt vang gân bắp Đài Loan (Beef Noodle Soup)"},"subtitle":{"zh-TW":"牛腱牛筋慢熬濃郁紅湯・岡山豆瓣醬與酸菜靈魂組合","en":"Rich Red-Braised Broth, Tender Shank & Translucent Tendons","ja":"牛スネ肉と牛すじの極上ダブル具材＆濃厚ピリ辛スープ","ko":"진한 우사골 홍탕에 부드러운 아롱사태와 쫀득한 스지","vi":"Nước dùng đỏ sánh đậm đà ngập tràn gân bò và bắp hoa bò"},"tagline":{"zh-TW":"米其林必比登推薦！台灣享譽全球的國寶級麵食","en":"The Michelin-celebrated national dish of Taiwan","ja":"ミシュラン・ビブグルマン絶賛！世界が認めた台湾の国民的麺料理","ko":"미슐랭 빕구르망이 사랑한 대만 최고의 국보급 면 요리","vi":"Món mì quốc bảo của Đài Loan nức tiếng khắp thế giới"},"heroImage":"/images/tw/beef-noodle-soup.jpg","difficulty":"hard","prepTimeMinutes":30,"cookTimeMinutes":90,"defaultServings":4,"caloriesPerServing":640,"category":"soups","dietaryTags":["classic","halal"],"supportedCookware":["traditional","instantPot"],"culture":{"originCity":{"zh-TW":"台北永康街 / 高雄岡山","en":"Taipei Yongkang / Kaohsiung Gangshan","ja":"台北・永康街 / 高雄・岡山","ko":"타이베이 융캉제 / 가오슝 강산","vi":"Đài Bắc Yongkang / Cao Hùng"},"famousNightMarkets":[{"zh-TW":"永康牛肉麵 / 林東芳牛肉麵","en":"Yongkang Beef Noodles","ja":"永康牛肉麺","ko":"융캉 뉴러우멘","vi":"Mì bò Yongkang"},{"zh-TW":"饒河街夜市","en":"Raohe Night Market","ja":"饒河街夜市","ko":"라오허제 야시장","vi":"Chợ đêm Raohe"}],"historyStory":{"zh-TW":"1949年隨國民政府遷台的四川老兵，在高雄岡山以豆瓣醬、花椒結合台灣本產黃牛肉燉製成第一碗「川味紅燒牛肉麵」，隨後在台北永康街與西門町發揚光大。濃郁帶甘甜的紅燒湯頭配上手切花紋牛腱與軟糯牛筋，是世界旅人來台必吃第一名。","en":"Created by Sichuan veteran soldiers in Kaohsiung in the 1950s using fermented chili bean paste and aromatics with beef shanks, this dish evolved into Taiwan's world-famous culinary masterpiece with noodle shops across Taipei.","ja":"1950年代に四川出身の軍人が高雄で豆板醤や八角を用いて作ったのがルーツ。台北・永康街などで進化を遂げ、今や世界中から観光客が訪れる台湾を代表する名物料理となりました。","ko":"1950년대 사천 출신 참전 군인들이 고향의 두반장과 향신료를 대만산 소고기와 접목해 만든 음식입니다. 타이베이 융캉제를 중심으로 발전하여 오늘날 대만을 대표하는 세계적인 요리가 되었습니다.","vi":"Bắt nguồn từ những năm 1950 do những người lính Tứ Xuyên kết hợp tương ớt đậu bản với bắp bò và gân bò hầm nhừ, tạo nên món mì bò trứ danh của Đài Bắc."},"taiwaneseHokkien":"Gû-bah-mī (ㄍㄨˊ ㄅㄚ ㄇㄧˇ)","mandarinPinyin":"Niúròumiàn (ㄋㄧㄡˊ ㄖㄡˋ ㄇㄧㄢˋ)","audioPronunciationText":"老闆，一碗紅燒半筋半肉麵，寬麵加酸菜"},"ingredients":[{"id":"beef-shank","name":{"zh-TW":"牛腱心 (金錢腱 / 花腱)","en":"Beef Shank (Shin with Marbled Tendons)","ja":"牛スネ肉（すじの入った上質部位）","ko":"소 아롱사태 (마블링 좋은 부위)","vi":"Bắp hoa bò (Bắp bò nhiều gân)"},"amount":600,"unitMetric":"g","unitUS":"1.3 lbs","isKeyFlavor":true,"chineseName":"牛腱心","chinesePinyin":"Niú jiàn xīn"},{"id":"beef-tendon","name":{"zh-TW":"熟牛筋 (或生牛蹄筋)","en":"Beef Tendon (Pre-cooked or raw)","ja":"牛すじ（アキレス腱）","ko":"소 스지 (소 힘줄)","vi":"Gân bò"},"amount":300,"unitMetric":"g","unitUS":"0.7 lbs","isKeyFlavor":true,"chineseName":"牛筋","chinesePinyin":"Niú jīn"},{"id":"spicy-bean-paste","name":{"zh-TW":"台灣岡山辣豆瓣醬 (或郫縣豆瓣)","en":"Taiwanese Spicy Fermented Bean Paste (Doubanjiang)","ja":"台湾産 辛口豆板醤（岡山豆瓣醤）","ko":"대만 강산 두반장 (매콤한 두반장)","vi":"Tương hột ớt cay Đài Loan (Đậu bản tương)"},"amount":45,"unitMetric":"g","unitUS":"2.5 tbsp","isKeyFlavor":true,"chineseName":"辣豆瓣醬","chinesePinyin":"Là dòubàn jiàng","substitute":{"substituteName":{"zh-TW":"四川郫縣豆瓣醬 + 1茶匙糖","en":"Sichuan Pixian Broad Bean Paste + 1 tsp sugar","ja":"四川ピィシェン豆板醤＋砂糖小さじ1","ko":"피현 두반장 + 설탕 1작은술","vi":"Tương ớt đậu bản Tứ Xuyên + 1 thìa đường"},"ratio":"1:1","explanation":{"zh-TW":"台灣岡山辣豆瓣醬微甜醇厚，若用四川豆瓣醬偏鹹辣，補一茶匙糖即可完美還原台灣風味。","en":"Taiwanese Doubanjiang is sweeter. If using Sichuan style, add 1 tsp sugar to balance salinity.","ja":"台湾の豆板醤は甘みがあります。中華の豆板醤を使う場合は砂糖を少し加えて調整してください。","ko":"대만 두반장은 감칠맛과 단맛이 돌아, 일반 두반장 사용 시 설탕을 약간 더해주세요.","vi":"Đậu bản tương Đài Loan có vị ngọt dịu, nếu dùng tương Tứ Xuyên hãy thêm 1 thìa đường."},"whereToBuy":{"zh-TW":"各大亞超 (尋找岡山明德豆瓣醬或金蘭)","en":"99 Ranch, H-Mart (Ming Teh or Kimlan brands)","ja":"アジア食材店、中華スーパー","ko":"중국 식자재 몰","vi":"Siêu thị đồ Hoa"}}},{"id":"beef-spice-satchel","name":{"zh-TW":"牛肉麵滷包 (八角+花椒+桂皮+草果+甘草)","en":"Beef Spice Sachet (Star Anise, Sichuan Pepper, Cinnamon, Tsaoko, Licorice)","ja":"特製スパイスバッグ（八角、花椒、シナモン、草果）","ko":"우육면 한방 향신료 팩 (팔각+화조+계피+초과)","vi":"Gói thảo mộc hầm bò (Hoa hồi, thảo quả, quế, tiêu Tứ Xuyên)"},"amount":1,"unitMetric":"bag","unitUS":"1 pack","isKeyFlavor":true,"chineseName":"牛肉滷包","chinesePinyin":"Niú ròu lǔ bāo"},{"id":"tomatoes-beef","name":{"zh-TW":"新鮮熟番茄 (切大塊熬湯自然果酸)","en":"Ripe Tomatoes (Cut into Wedges for Natural Umami)","ja":"完熟トマト（旨味と酸味用）","ko":"완숙 토마토 (감칠맛과 자연스러운 산미)","vi":"Cà chua chín mọng"},"amount":2,"unitMetric":"piece","unitUS":"2 whole","chineseName":"牛番茄","chinesePinyin":"Niú fān qié"},{"id":"taiwanese-noodles","name":{"zh-TW":"台灣陽春拉麵或手工刀削麵","en":"Fresh Taiwanese Wheat Noodles or Knife-Cut Noodles","ja":"台湾生ラーメンまたは手打ち刀削麺","ko":"대만식 굵은 생면 또는 도삭면","vi":"Mì tươi sợi to hoặc mì dao gọt Đài Loan"},"amount":400,"unitMetric":"g","unitUS":"14 oz","chineseName":"陽春拉麵","chinesePinyin":"Yáng chūn lā miàn"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"牛腱牛筋汆燙與手切厚塊","en":"Blanch Beef Shank & Tendon, Cut Thick Chunks","ja":"牛スネ肉と牛すじの下茹で＆極厚カット","ko":"소고기 사태와 스지 데치기 및 두툼하게 썰기","vi":"Chần bắp bò, gân bò và thái miếng dày"},"instruction":{"zh-TW":"牛腱與牛筋冷水下鍋，加入薑片、蔥段、米酒，大火煮滾 8 分鐘去除血水與雜質。撈出用冷水洗淨表面，用刀切成約 2.5 公分的厚實大塊（煮後會縮小，切大塊才有吃肉快感！）。","en":"Place whole beef shank and tendon in cold water with ginger, scallions, and rice wine. Boil for 8 mins, skim scum, and rinse in cold water. Slice into thick 2.5cm chunks (beef shrinks while braising, so cut large!).","ja":"牛スネ肉と牛すじを生姜、ネギ、酒と水から煮て8分下茹でしアクを抜きます。冷水で洗い、2.5cmの分厚い一口大にカットします（煮込むと縮むため大きめに切るのがコツ！）。","ko":"사태와 스지를 생강, 대파, 맛술과 함께 찬물에 넣고 8분간 끓여 불순물을 뺍니다. 찬물에 헹궈 2.5cm 두께로 큼직하게 썹니다 (익으면서 줄어들므로 큼직해야 식감이 좋습니다).","vi":"Cho bắp bò và gân bò vào nồi nước lạnh cùng gừng, hành lá và rượu luộc 8 phút hớt bọt. Rửa sạch thái miếng dày 2.5cm."},"image":"/images/tw/beef-step1.jpg","durationSeconds":600},{"stepNumber":2,"title":{"zh-TW":"爆香辛香料與煸炒紅亮豆瓣醬","en":"Stir-Fry Aromatics & Caramelize Doubanjiang","ja":"香味野菜を炒め、豆板醤の赤い旨味油を引き出す","ko":"향신채 볶기 및 두반장 고추기름 내기","vi":"Phi thơm thảo mộc và xào tương đậu bản lên màu đỏ đẹp"},"instruction":{"zh-TW":"深鍋中倒入 2 大匙油，下拍碎大蒜、老薑片、洋蔥塊、八角、花椒粒與肉桂棒中火爆香 3 分鐘。加入 45g 辣豆瓣醬與 25g 冰糖，以中小火慢炒 2 分鐘，炒出紅亮誘人的紅油香氣！","en":"Heat 2 tbsp oil in pot over medium flame. Add crushed garlic, sliced ginger, onion, star anise, peppercorns, and cinnamon stick for 3 mins. Add 45g Doubanjiang and 25g rock sugar, stirring for 2 mins until fragrant red oil bubbles.","ja":"鍋に油大さじ2を熱し、ニンニク、生姜、玉ねぎ、八角、花椒、シナモンを3分炒めます。豆板醤45gと氷砂糖25gを加え、赤い香味油が立つまでじっくり炒め合わせます！","ko":"냄비에 기름 2큰술을 두르고 마늘, 생강, 양파, 팔각, 화조를 3분간 볶습니다. 두반장 45g과 빙탕 25g을 넣고 중약불에서 붉은 고추기름 향이 피어오를 때까지 볶아줍니다.","vi":"Đun nóng 2 thìa dầu, phi thơm tỏi đập dập, gừng, hành tây, hoa hồi, quế trong 3 phút. Cho tương ớt đậu bản và đường phèn vào đảo 2 phút lên màu dầu đỏ óng."},"image":"/images/tw/beef-step2.jpg","durationSeconds":300},{"stepNumber":3,"title":{"zh-TW":"加入牛肉番茄、慢火熬燉濃郁高湯","en":"Add Beef, Tomatoes & Simmer Rich Broth","ja":"牛肉・トマト・煮込みパックを加え、極上スープを煮込む","ko":"소고기, 토마토, 한방팩 넣고 푹 끓이기","vi":"Cho thịt bò, cà chua và gói thảo mộc ninh nước dùng"},"instruction":{"zh-TW":"【傳統燉鍋】：倒入切塊牛腱牛筋翻炒上色，沿鍋邊淋入醬油 80ml 與米酒 50ml 熗香。加入番茄塊、滷包與清水 1800ml。大火煮滾後轉微小火，加蓋慢燉 80~90 分鐘至牛腱軟爛入味、牛筋晶瑩軟Q。\n【電壓力鍋】：High Pressure 壓 35 分鐘自然洩壓。","en":"Traditional Pot: Add beef chunks, searing with 80ml soy sauce and 50ml rice wine. Add tomato wedges, spice pouch, and 1800ml water. Bring to boil, cover and simmer on low for 80-90 mins until shank is meltingly tender and tendons are translucent gelatin.\nInstant Pot: High Pressure for 35 mins + Natural Release.","ja":"【普通鍋】：牛肉を加えて炒め、醤油80mlと酒50mlを回し入れます。トマト、スパイスパック、水1800mlを加え、沸騰後フタをして弱火で80〜90分コトコト煮込みます。\n【圧力鍋】：高圧で35分加熱、自然減圧。","ko":"【일반 냄비】：소고기를 넣고 볶다가 간장 80ml와 맛술 50ml를 둘러 향을 입힙니다. 토마토, 한방팩, 물 1800ml를 붓고 끓으면 약불로 줄여 뚜껑 덮고 80~90분간 푹 조립니다.\n【인스턴트팟】：High Pressure 35분 후 자연 감압。","vi":"Nồi thường: Cho bắp bò vào đảo săn, rưới nước tương và rượu. Thêm cà chua, gói thảo mộc và 1.8L nước, ninh nhỏ lửa 80-90 phút cho bắp bò mềm rục gân trong veo.\nNồi áp suất: High Pressure 35 phút xả van tự nhiên."},"image":"/images/tw/beef-step3.jpg","durationSeconds":5400,"cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Manual High Pressure: 35 mins + Natural Release","instructionOverride":{"zh-TW":"在 Instant Pot 內用 Sauté 模式炒香辛料與豆瓣醬，加入肉塊、番茄、醬油、水與滷包。鎖蓋設定 Meat/Stew 模式 35 分鐘，自然洩壓後開蓋，牛筋軟糯如同果凍！","en":"Use Sauté mode to brown aromatics and beef. Add liquid, tomatoes, and spice pouch. Lock lid, select High Pressure for 35 mins. Natural Release for melt-in-mouth tendons!","ja":"Instant PotのSautéモードで炒めた後、水と調味料を加え高圧35分。自然減圧すれば牛すじがゼリーのようにとろけます！","ko":"인스턴트팟 Sauté 모드로 볶은 후 물과 재료를 넣고 High Pressure 35분 설정 후 자연 감압하면 스지가 젤리처럼 부드러워집니다.","vi":"Dùng chế độ Sauté xào thơm nguyên liệu, thêm nước rồi chọn High Pressure 35 phút xả van tự nhiên."}}]},{"stepNumber":4,"title":{"zh-TW":"滾水煮拉麵與汆燙翠綠青菜","en":"Boil Springy Wheat Noodles & Bok Choy","ja":"たっぷりのお湯でモチモチ麺と青菜を茹でる","ko":"쫄깃한 생면 삶기 및 청경채 데치기","vi":"Luộc mì sợi dai và chần cải thìa xanh mướt"},"instruction":{"zh-TW":"另起大鍋滾水，下台灣陽春麵或刀削麵煮約 4~5 分鐘至彈牙筋道，起鍋前 30 秒下小白菜或青江菜一同汆燙。撈起瀝乾水分，平均分裝入大青花瓷碗中。","en":"In a large pot of boiling water, cook noodles for 4-5 mins until al dente. Drop in bok choy for the final 30 secs. Drain well and divide into large ceramic serving bowls.","ja":"別鍋に湯を沸かし、麺を4〜5分茹でてアルデンテに仕上げます。最後の30秒で青菜を加えてサッと茹で、水気をしっかり切って大きめの丼に入れます。","ko":"다른 냄비에 끓는 물을 넉넉히 붓고 면을 4~5분간 쫄깃하게 삶아냅니다. 건지기 30초 전 청경채를 넣어 살짝 데치고, 물기를 털어 큰 대접에 담습니다.","vi":"Đun sôi nước luộc mì 4-5 phút cho chín tới dai giòn, 30 giây cuối thả cải thìa vào chần. Vớt ra để ráo chia đều vào tô lớn."},"image":"/images/tw/beef-step4.jpg","durationSeconds":300},{"stepNumber":5,"title":{"zh-TW":"澆上濃醇紅湯，鋪滿牛腱牛筋與炒酸菜！","en":"Ladle Rich Red Broth, Garnish with Pickled Greens","ja":"熱々の濃厚スープを注ぎ、肉・牛すじ・酸菜を盛り付けて完成！","ko":"진한 육수를 붓고 사태, 스지, 볶은 갓절임 고명 얹어 완성!","vi":"Chan ngập nước dùng đậm đà, xếp bắp bò gân bò và dưa chua thưởng thức!"},"instruction":{"zh-TW":"在麵碗上整齊鋪上切厚片的軟嫩牛腱心與晶瑩牛筋，擺上翠綠青菜。舀入滾燙濃醇的紅燒牛肉高湯，撒上一大把新鮮蔥花，加一滿勺靈魂炒酸菜（嗜辣者淋一匙辣牛油），大口開動！","en":"Arrange thick beef shank slices and translucent tendons over the noodles. Ladle boiling rich red-braised soup to fill the bowl. Top with fresh chopped scallions and a heap of Taiwanese sour pickled mustard greens (and beef chili tallow). Enjoy!","ja":"麺の上に極厚牛スネ肉、とろける牛すじ、青菜を美しく並べます。熱々の濃厚スープをたっぷり注ぎ、刻みネギと山盛りの酸菜（お好みで特製牛脂ラー油も）を添えていただきます！","ko":"면 위에 두툼한 사태와 쫀득한 스지, 청경채를 얹고 뜨거운 육수를 듬뿍 붓습니다. 쫑쫑 썬 대파와 볶은 갓절임 고명을 듬뿍 얹어 맛있게 드세요!","vi":"Xếp bắp bò thái dày, gân bò dẻo trong và cải thìa lên bát mì. Chan nước dùng sôi sùng sục, rắc hành hoa và múc một thìa dưa chua xào thưởng thức ngay!"},"image":"/images/tw/beef-noodle-soup.jpg","durationSeconds":60}],"troubleshooting":[{"id":"ts-bn-1","problem":{"zh-TW":"牛肉燉完柴柴的咬不動？","en":"Why is my beef tough and dry instead of melt-in-mouth tender?","ja":"煮込んだお肉が固くてパサパサしてしまう？","ko":"소고기가 질기고 퍽퍽한가요?","vi":"Tại sao thịt bò bị dai khô không mềm tan?"},"cause":{"zh-TW":"燉煮火候太大（大火會使肉質蛋白質緊縮變硬），或是燉煮時間不足。","en":"Boiled on high heat (which seizes muscle fibers) or didn't braise long enough.","ja":"強火でグラグラ煮すぎたか、煮込み時間が短いためです。","ko":"강불로 팔팔 끓였거나(단백질이 수축함), 끓이는 시간이 부족했기 때문입니다.","vi":"Đun lửa quá lớn làm thớ thịt co cứng hoặc ninh chưa đủ thời gian."},"solution":{"zh-TW":"水滾後務必轉「最小微火」加蓋慢燉至少 80 分鐘，微火慢煨才能將肉筋化作膠質！","en":"Always turn flame to ultra-low simmer after boiling, covered, for at least 80 mins.","ja":"沸騰後は必ず「極弱火」にしてフタをし、80分以上じっくり煮込んでください！","ko":"끓어오른 후 반드시 가장 약한 약불로 줄여 80분 이상 은근하게 끓여주세요.","vi":"Bắt buộc hạ lửa thật nhỏ đậy vung ninh tối thiểu 80 phút cho gân thịt nhừ mềm."}}],"proTips":[{"zh-TW":"牛肉麵的靈魂伴侶是「炒酸菜」與「牛辣油」，酸菜中的微酸能激發牛肉的甘甜鮮美，吃一半後加入酸菜能品嚐出第二種層次！","en":"Adding Taiwanese pickled mustard greens halfway through eating unlocks a second dimension of flavor, cutting the richness and boosting beef umami.","ja":"途中で「酸菜（高菜漬け）」を加えると、酸味とコクがプラスされ二度美味しく楽しめます！","ko":"절반쯤 드신 후 볶은 갓절임(쏸차이)과 매콤한 우지를 넣으면 국물 맛이 한 단계 더 깊어집니다.","vi":"Ăn nửa bát rồi cho thêm dưa chua xào và ớt mỡ bò sẽ đánh thức tầng hương vị thứ hai bùng nổ."}]},{"country":"tw","id":"mango-shaved-ice","slug":"mango-shaved-ice","title":{"zh-TW":"盛夏巨無霸鮮芒果雪花冰","en":"Taiwanese Fresh Mango Shaved Snow Ice","ja":"台湾名物 完熟マンゴー雪花氷（ふわふわかき氷）","ko":"대만 프리미엄 생망고 눈꽃빙수 (망궈빙)","vi":"Bingsu xoài tươi Đài Loan ngập tràn sữa đặc (Mango Snow Ice)"},"subtitle":{"zh-TW":"屏東愛文芒果切大塊・綿密牛奶雪花冰與煉乳奶蓋","en":"Sweet Irwin Mango Chunks, Silky Milk Ribbon Ice & Condensed Milk","ja":"完熟アップルマンゴー山盛り×極上ミルク雪花氷×練乳","ko":"달콤한 애플망고 가득・부드러운 우유 눈꽃 얼음과 연유의 앙상블","vi":"Xoài chín ngọt mọng xắt khối to & Lớp tuyết sữa bào mềm tan như lụa"},"tagline":{"zh-TW":"CNN 評選全球最佳甜點之一！盛夏台灣最璀璨的黃金傳奇","en":"Ranked by CNN as one of the world's top desserts","ja":"CNN「世界一のデザート」選出！台湾の夏を象徴する黄金のスイーツ","ko":"CNN 선정 세계 최고의 디저트! 대만의 여름을 대표하는 황금빛 축제","vi":"Được CNN bình chọn là một trong những món tráng miệng ngon nhất thế giới"},"heroImage":"/images/tw/mango-shaved-ice.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":310,"category":"desserts","dietaryTags":["vegetarian","halal","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北永康街 / 屏東枋山 / 台南玉井","en":"Taipei Yongkang / Pingtung / Tainan Yujing","ja":"台北・永康街 / 屏東 / 台南・玉井","ko":"타이베이 융캉제 / 핑둥 / 타이난 위징","vi":"Đài Bắc Yongkang / Bình Đông / Đài Nam"},"famousNightMarkets":[{"zh-TW":"永康街 (思慕昔 / 冰館創始地)","en":"Yongkang Street (Smoothie House)","ja":"永康街（思慕昔）","ko":"융캉제 스무시 하우스","vi":"Phố Yongkang (Smoothie House)"},{"zh-TW":"士林夜市 (辛發亭雪花冰)","en":"Shilin Night Market (Xin Fa Ting)","ja":"士林夜市（辛發亭）","ko":"스린 야시장 신파팅","vi":"Chợ đêm Shilin"}],"historyStory":{"zh-TW":"1997年台北永康街「冰館」老闆首創將屏東枋山與台南玉井的特級「愛文芒果」切成巨型果肉塊，鋪在由牛奶製成的綿密雪花冰磚上，淋上純濃煉乳與自製鮮芒果泥，引發全台灣與全亞洲的芒果冰狂潮，更被 CNN 評為世界最佳夏日甜品。","en":"Invented on Taipei's Yongkang Street in 1997, vendors layered sweet Pingtung Irwin mango chunks over fluffy shaved milk snow ribbons, drizzled with sweet condensed milk and fresh mango purée. It sparked a global dessert phenomenon.","ja":"1997年に台北・永康街の「冰館（現・思慕昔）」が開発。極甘の完熟マンゴーを贅沢に山盛りにし、フワフワのミルクかき氷に練乳とマンゴーソースを合わせた伝説のスイーツです。","ko":"1997년 타이베이 융캉제에서 시작되어 전 세계적인 망고 빙수 열풍을 일으킨 원조 디저트입니다. 부드러운 우유 눈꽃 얼음 위에 신선하고 달콤한 망고를 가득 얹고 연유를 듬뿍 뿌려 즐깁니다.","vi":"Ra đời năm 1997 tại phố Yongkang Đài Bắc, món ăn kết hợp xoài tươi mọng nước trên lớp tuyết sữa bào mịn tan chảy cùng sữa đặc ngọt béo."},"taiwaneseHokkien":"Suān-kó-ping (ㄙㄨㄞㄣˇ ㄍㄜˋ ㄅㄧㄥ)","mandarinPinyin":"Mángguǒ bīng (ㄇㄤˊ ㄍㄨㄛˇ ㄅㄧㄥ)","audioPronunciationText":"老闆，大碗芒果雪花冰，加一球芒果冰淇淋"},"ingredients":[{"id":"fresh-mango","name":{"zh-TW":"特級熟成愛文芒果 (或新鮮金煌芒果)","en":"Ripe Sweet Mangoes (Irwin, Kent or Honey Mango)","ja":"完熟マンゴー（アップルマンゴーまたはペリカンマンゴー）","ko":"완숙 생망고 (애플망고 또는 골드망고)","vi":"Xoài cát chín mọng ngọt lịm"},"amount":2,"unitMetric":"piece","unitUS":"2 large","isKeyFlavor":true,"chineseName":"愛文芒果","chinesePinyin":"Ài wén máng guǒ"},{"id":"condensed-milk","name":{"zh-TW":"台灣雀巢鷹牌煉乳 (或優質煉乳)","en":"Sweetened Condensed Milk","ja":"加糖練乳（コンデンスミルク）","ko":"달콤한 연유","vi":"Sữa đặc có đường"},"amount":40,"unitMetric":"ml","unitUS":"2.5 tbsp","isKeyFlavor":true,"chineseName":"煉乳","chinesePinyin":"Liàn rǔ"},{"id":"whole-milk-ice-block","name":{"zh-TW":"自製濃醇牛奶雪花冰磚 (全脂鮮奶+煉乳+鮮奶油)","en":"Homemade Milk Snow Block (Whole milk + Condensed milk + Heavy cream)","ja":"特製ミルク氷（牛乳＋練乳＋生クリームを凍らせたもの）","ko":"홈메이드 우유 눈꽃 얼음 (우유+연유+생크림 얼린 것)","vi":"Đá tuyết sữa đặc chế (Sữa tươi + Sữa đặc + Kem béo đông lạnh)"},"amount":300,"unitMetric":"ml","unitUS":"1.2 cups","isKeyFlavor":true,"chineseName":"牛奶雪花冰磚","chinesePinyin":"Niú nǎi xuě huā bīng zhuān"},{"id":"mango-ice-cream","name":{"zh-TW":"芒果冰淇淋或香草冰淇淋","en":"Mango or Vanilla Ice Cream Scoop","ja":"マンゴーアイス または バニラアイス","ko":"망고 아이스크림 또는 바닐라 아이스크림","vi":"Viên kem xoài hoặc kem vani"},"amount":1,"unitMetric":"scoop","unitUS":"1 scoop","chineseName":"芒果冰淇淋","chinesePinyin":"Máng guǒ bīng qí lín"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製與冷凍濃醇牛奶雪花冰磚","en":"Mix & Freeze Rich Milk Snow Ice Block","ja":"濃厚ミルク液を作り、冷凍庫で凍らせる","ko":"부드러운 우유 얼음 베이스 만들어 얼리기","vi":"Pha và đông lạnh khối tuyết sữa béo ngậy"},"instruction":{"zh-TW":"將全脂鮮奶 250ml、煉乳 30ml、鮮奶油 30ml 與細糖 15g 攪拌均勻至完全融化。倒入圓形保鮮盒或專用製冰盒中，放入冷凍庫冷凍至少 6 小時成堅硬的牛奶冰磚。","en":"Whisk together 250ml whole milk, 30ml condensed milk, 30ml heavy cream, and 15g sugar until dissolved. Pour into a container and freeze for at least 6 hours into a solid milk block.","ja":"牛乳250ml、練乳30ml、生クリーム30ml、砂糖15gをよく混ぜ合わせます。容器に注ぎ、冷凍庫で6時間以上しっかり凍らせて特製ミルク氷を作ります。","ko":"우유 250ml, 연유 30ml, 생크림 30ml, 설탕 15g을 잘 섞어 녹입니다. 용기에 담아 냉동실에서 6시간 이상 단단하게 얼려 우유 얼음을 만듭니다.","vi":"Khuấy đều 250ml sữa tươi, 30ml sữa đặc, 30ml kem béo và 15g đường. Đổ vào khuôn trữ đông tối thiểu 6 tiếng thành khối đá sữa."},"image":"/images/tw/mango-step1.jpg","durationSeconds":300},{"stepNumber":2,"title":{"zh-TW":"現切香甜愛文芒果大果肉塊","en":"Slice Ripe Irwin Mangoes into Giant Cubes","ja":"完熟マンゴーを贅沢な大粒サイコロ状にカットする","ko":"신선한 완숙 생망고 큼직한 큐브로 썰기","vi":"Thái xoài chín mọng thành những khối vuông to"},"instruction":{"zh-TW":"將熟透的愛文芒果沿著果核兩側切下大片果肉。用刀尖在果肉上劃出約 2 公分的井字十字紋（切至果皮不切斷），接著用雙手從果皮底部往上頂翻開，用刀削下飽滿多汁的金黃芒果大丁。","en":"Slice off the two thick cheeks of ripe mango along the flat seed. Score a 2cm criss-cross pattern through flesh down to skin. Push the skin inside out to pop the cubes up, then slice cubes off into a bowl.","ja":"種を避けてマンゴーの両面を切り落とします。果肉に2cm角の格子状の切り込みを入れ、皮を裏返してポコッと浮かせ、ナイフでダイス状に切り取ります。","ko":"망고 씨를 피해 양쪽 과육을 도톰하게 잘라냅니다. 2cm 크기로 바둑판 모양 칼집을 낸 뒤 껍질을 뒤집어 숟가락이나 칼로 큼직한 망고 조각을 떼어냅니다.","vi":"Cắt hai má xoài theo chiều dọc hạt. Khía hình bàn cờ 2cm trên thịt quả rồi lộn ngược vỏ để cắt lấy các khối xoài vàng óng mọng nước."},"image":"/images/tw/mango-step2.jpg","durationSeconds":240},{"stepNumber":3,"title":{"zh-TW":"熬製純天然鮮芒果濃縮果醬淋醬","en":"Simmer Pure Natural Fresh Mango Purée Glaze","ja":"余ったマンゴーで特製濃厚マンゴーソースを作る","ko":"남은 망고로 100% 천연 망고 퓨레 시럽 만들기","vi":"Nấu sốt xoài tươi tự nhiên thơm ngát"},"instruction":{"zh-TW":"將靠近果核周圍的碎芒果肉放入小碗中，加入 1 茶匙檸檬汁與 1 茶匙糖，用叉子或料理棒打成細滑的濃稠芒果泥，冷藏作為最後提味的純天然淋醬。","en":"Place scrap mango pulp around seed into a small bowl with 1 tsp lemon juice and 1 tsp sugar. Blend or crush into a silky smooth mango puree glaze and chill.","ja":"種の周りの果肉にレモン汁小さじ1と砂糖小さじ1を加え、ブレンダーやフォークでなめらかなマンゴーピュレにして冷やしておきます。","ko":"씨 주변의 과육을 모아 레몬즙 1작은술, 설탕 1작은술과 함께 블렌더로 곱게 갈아 시원하고 달콤한 천연 망고 시럽을 만듭니다.","vi":"Lấy phần thịt xoài cạnh hạt xay nhuyễn cùng 1 thìa cafe nước cốt chanh và 1 thìa đường làm sốt xoài sánh mịn thanh mát."},"image":"/images/tw/mango-step3.jpg","durationSeconds":180},{"stepNumber":4,"title":{"zh-TW":"刨出如絲絹羽毛般綿密牛奶雪花冰","en":"Shave Silky Snowflake Ribbons into High Mound","ja":"かき氷機で絹のようにふわふわの雪花氷を削る","ko":"빙수기로 눈꽃처럼 사르르 녹는 실타래 우유 얼음 갈기","vi":"Bào đá tuyết sữa mềm mịn như lụa xếp thành ngọn núi"},"instruction":{"zh-TW":"將牛奶冰磚放入雪花刨冰機中（或使用家用刨冰機調至最細檔位），一邊旋轉大碗一邊刨出層層疊疊、如絲絹緞帶般輕盈細膩的牛奶雪花冰，在碗中堆疊成一座小雪山！","en":"Place frozen milk block into shaved ice machine set to fine. Rotate bowl while shaving to form tall, delicate, ribbon-like snowflake layers that instantly melt on the tongue.","ja":"ミルク氷をかき氷機にセットし、最も細かい設定で削ります。器を回しながら、シルクのように繊細でフワフワな雪花氷を山盛りに削り出します！","ko":"우유 얼음을 빙수기에 넣고 가장 고운 눈꽃 입자로 갈아냅니다. 그릇을 돌려가며 깃털처럼 가볍고 사르르 녹는 우유 눈꽃을 소복하게 쌓아 올립니다.","vi":"Cho khối đá sữa vào máy bào nấc mịn nhất, vừa quay tô vừa bào những dải tuyết sữa mềm mịn bay bổng xếp thành núi tuyết nhỏ."},"image":"/images/tw/mango-step4.jpg","durationSeconds":120},{"stepNumber":5,"title":{"zh-TW":"鋪滿爆量芒果丁、淋上煉乳、放上冰淇淋！","en":"Cover in Mango Mountains, Condensed Milk & Ice Cream Scoop","ja":"マンゴーを隙間なく盛り、練乳を回しかけてアイスをトッピング！","ko":"망고 폭탄 투하, 연유 듬뿍 두르고 망고 아이스크림 한 스쿱 얹어 완성!","vi":"Phủ ngập xoài tươi, rưới sữa đặc và đặt viên kem xoài mát lạnh!"},"instruction":{"zh-TW":"在牛奶雪山四周鋪滿厚厚一層金黃愛文芒果大塊，頂部挖上一大球金黃芒果冰淇淋。淋上滿滿特製鮮芒果泥與香濃煉乳，插上薄荷葉點綴，盛夏最頂級的視覺與味覺饗宴！","en":"Surround the milk snow mountain completely with glistening mango cubes. Crown with a large scoop of mango ice cream. Drizzle generously with fresh mango purée and condensed milk. Garnish with fresh mint and dive in!","ja":"雪花氷の周りにマンゴーをこぼれ落ちるほど敷き詰め、頂上にマンゴーアイスを豪快にトッピング。特製マンゴーピュレと練乳をたっぷり回しかけて完成！","ko":"우유 눈꽃 주변에 망고 조각을 틈 없이 빽빽하게 두르고, 꼭대기에 망고 아이스크림 한 스쿱을 올립니다. 천연 망고 시럽과 연유를 듬뿍 뿌려 시원하게 즐기세요!","vi":"Xếp xoài kín quanh núi tuyết, đặt một viên kem xoài lên đỉnh rồi rưới đẫm sốt xoài tươi cùng sữa đặc thơm béo và thưởng thức!"},"image":"/images/tw/mango-shaved-ice.jpg","durationSeconds":60}],"troubleshooting":[{"id":"ts-ms-1","problem":{"zh-TW":"刨出來的冰顆粒粗大、像粗挫冰而不是綿密雪花？","en":"Why did my shaved ice turn out like crunchy crushed ice instead of fluffy snow ribbons?","ja":"フワフワにならず、ジャリジャリした粗いかき氷になってしまう？","ko":"부드러운 눈꽃이 아니라 서걱서걱한 얼음 알갱이가 갈리나요?","vi":"Tại sao đá bào bị lạo xạo hạt to không mịn như tuyết?"},"cause":{"zh-TW":"冰磚只用純水或水分太多，缺乏牛奶乳脂與糖分；或是刨冰機刀片調節得太粗。","en":"Used plain water without milkfat/sugar, or machine blade was set too thick.","ja":"水だけで作った氷か、乳脂肪や糖分が足りないため氷の結晶が固くなっています。","ko":"물로만 얼렸거나(유지방과 당분이 부족함), 빙수기 날이 너무 굵게 조절되었기 때문입니다.","vi":"Đá không có sữa đặc/kem béo tạo độ dẻo mịn hoặc lưỡi dao chỉnh quá thô."},"solution":{"zh-TW":"一定要按配方加入全脂鮮奶、煉乳與少許鮮奶油，乳脂與糖能阻止大冰晶生成，刨出來如同真雪！","en":"Always include whole milk, condensed milk, and cream. Fat and sugar prevent hard crystallization and yield pure silk snow.","ja":"必ず牛乳・練乳・生クリームを加えてください。乳脂肪分が滑らかな絹のような食感を生み出します！","ko":"레시피대로 전지분유나 우유, 연유, 생크림을 꼭 섞어 얼려주세요. 부드러운 텍스처의 비결입니다.","vi":"Bắt buộc dùng sữa tươi và kem béo, chất béo sẽ ngăn đá kết tinh cứng tạo ra tuyết mềm mượt."}}],"proTips":[{"zh-TW":"挑選芒果時一定要選擇散發濃郁果香、表皮帶有天然果膠光澤的「在欉紅」熟芒果，甜度與香氣才是台灣夜市冰品的最高境界！","en":"Choose naturally tree-ripened Irwin mangoes with an intoxicating tropical aroma and slight tackiness on the skin.","ja":"マンゴーは手で触れて少し柔らかく、甘い芳醇な香りが強く漂う完熟のものを使うと格段に美味しくなります！","ko":"진한 달콤한 향이 나고 껍질이 매끄럽고 윤기 나는 완숙 애플망고를 골라야 최고의 맛을 낼 수 있습니다.","vi":"Hãy chọn những quả xoài chín cây thơm nức mũi vỏ căng mọng để có món bingsu chuẩn vị nhất."}]},{"country":"tw","id":"pork-thick-soup","slug":"pork-thick-soup","title":{"zh-TW":"夜市鮮甜香濃肉羹湯","en":"Taiwanese Traditional Pork Thick Soup (Geng)","ja":"台湾夜市名物 つみれとろみスープ（肉羹湯）","ko":"대만 야시장 전통 고기 완자 걸쭉한 수프 (로우겅탕)","vi":"Súp Thịt Viên Đậm Đà Chợ Đêm Đài Loan"},"subtitle":{"zh-TW":"手打赤肉羹・柴魚白菜高湯・烏醋香菜靈魂提味","en":"Handmade Pork Strips, Bonito Cabbage Broth & Black Vinegar","ja":"手ごね豚肉つみれ・白菜と鰹出汁・黒酢とパクチーの極上風味","ko":"수제 돼지고기 완자, 가쓰오부시 배추 육수, 흑식초와 고수의 조화","vi":"Thịt nạc quết dai ngon, nước dùng bắp cải cá ngừ, giấm đen ngò rí"},"tagline":{"zh-TW":"滑順羹湯溫潤入喉，赤肉裹上薄漿彈牙爆汁，一口回魂的古早味","en":"Silky thick broth gliding down your throat with bouncy pork bites","ja":"とろりとしたスープが喉を潤し、ジューシーな豚つみれの弾力がたまらない懐かしい味","ko":"부드러운 국물과 쫄깃한 고기 완자가 입안 가득 감칠맛을 선사하는 추억의 맛","vi":"Nước súp sánh mịn ấm bụng, thịt viên dai ngọt đậm đà hương vị truyền thống"},"heroImage":"/images/tw/taiwan-pork-soup-hero.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":25,"defaultServings":4,"caloriesPerServing":320,"category":"soups","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originCity":{"zh-TW":"基隆 / 彰化鹿港","en":"Keelung / Lukang","ja":"基隆 / 彰化鹿港","ko":"지룽 / 장화 루강","vi":"Keelung / Lukang"},"famousNightMarkets":[{"zh-TW":"基隆廟口夜市","en":"Keelung Miaokou Night Market","ja":"基隆廟口夜市","ko":"지룽 먀오커우 야시장","vi":"Chợ đêm Keelung Miaokou"},{"zh-TW":"饒河街觀光夜市","en":"Raohe Night Market","ja":"饒河街夜市","ko":"라오허제 야시장","vi":"Chợ đêm Raohe"},{"zh-TW":"羅東夜市","en":"Luodong Night Market","ja":"羅東夜市","ko":"뤄둥 야시장","vi":"Chợ đêm Luodong"}],"historyStory":{"zh-TW":"「羹」在台灣飲食史中承載著先民物盡其用、以蕃薯粉勾芡保留食材原汁的智慧。基隆廟口與鹿港更發展出赤肉裹魚漿的獨門手藝，配上清甜大白菜與扁魚柴魚，是一代代台灣人的宵夜慰藉。","en":"Thick soup (Geng) represents traditional Taiwanese culinary wisdom using sweet potato starch to lock in richness. Keelung Miaokou perfected the craft of coating tender pork in fish paste.","ja":"台湾の「羹（とろみスープ）」はサツマイモ澱粉で出汁の旨味を凝縮させた郷土料理。基隆廟口の赤肉羹は夜市の定番です。","ko":"고구마 전분으로 육수의 풍미를 가두어 먹던 지혜에서 유래한 요리로, 지룽 먀오커우 등 대만 전역에서 사랑받습니다.","vi":"Món canh súp đặc trưng sử dụng bột khoai lang tạo độ sánh, giữ trọn vị ngọt thanh của thịt nạc quết chả cá."},"taiwaneseHokkien":"Bah-kinn-thng (ㄅㄚˊ ㄍㄧㄥ ㄊㄥ)","mandarinPinyin":"Ròu Gēng Tāng (ㄖㄡˋ ㄍㄥ ㄊㄤ)","audioPronunciationText":"肉羹湯，烏醋加多一點"},"ingredients":[{"id":"pork-strips","name":{"zh-TW":"豬後腿肉 (切粗條)","en":"Pork Loin Strips","ja":"豚もも肉細切り","ko":"돼지 안심 채","vi":"Thịt nạc mông heo thái sợi"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"chineseName":"豬後腿肉條","chinesePinyin":"Zhū hòutuǐ ròu tiáo"},{"id":"fish-paste","name":{"zh-TW":"虱目魚漿 (或旗魚漿)","en":"Whitefish Paste","ja":"白身魚すり身","ko":"생선 연육 반죽","vi":"Chả cá thác lác sống"},"amount":150,"unitMetric":"g","unitUS":"5 oz","isKeyFlavor":true,"chineseName":"魚漿","chinesePinyin":"Yú jiāng"},{"id":"cabbage","name":{"zh-TW":"大白菜 (切大塊)","en":"Napa Cabbage","ja":"白菜","ko":"배추","vi":"Bắp cải thảo"},"amount":200,"unitMetric":"g","unitUS":"7 oz","chineseName":"大白菜","chinesePinyin":"Dà bái cài"},{"id":"sweet-potato-starch","name":{"zh-TW":"台灣地瓜粉 (勾芡用)","en":"Sweet Potato Starch","ja":"サツマイモ澱粉","ko":"고구마 전분","vi":"Bột khoai lang"},"amount":40,"unitMetric":"g","unitUS":"3 tbsp","isKeyFlavor":true,"chineseName":"地瓜粉","chinesePinyin":"Dìguā fěn"},{"id":"black-vinegar","name":{"zh-TW":"工研烏醋","en":"Taiwanese Black Vinegar","ja":"台湾黒酢","ko":"대만 흑식초","vi":"Giấm đen Đài Loan"},"amount":25,"unitMetric":"ml","unitUS":"1.5 tbsp","chineseName":"烏醋","chinesePinyin":"Wū cù"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"抓醃肉條與摔打魚漿","en":"Marinate Pork & Knead with Fish Paste","ja":"豚肉の下味とすり身の練り合わせ","ko":"돼지고기 밑간 및 어육 반죽 치대기","vi":"Ướp thịt heo và quết với chả cá sống"},"instruction":{"zh-TW":"豬後腿肉條加入醬油、五香粉、白胡椒、蒜泥與米酒抓醃15分鐘，再與魚漿緊密揉勻摔打出筋度。","en":"Marinate pork strips with soy sauce, five-spice, white pepper, garlic & rice wine for 15m, then massage tightly with fish paste.","ja":"豚肉に醤油、五香粉、胡椒、おろしニンニク、料理酒を揉み込み15分置き、すり身とよく混ぜて粘りを出します。","ko":"돼지고기에 간장, 오향가루, 후추, 다진 마늘, 청주를 넣고 15분간 재운 뒤 생선 반죽과 치대어 찰기를 냅니다.","vi":"Ướp thịt heo với nước tương, ngũ vị hương, tiêu, tỏi băm và rượu gạo 15 phút, sau đó quết đều với chả cá sống."},"durationSeconds":900,"image":"/images/tw/taiwan-pork-soup-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"低溫微滾汆燙肉羹定型","en":"Poach Pork Strips at Gentle Simmer","ja":"微沸騰の湯で肉羹を茹でる","ko":"약불에서 고기 완자 데쳐내기","vi":"Luộc chín thịt viên ở lửa nhỏ"},"instruction":{"zh-TW":"煮一鍋水至微滾（約85-90°C保持冒小泡），用手將肉羹一條條捏入水中，待肉羹浮起變白即撈出瀝乾備用。","en":"Bring water to a gentle simmer (85-90°C), drop pork strips one by one. Once they float to surface and turn opaque, scoop out.","ja":"沸騰直前（85-90℃）の湯に肉羹を一口大ずつ落とし、浮き上がってきたらすくい上げて水気を切ります。","ko":"약하게 끓는 물(85-90°C)에 고기 반죽을 한 입 크기로 떼어 넣고, 위로 떠오르면 건져냅니다.","vi":"Nấu nước sôi lăn tăn, thả từng miếng thịt viên vào, khi thịt nổi lên mặt nước thì vớt ra để ráo."},"durationSeconds":360,"image":"/images/tw/taiwan-pork-soup-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"爆香香菇白菜熬高湯","en":"Simmer Cabbage & Shiitake Broth","ja":"椎茸と白菜の出汁を煮込む","ko":"표고버섯과 배추로 육수 끓이기","vi":"Nấu nước dùng bắp cải nấm hương"},"instruction":{"zh-TW":"鍋中熱油爆香香菇絲、扁魚（或蝦米），加入大白菜絲翻炒，注入大骨柴魚高湯大火煮滾，轉小火燉煮10分鐘至白菜軟甜。","en":"Sauté shiitake & dried flatfish in oil, add cabbage strips, pour in bone broth with bonito. Simmer 10m until cabbage softens.","ja":"油で椎茸と干し魚を炒め、白菜を加えて炒めたら豚骨鰹出汁を注ぎ、白菜が柔らかくなるまで10分煮ます。","ko":"팬에 버섯과 건생선을 볶다가 배추를 넣고 볶은 뒤 육수를 붓고 10분간 배추가 부드러워질 때까지 끓입니다.","vi":"Phi thơm nấm hương, cho bắp cải vào xào sơ rồi đổ nước hầm xương vào đun 10 phút cho bắp cải mềm ngọt."},"durationSeconds":600,"image":"/images/tw/taiwan-pork-soup-step3.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Soup Mode (High Pressure) for 12 mins","instructionOverride":{"en":"For Instant Pot: Add broth, bamboo shoots, and mushrooms into inner pot. Cook on Soup Mode (High Pressure) for 12 mins. Quick release, switch to Sauté mode to add pork geng and thicken with starch slurry.","zh-TW":"若使用電壓力鍋：高湯、竹筍絲與香菇絲倒入內鍋，選擇 Soup 模式高壓壓製 12 分鐘。手動洩壓後切換至 Sauté 開蓋拌煮，下肉羹並勾芡淋蛋花。","ja":"電気圧力鍋使用時：スープ、筍、椎茸を内釜に入れ「スープ／高圧」で12分加圧。減圧後に「炒めモード」で肉羹を加え、水溶き澱粉でとろみをつけます。","ko":"인스턴트팟 이용 시: 육수와 채소를 넣고 국/수프 모드(고압)로 12분간 조리합니다. 압력 배출 후 볶음 모드로 전환해 고기완자를 넣고 전분물을 풉니다.","th":"สำหรับหม้ออัดแรงดัน: ใส่น้ำซุปและผัก ใช้โหมด Soup นาน 12 นาที ปล่อยแรงดันแล้วเปิดโหมดผัด ใส่หมูเด้งและละลายแป้งให้ข้น"}}]},{"stepNumber":4,"title":{"zh-TW":"地瓜粉勾芡打蛋花盛裝","en":"Thicken with Starch Slurry & Finish","ja":"とろみをつけて溶き卵を回し入れ","ko":"전분물로 농도 맞추고 달걀물 풀기","vi":"Làm sánh nước súp và rưới trứng đánh tan"},"instruction":{"zh-TW":"放入煮好的肉羹，倒入調勻的地瓜粉水快速攪勻勾芡，淋入蛋花熄火。起鍋盛碗，淋上烏醋、白胡椒粉、香菜與九層塔。","en":"Add cooked pork strips, stir in starch slurry to thicken, drizzle beaten egg. Finish with black vinegar, white pepper & cilantro.","ja":"肉羹を戻し入れ、水溶き片栗粉でとろみをつけ、溶き卵を回し入れます。器に盛り、黒酢、胡椒、パクチーを添えます。","ko":"익힌 고기 완자를 넣고 전분물을 풀어 걸쭉하게 만든 뒤 달걀물을 두릅니다. 그릇에 담고 흑식초, 후추, 고수를 얹어 완성합니다.","vi":"Cho thịt viên vào lại nồi, rưới nước bột khoai lang để tạo độ sánh, thêm trứng đánh tan. Múc ra tô thêm giấm đen, tiêu và ngò."},"durationSeconds":240,"image":"/images/tw/taiwan-pork-soup-step4.jpg"}],"troubleshooting":[{"id":"soup-watery","problem":{"zh-TW":"羹湯勾芡冷卻後出水變稀？","en":"Soup turns watery after cooling down?","ja":"スープが冷めるとサラサラに戻ってしまう？","ko":"수프가 식으면서 묽어지나요?","vi":"Súp bị loãng ra sau khi nguội?"},"cause":{"zh-TW":"使用了普通太白粉，遇到醋酸容易水解回稀。","en":"Using cornstarch which breaks down rapidly when exposed to vinegar.","ja":"酸に弱い通常の片栗粉を使ったため。","ko":"식초의 산에 약한 일반 전분을 사용했기 때문입니다.","vi":"Dùng bột bắp thông thường dễ bị vữa khi gặp giấm chua."},"solution":{"zh-TW":"務必使用台灣傳統「粗粒地瓜粉」調水勾芡，保水性極強且耐酸耐熱！","en":"Always use sweet potato starch slurry which stays thick and glossy even with acid.","ja":"酸に強くツヤが保たれる台湾産サツマイモ澱粉を使用してください。","ko":"고구마 전분을 사용해야 식초를 넣어도 농도가 오래 유지됩니다.","vi":"Hãy dùng bột khoai lang nguyên chất để giữ độ sánh mượt lâu dài."}}],"proTips":[{"zh-TW":"起鍋前沿碗緣淋上一勺工研烏醋與少許沙茶醬，是全台灣夜市老饕公認的靈魂吃法！","en":"Drizzling Taiwanese black vinegar and a touch of Shacha sauce around the bowl edge is the authentic night market ritual!","ja":"仕上げに台湾黒酢と沙茶醤をひと回しするのが本場の通の食べ方です！","ko":"먹기 직전 대만 흑식초와 사차장을 한 바퀴 둘러주는 것이 현지 미식가들의 팁입니다!","vi":"Rưới một muỗng giấm đen và chút sốt Sa Trà quanh vành tô trước khi thưởng thức để dậy mùi thơm nức."}]},{"country":"tw","id":"taiwanese-egg-crepe","slug":"taiwanese-egg-crepe","title":{"zh-TW":"眷村手擀酥皮蔥花蛋餅","en":"Taiwanese Crispy Flaky Egg Crepe (Danbing)","ja":"台湾朝ごはん定番 サクサク葱パイたまご焼き（蛋餅）","ko":"대만식 바삭하고 쫄깃한 파 계란말이 크레페 (딴빙)","vi":"Bánh Tráng Trứng Chiên Giòn Hành Hoa Đài Loan"},"subtitle":{"zh-TW":"外酥內嫩金黃蔥香・爆漿起司・蒜蓉油膏經典早餐","en":"Flaky Golden Crust, Tender Egg, Scallion Aroma & Garlic Soy Paste","ja":"外はパリパリ中はふんわり・ネギの香りとニンニク醤油が絶品","ko":"겉바속촉 고소한 파향과 치즈 폭포, 달콤 짭짤한 마늘 간장소스","vi":"Vỏ giòn rụm bên trong mềm thơm, nhân phô mai trứng béo ngậy kèm sốt tỏi"},"tagline":{"zh-TW":"全台灣人最驕傲的早餐靈魂，每一口都是卡滋卡滋的酥脆麥香","en":"Taiwan’s most iconic morning ritual: golden crispy layers wrapped around fragrant scallion eggs","ja":"台湾人が毎朝愛してやまないソウルフード。香ばしい小麦の香りと卵のハーモニー","ko":"대만 사람들의 아침을 깨우는 영혼의 음식. 바삭바삭한 크러스트와 부드러운 달걀","vi":"Món ăn sáng quốc dân được yêu thích nhất Đài Loan với lớp vỏ giòn tan thơm lừng"},"heroImage":"/images/tw/taiwan-egg-crepe-hero.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":280,"category":"breakfast","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北 / 全台眷村","en":"Taipei / Military Villages","ja":"台北 / 眷村","ko":"타이베이 / 군인 마을","vi":"Đài Bắc / Khu gia binh"},"famousNightMarkets":[{"zh-TW":"台北華山阜杭豆漿","en":"Fuhang Soy Milk","ja":"阜杭豆漿","ko":"푸항또우장","vi":"Fuhang Soy Milk"},{"zh-TW":"寧夏夜市","en":"Ningxia Night Market","ja":"寧夏夜市","ko":"닝샤 야시장","vi":"Chợ đêm Ningxia"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"}],"historyStory":{"zh-TW":"蛋餅起源於戰後眷村北方麵食傳承，台灣早餐店將麵粉糊或手擀薄餅改良成外酥內軟、夾入雞蛋與蔥花的特色早點，現已風靡全球。","en":"Evolved from military villages blending Northern Chinese flatbreads with local Taiwanese morning culture into a global phenomenon.","ja":"台湾の軍人村（眷村）で誕生した小麦粉料理が進化し、今や世界中で愛される台湾朝ごはんの王様に。","ko":"군인 마을의 북방 밀가루 요리에서 발전하여 대만 대표 조식 메뉴로 자리잡았습니다.","vi":"Bắt nguồn từ các khu gia binh dung hòa ẩm thực bột mì miền Bắc với văn hóa ăn sáng Đài Loan."},"taiwaneseHokkien":"Nn̄g-piánn (ㄋㄥˊ ㄅㄧㄢˋ)","mandarinPinyin":"Dàn Bǐng (ㄉㄢˋ ㄅㄧㄥˇ)","audioPronunciationText":"蛋餅一份，加蛋加起司"},"ingredients":[{"id":"danbing-sheets","name":{"zh-TW":"手擀酥皮蛋餅皮","en":"Flaky Danbing Sheets","ja":"手ごね蛋餅の皮","ko":"딴빙 전용 피","vi":"Vỏ bánh đản bính"},"amount":2,"unitMetric":"piece","unitUS":"2 sheets","isKeyFlavor":true,"chineseName":"蛋餅皮","chinesePinyin":"Dàn bǐng pí"},{"id":"eggs","name":{"zh-TW":"新鮮雞蛋","en":"Fresh Eggs","ja":"新鮮な卵","ko":"신선한 계란","vi":"Trứng gà tươi"},"amount":2,"unitMetric":"piece","unitUS":"2 pcs","isKeyFlavor":true,"chineseName":"雞蛋","chinesePinyin":"Jī dàn"},{"id":"scallions","name":{"zh-TW":"細蔥花","en":"Minced Scallions","ja":"刻み青ネギ","ko":"송송 썬 쪽파","vi":"Hành lá băm"},"amount":30,"unitMetric":"g","unitUS":"1 oz","isKeyFlavor":true,"chineseName":"蔥花","chinesePinyin":"Cōng huā"},{"id":"garlic-soy-paste","name":{"zh-TW":"蒜蓉甜油膏","en":"Sweet Garlic Soy Paste","ja":"蒜蓉油膏","ko":"대만 마늘 간장 소스","vi":"Nước tương ngọt tỏi ớt"},"amount":20,"unitMetric":"ml","unitUS":"1 tbsp","chineseName":"蒜蓉油膏","chinesePinyin":"Suànróng yóugāo"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"打散蔥花蛋液","en":"Whisk Scallions into Eggs","ja":"ネギ入り卵液を溶きほぐす","ko":"파를 넣고 계란물 풀기","vi":"Đánh tan trứng với hành lá"},"instruction":{"zh-TW":"碗中打入雞蛋，加入大量新鮮翠綠細蔥花、少許鹽與白胡椒粉，用筷子充分攪打出細緻泡沫。","en":"Beat eggs in a bowl with generous minced scallions, pinch of salt and white pepper until frothy.","ja":"ボウルに卵を割り入れ、たっぷりの刻みネギ、塩、白胡椒を加えてよく溶きほぐします。","ko":"볼에 계란을 풀고 송송 썬 쪽파, 소금 약간, 백후추를 넣어 거품이 일도록 잘 섞어줍니다.","vi":"Đập trứng vào tô, thêm nhiều hành lá băm, chút muối và tiêu trắng rồi đánh đều cho sủi bọt."},"durationSeconds":120,"image":"/images/tw/taiwan-egg-crepe-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"熱鍋倒入蔥花蛋液攤開","en":"Pour Egg into Heated Pan","ja":"フライパンに卵液を流し入れる","ko":"예열된 팬에 파 계란물 붓기","vi":"Đổ trứng hành vào chảo nóng"},"instruction":{"zh-TW":"平底鍋中倒入一小匙油，中火熱鍋後倒入蔥花蛋液，迅速搖晃鍋身使蛋液均勻攤開成圓形。","en":"Heat 1 tsp oil in a non-stick skillet over medium heat, pour in scallion egg mixture and swirl into a round sheet.","ja":"フライパンに油小さじ1を熱し、ネギ入り卵液を一気に流し入れて丸く広げます。","ko":"팬에 기름을 두르고 중불로 예열한 뒤 파 계란물을 부어 둥글게 펼쳐줍니다.","vi":"Làm nóng chảo với chút dầu, đổ hỗn hợp trứng hành vào và láng đều thành hình tròn."},"durationSeconds":120,"image":"/images/tw/taiwan-egg-crepe-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"覆蓋餅皮翻面捲起","en":"Cover with Crepe & Roll","ja":"皮を重ねて裏返し巻く","ko":"피를 덮고 뒤집어 돌돌 말기","vi":"Đặt vỏ bánh lên lật mặt và cuộn tròn"},"instruction":{"zh-TW":"在半熟蛋液上立刻覆蓋上蛋餅皮，用鍋鏟輕壓貼合。待底部蛋香凝固翻面，鋪上起司片，由一端緊密捲成圓柱狀。","en":"Immediately place Danbing crepe on top of half-cooked egg, press down. Flip over, add cheese, and roll tightly into a cylinder.","ja":"卵が半熟のうちに蛋餅の皮を重ねて密着させます。裏返してチーズをのせ、端からくるくると巻きます。","ko":"계란이 반숙일 때 딴빙 피를 덮어 밀착시킵니다. 뒤집어서 치즈를 올리고 돌돌 말아줍니다.","vi":"Đặt vỏ bánh lên khi trứng còn hơi ướt, ấn nhẹ. Lật mặt bánh, thêm phô mai rồi cuộn tròn chặt tay."},"durationSeconds":180,"image":"/images/tw/taiwan-egg-crepe-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"切段裝盤淋蒜蓉醬油膏","en":"Slice and Drizzle Garlic Sauce","ja":"切り分けてニンニク醤油をかける","ko":"먹기 좋게 썰어 마늘 소스 뿌리기","vi":"Cắt khúc và rưới sốt tỏi ngọt"},"instruction":{"zh-TW":"將雙面煎至金黃酥脆的蛋餅移至砧板，用菜刀切成約 3cm 等寬小段裝盤，淋上靈魂蒜蓉醬油膏即可熱騰騰享用！","en":"Transfer golden crispy roll to cutting board, slice into 3cm pieces, and drizzle with sweet garlic soy paste.","ja":"両面がキツネ色にカリッと焼けたらまな板に取り出し、3cm幅に切って特製ニンニク甘醤油をかけて完成です！","ko":"노릇노릇 바삭하게 구워진 딴빙을 3cm 크기로 썰어 접시에 담고 특제 마늘 간장소스를 뿌려 완성합니다!","vi":"Cắt cuộn bánh giòn rụm thành từng khúc 3cm, xếp ra đĩa và rưới sốt tương ngọt tỏi ớt thơm lừng."},"durationSeconds":120,"image":"/images/tw/taiwan-egg-crepe-step4.jpg"}],"troubleshooting":[{"id":"crepe-separate","problem":{"zh-TW":"餅皮與蛋液分離沒有貼合？","en":"Crepe detaches from egg layer?","ja":"皮と卵がくっつかずに剥がれてしまう？","ko":"딴빙 피와 계란이 따로 노나요?","vi":"Vỏ bánh không dính chặt vào lớp trứng?"},"cause":{"zh-TW":"蛋液太熟才放餅皮，失去黏著力。","en":"Adding crepe after egg is already fully cooked.","ja":"卵が完全に固まってから皮をのせたため。","ko":"계란이 이미 다 익은 뒤에 피를 올렸기 때문입니다.","vi":"Đặt vỏ bánh lên khi trứng đã chín hoàn toàn."},"solution":{"zh-TW":"蛋液倒入鍋中趁「表面還呈現半熟濕潤狀」就要立刻蓋上餅皮，用鏟子均勻按壓！","en":"Lay crepe on top while egg surface is still wet and uncooked, pressing firmly.","ja":"卵が完全に固まる前の半熟の瞬間に皮をのせて軽く押さえてください。","ko":"계란 윗면이 촉촉할 때 피를 얹고 가볍게 눌러주어야 단단히 달라붙습니다.","vi":"Hãy đặt vỏ bánh lên ngay khi mặt trứng còn ướt và dùng xẻng ấn nhẹ."}}],"proTips":[{"zh-TW":"氣炸鍋懶人吃法：餅皮刷油 180°C 氣炸 3 分鐘立刻享有千層酥脆口感！","en":"Air Fryer Hack: Brush crepe with oil and air fry at 180°C for 3 mins for ultra-flaky layers!","ja":"エアフライヤーなら180℃で3分加熱するだけで驚きのサクサク感になります！","ko":"에어프라이어 꿀팁: 피에 기름을 살짝 발라 180°C에서 3분간 돌리면 크로와상처럼 바삭해집니다!","vi":"Mẹo nồi chiên không dầu: Quét dầu lên vỏ bánh nướng 180°C trong 3 phút để có lớp vỏ giòn rụm."}]},{"country":"tw","id":"taiwanese-coffin-bread","slug":"taiwanese-coffin-bread","title":{"zh-TW":"台南府城經典黃金棺材板","en":"Tainan Authentic Golden Coffin Bread","ja":"台南名物 黄金棺材板（サクサクトーストシチュー）","ko":"타이난 명물 황금 관재판 (크리미 해산물 토스트 박스)","vi":"Bánh Mì Quan Tài Vàng Giòn Đài Nam"},"subtitle":{"zh-TW":"酥炸厚片吐司盒子・濃郁滑順雞肉海鮮白醬・中西合璧傳奇","en":"Deep-Fried Golden Thick Toast Box with Creamy Seafood Chicken Chowder","ja":"カリッと揚げた厚切り食パンに濃厚クリーミー海鮮チキンシチュー","ko":"바삭하게 튀겨낸 두툼한 식빵 상자 속 진하고 고소한 해산물 치킨 크림스튜","vi":"Hộp bánh mì sandwich chiên giòn rụm ngập sốt kem hải sản thịt gà béo ngậy"},"tagline":{"zh-TW":"台南沙卡里巴發源的傳奇點心！外殼金黃酥脆，掀開滿溢絲滑海鮮濃香","en":"The legendary snack born in Tainan Sakariba! Crispy golden shell with velvety rich chowder","ja":"台南サカリバ発祥の伝説のグルメ。サクサクのパンを開けると熱々の特製シチューが溢れ出します","ko":"타이난 사카리바에서 시작된 전설의 길거리 음식! 바삭한 빵 뚜껑을 열면 크리미한 스튜가 가득","vi":"Món ăn huyền thoại xứ Đài Nam với vỏ bánh mì giòn tan cùng nhân sốt kem sánh mịn ngất ngây"},"heroImage":"/images/tw/taiwan-coffin-bread-hero.jpg","difficulty":"medium","prepTimeMinutes":15,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":450,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originCity":{"zh-TW":"台南沙卡里巴","en":"Tainan Sakariba","ja":"台南サカリバ","ko":"타이난 사카리바","vi":"Sakariba Đài Nam"},"famousNightMarkets":[{"zh-TW":"花園夜市","en":"Tainan Flower Night Market","ja":"花園夜市","ko":"화위안 야시장","vi":"Chợ đêm Tainan Flower"},{"zh-TW":"武聖夜市","en":"Wusheng Night Market","ja":"武聖夜市","ko":"무성 야시장","vi":"Chợ đêm Wusheng"},{"zh-TW":"花蓮東大門夜市","en":"Hualien Dongdamen Night Market","ja":"花蓮東大門夜市","ko":"화롄 둥다먼 야시장","vi":"Chợ đêm Dongdamen"}],"historyStory":{"zh-TW":"1940年代由台南「盛場老牌」名廚許六一先生研發。因將厚片吐司炸酥後填入西式白醬內餡，形狀似官木而得名「棺材板」，寓意「升官發財」，轟動全台。","en":"Invented in the 1940s by Chef Hsu Liu-yi in Tainan Sakariba, named after its box shape with auspicious meaning of wealth & promotion.","ja":"1940年代に台南で考案された料理。パンを棺に見立てたユニークなネーミングと出世・蓄財の縁起の良さで大ヒットしました。","ko":"1940년대 타이난 셰프가 개발한 요리로 관 모양을 닮아 관재판이라 불리며 승진과 재물을 부른다는 뜻을 담고 있습니다.","vi":"Được sáng tạo vào thập niên 1940 tại Đài Nam, mang ý nghĩa thăng quan phát tài với hình dáng chiếc hộp độc đáo."},"taiwaneseHokkien":"Kuan-tshâ-pán (ㄍㄨㄢ ㄘㄚ ㄅㄢˋ)","mandarinPinyin":"Guān Cai Bǎn (ㄍㄨㄢ ㄘㄞˊ ㄅㄢˇ)","audioPronunciationText":"棺材板一份，趁熱吃"},"ingredients":[{"id":"thick-toast","name":{"zh-TW":"厚片白吐司 (3.5cm厚)","en":"Thick Cut White Toast","ja":"厚切り食パン","ko":"두툼한 통식빵","vi":"Bánh mì sandwich gối cắt dày"},"amount":2,"unitMetric":"piece","unitUS":"2 slices","isKeyFlavor":true,"chineseName":"厚片吐司","chinesePinyin":"Hòupiàn tǔsī"},{"id":"chicken-thigh","name":{"zh-TW":"去骨雞腿肉丁","en":"Boneless Chicken Thigh","ja":"鶏もも肉角切り","ko":"닭다리살 깍둑썰기","vi":"Thịt đùi gà thái hạt lựu"},"amount":120,"unitMetric":"g","unitUS":"4 oz","chineseName":"雞肉丁","chinesePinyin":"Jī ròu dīng"},{"id":"shrimp","name":{"zh-TW":"鮮蝦仁與花枝丁","en":"Shrimp & Squid Chunks","ja":"エビ・イカ角切り","ko":"새우 및 오징어","vi":"Tôm tươi và mực hạt lựu"},"amount":80,"unitMetric":"g","unitUS":"3 oz","isKeyFlavor":true,"chineseName":"蝦仁花枝","chinesePinyin":"Xiārén huāzhī"},{"id":"milk","name":{"zh-TW":"鮮牛奶與鮮奶油","en":"Whole Milk & Heavy Cream","ja":"牛乳と生クリーム","ko":"우유 및 생크림","vi":"Sữa tươi và whipping cream"},"amount":200,"unitMetric":"ml","unitUS":"0.8 cup","chineseName":"鮮奶","chinesePinyin":"Xiān nǎi"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"酥炸厚片吐司成金黃盒子","en":"Deep-Fry Toast into Golden Box","ja":"厚切り食パンをキツネ色に揚げる","ko":"두툼한 식빵 바삭하게 튀겨내기","vi":"Chiên vàng giòn lát bánh mì sandwich dày"},"instruction":{"zh-TW":"油鍋加熱至 175°C，將厚片吐司整塊放入油鍋中，炸至六面金黃酥脆（或用氣炸鍋 185°C 雙面噴油氣炸 6 分鐘），撈起瀝油。","en":"Deep-fry thick toast in 175°C oil until all 6 sides are golden and crispy (or air-fry with oil spray at 185°C for 6m). Drain.","ja":"175℃の油で厚切り食パンを全面がきつね色にカリッとするまで揚げます（エアフライヤー185℃で6分でもOK）。","ko":"175°C 기름에 두툼한 식빵을 넣고 모든 면이 황금빛으로 바삭해질 때까지 튀겨냅니다 (에어프라이어 185°C 6분 가능).","vi":"Chiên ngập dầu lát bánh mì dày ở 175°C đến khi 6 mặt vàng giòn rụm (hoặc nồi chiên không dầu 185°C trong 6 phút)."},"durationSeconds":300,"image":"/images/tw/taiwan-coffin-bread-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"小刀開蓋挖空內部成盒","en":"Cut Square Lid & Hollow Inside","ja":"上部を切り開いて器を作る","ko":"뚜껑을 잘라내고 속 파내기","vi":"Cắt mở nắp và tạo lòng hộp rỗng"},"instruction":{"zh-TW":"用尖頭小刀沿炸好的酥脆吐司頂部邊緣 0.5cm 處切出一個四方形，揭開吐司薄蓋，用湯匙將吐司內部的白麵包輕輕壓實挖成盒子狀。","en":"Use a small knife to cut a square lid along top edges (0.5cm margin), lift lid and press inside to create a hollow bread box.","ja":"パンの上部をナイフで四角く切り込みを入れてフタを開け、中のパンをスプーンで軽く押し込んで器を作ります。","ko":"튀긴 빵 윗면에 네모나게 칼집을 내어 뚜껑을 열고, 숟가락으로 속을 꾹 눌러 속이 빈 상자 모양을 만듭니다.","vi":"Dùng dao nhỏ khía hình vuông trên mặt bánh, mở nắp và dùng muỗng nén nhẹ phần ruột bánh tạo thành chiếc hộp."},"durationSeconds":180,"image":"/images/tw/taiwan-coffin-bread-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 180°C (355°F) for 5-6 mins","instructionOverride":{"en":"For Air Fryer: Brush all sides of the thick toast slice with melted butter or oil. Air fry at 180°C (355°F) for 5-6 mins until deep golden and crisp on all sides, then cut out the lid.","zh-TW":"若使用氣炸鍋：厚片吐司六面均勻刷上融化奶油或沙拉油，放入氣炸鍋以 180°C 氣炸 5-6 分鐘至各面金黃酥脆，取出切開頂蓋。","ja":"ノンフライヤー使用時：厚切り食パンの全面に溶かしバターを塗り、180℃で5〜6分こんがりきつね色になるまで加熱し、フタを切り抜きます。","ko":"에어프라이어 이용 시: 두꺼운 식빵 표면에 녹인 버터를 바르고 180도에서 5~6분간 노릇하게 구운 뒤 뚜껑을 잘라냅니다.","th":"สำหรับหม้อทอดไร้น้ำมัน: ทาเนยละลายบนขนมปังหนา อบที่ 180°C นาน 5-6 นาทีจนเหลืองกรอบแล้วตัดฝาบนออก"}}]},{"stepNumber":3,"title":{"zh-TW":"炒製香濃海鮮雞肉白醬","en":"Cook Creamy Seafood Chowder","ja":"濃厚海鮮チキンシチューを作る","ko":"크리미한 해산물 치킨 스튜 끓이기","vi":"Nấu sốt kem hải sản thịt gà béo ngậy"},"instruction":{"zh-TW":"鍋中融化奶油炒香洋蔥丁，加入麵粉炒出微黃麵糊（Roux），分次注入牛奶與高湯拌勻至絲滑濃稠。下雞肉丁、蝦仁、三色豆煮熟，以鹽、白胡椒調味。","en":"Melt butter to sauté onions, stir in flour to make roux, whisk in milk & broth until silky. Add chicken, shrimp & peas, season with salt & pepper.","ja":"バターで玉ねぎを炒め、小麦粉を加えてルーを作り、牛乳と出汁で滑らかに伸ばします。具材を加えて煮込み味を調えます。","ko":"팬에 버터를 녹여 양파를 볶고 밀가루를 넣어 루를 만든 뒤 우유와 육수를 부어 크림소스를 만듭니다. 닭고기와 해산물을 넣고 익힙니다.","vi":"Xào thơm hành tây với bơ, rắc bột mì làm sốt roux rồi rót sữa tươi vào khuấy mịn. Thêm thịt gà, tôm, rau củ nấu chín nêm nếm vừa ăn."},"durationSeconds":360,"image":"/images/tw/taiwan-coffin-bread-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"滾燙濃湯灌入吐司盒裝盤","en":"Fill Toast Box with Hot Chowder","ja":"熱々シチューを注いで完成","ko":"토스트 상자에 스튜 가득 채우기","vi":"Đổ sốt kem nóng hổi vào hộp bánh mì"},"instruction":{"zh-TW":"將滾燙香濃的海鮮白醬舀入挖空的酥脆吐司盒中，直至九分滿，最後將吐司蓋半掩蓋上，趁熱大口咬下！","en":"Ladle bubbling hot creamy seafood chowder into the crispy bread bowl until 90% full, replace the lid partially, and serve hot!","ja":"熱々の濃厚シチューをトーストの器にたっぷり注ぎ、フタを半分かぶせてアツアツのうちにお召し上がりください！","ko":"바삭한 식빵 상자에 갓 끓인 뜨거운 크림스튜를 가득 채우고 뚜껑을 비스듬히 덮어 따뜻할 때 즐깁니다!","vi":"Múc sốt kem hải sản nóng hổi ngập 9 phần hộp bánh, đậy hờ nắp bánh mì và thưởng thức ngay khi còn nóng hổi!"},"durationSeconds":120,"image":"/images/tw/taiwan-coffin-bread-step4.jpg"}],"troubleshooting":[{"id":"toast-soggy","problem":{"zh-TW":"吐司很快被白醬泡軟變塌？","en":"Toast box becomes soggy too quickly?","ja":"トーストがシチューを吸ってすぐフニャフニャになる？","ko":"식빵이 스튜를 흡수해 금방 눅눅해지나요?","vi":"Hộp bánh mì nhanh bị ỉu do ngấm sốt?"},"cause":{"zh-TW":"油炸溫度不夠或吐司質地過於鬆軟。","en":"Oil temperature was too low or toast bread was too airy.","ja":"揚げ温度が低かったか、パンの気泡が粗すぎたため。","ko":"튀김 온도가 낮았거나 빵 조직이 너무 헐거웠기 때문입니다.","vi":"Nhiệt độ chiên chưa đủ cao hoặc ruột bánh quá xốp."},"solution":{"zh-TW":"選用厚片扎實的白吐司，炸至金黃酥硬結殼；白醬煮至濃稠再盛入，並立即趁熱享用！","en":"Use dense white bread fried until hard crispy shell forms, and make sure chowder is sufficiently thick.","ja":"密度の高い食パンをカリッと揚げ、シチューをしっかり煮詰めてから注いでください。","ko":"조직이 촘촘한 식빵을 바삭하게 튀기고, 스튜 농도를 걸쭉하게 끓여 즉시 드세요.","vi":"Chọn loại bánh mì đặc ruột, chiên thật giòn cứng và nấu sốt kem thật sánh đặc trước khi cho vào."}}],"proTips":[{"zh-TW":"選用台式傳統白吐司（質地較密實），炸出來的麵包盒才不易被濃湯泡軟滲漏！","en":"Use dense, traditional bakery white sandwich bread so the chowder doesn’t leak through the crust!","ja":"密度の高い食パンを使うことで、シチューを入れても染み出さずサクサクが長持ちします！","ko":"밀도가 높은 전통 식빵을 사용해야 스튜를 넣었을 때 빵이 쉽게 눅눅해지지 않습니다!","vi":"Nên chọn loại bánh mì gối ruột đặc để giữ sốt kem lâu mà không bị mềm nhũn."}]},{"country":"tw","id":"fried-milk","slug":"fried-milk","title":{"zh-TW":"夜市脆皮黃金炸牛奶","en":"Taiwanese Crispy Fried Milk","ja":"台湾夜市名物 揚げミルク（炸鮮奶）","ko":"대만 야시장 바삭한 우유튀김 (자셴나이)","vi":"Sữa tươi chiên giòn chợ đêm Đài Loan"},"subtitle":{"zh-TW":"外皮金黃酥脆・內餡濃醇奶香絲滑爆漿","en":"Golden Crispy Shell with Velvety Molten Milk Center","ja":"サクサクの衣と中からとろけ出す濃厚ミルククリーム","ko":"바삭한 튀김옷 속 부드럽고 달콤한 우유 크림이 주르륵","vi":"Vỏ giòn rụm tan trong miệng, nhân sữa tươi đặc sánh béo ngậy"},"tagline":{"zh-TW":"羅東夜市排隊傳奇，一口咬下奶香濃郁在舌尖化開的夢幻甜點","en":"The Luodong night market legend with a sweet molten milk surprise","ja":"羅東夜市の大人気スイーツ。熱々サクサク、口いっぱいに広がる優しい甘さ","ko":"뤄둥 야시장 줄 서서 먹는 전설의 디저트, 입안 가득 퍼지는 달콤한 우유 풍미","vi":"Món tráng miệng huyền thoại chợ đêm Luodong với nhân sữa tươi béo thơm ngất ngây"},"heroImage":"/images/tw/taiwan-fried-milk-hero.jpg","difficulty":"medium","prepTimeMinutes":30,"cookTimeMinutes":10,"defaultServings":3,"caloriesPerServing":280,"category":"desserts","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional","airFryer"],"culture":{"originCity":{"zh-TW":"宜蘭羅東 / 彰化","en":"Yilan Luodong / Changhua","ja":"宜蘭羅東 / 彰化","ko":"이란 뤄둥 / 장화","vi":"Luodong Yilan / Chương Hóa"},"famousNightMarkets":[{"zh-TW":"羅東夜市","en":"Luodong Night Market","ja":"羅東夜市","ko":"뤄둥 야시장","vi":"Chợ đêm Luodong"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"}],"historyStory":{"zh-TW":"源自傳統甜品，在宜蘭羅東夜市發揚光大。使用優質鮮奶與玉米澱粉慢火熬成奶糕，冷藏定型後穿上脆皮外衣高溫快炸，成為夜市人手一串的經典點心。","en":"Perfected at Luodong Night Market, fresh milk and cornstarch are cooked into a silky pudding, chilled firm, and flash-fried to golden perfection.","ja":"新鮮なミルクを固めてカリッと揚げた宜蘭・羅東夜市発祥の定番串スイーツ。","ko":"신선한 우유를 굳혀 바삭하게 튀겨낸 대만 야시장의 필수 디저트입니다.","vi":"Món ăn vặt từ sữa tươi nấu đặc đông lạnh, lăn bột chiên giòn tan xiên que."},"taiwaneseHokkien":"Tsiah-leng (ㄗㄚ ㄌㄧㄥ)","mandarinPinyin":"Zhà Niúnǎi (ㄓㄚˋ ㄋㄧㄡˊ ㄋㄞˇ)","audioPronunciationText":"老闆，來兩串現炸熱騰騰的炸牛奶"},"ingredients":[{"id":"whole-milk","name":{"zh-TW":"全脂鮮牛奶","en":"Whole Fresh Milk","ja":"牛乳","ko":"우유","vi":"Sữa tươi"},"amount":500,"unitMetric":"ml","unitUS":"2 cups","isKeyFlavor":true,"chineseName":"全脂鮮奶","chinesePinyin":"Quánzhī xiānnǎi"},{"id":"cornstarch","name":{"zh-TW":"玉米澱粉","en":"Cornstarch","ja":"コーンスターチ","ko":"옥수수 전분","vi":"Bột bắp"},"amount":60,"unitMetric":"g","unitUS":"0.5 cup","isKeyFlavor":true,"chineseName":"玉米澱粉","chinesePinyin":"Yùmǐ diànfěn"},{"id":"sugar","name":{"zh-TW":"細砂糖與煉乳","en":"Granulated Sugar & Condensed Milk","ja":"砂糖と練乳","ko":"설탕 및 연유","vi":"Đường và sữa đặc"},"amount":40,"unitMetric":"g","unitUS":"3 tbsp","chineseName":"白糖煉乳","chinesePinyin":"Báitáng liànrǔ"},{"id":"crispy-batter","name":{"zh-TW":"脆皮粉漿","en":"Crispy Batter Mix","ja":"天ぷら粉ミックス","ko":"튀김가루 반죽","vi":"Bột chiên giòn"},"amount":100,"unitMetric":"g","unitUS":"0.8 cup","chineseName":"脆皮粉漿","chinesePinyin":"Cuìpí fěnjiāng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"小火熬煮濃稠絲滑奶糕糊","en":"Cook Milk & Cornstarch into Smooth Paste","ja":"弱火でミルクペーストを練る","ko":"우유와 전분을 저어 걸쭉하게 끓이기","vi":"Khuấy sữa tươi với bột bắp trên lửa nhỏ"},"instruction":{"zh-TW":"將鮮奶、玉米澱粉、糖與煉乳倒入不沾鍋中充分攪勻。開微小火，順時針攪拌約 3~5 分鐘至凝結成光滑濃稠的奶糕糊。","en":"Whisk milk, cornstarch, sugar & condensed milk in pan. Stir continuously over low heat for 3-5 mins until smooth & pudding-like.","ja":"鍋に牛乳、コーンスターチ、砂糖を入れ、弱火でかき混ぜてクリーム状になるまで練ります。","ko":"팬에 재료를 넣고 약불에서 저어 푸딩처럼 부드럽고 걸쭉해질 때까지 끓입니다.","vi":"Khuấy đều sữa, bột bắp, đường trên lửa nhỏ cho đặc sánh mượt mà."},"durationSeconds":300,"image":"/images/tw/taiwan-fried-milk-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"入模冷藏定型並切成長條塊","en":"Chill to Set and Cut into Bars","ja":"冷やし固めてスティック状に切る","ko":"냉장실에서 굳힌 뒤 막대 모양으로 썰기","vi":"Đông lạnh rồi cắt thanh vừa ăn"},"instruction":{"zh-TW":"保鮮盒抹薄油，倒入奶糕抹平，貼面覆蓋保鮮膜冷藏 2 小時至完全凝固。倒扣切成 2x5cm 的長條奶糕塊。","en":"Pour into oiled container, cover surface with plastic wrap and chill 2 hours. Unmold and cut into 2x5cm rectangular bars.","ja":"容器に流し入れラップをして冷蔵庫で2時間冷やし固め、スティック状に切ります。","ko":"용기에 부어 랩을 씌우고 2시간 냉장 굳힌 뒤 직사각형 막대로 자릅니다.","vi":"Đổ vào khuôn bọc kín cho tủ lạnh 2 tiếng rồi cắt miếng dài đều nhau."},"durationSeconds":7200,"image":"/images/tw/taiwan-fried-milk-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"調製薄脆粉漿與均勻裹糊","en":"Mix Crispy Batter & Coat Bars","ja":"特製衣を作りミルクにまとわせる","ko":"튀김 반죽을 골고루 입히기","vi":"Pha bột chiên giòn và nhúng thanh sữa"},"instruction":{"zh-TW":"脆皮粉加水調成流動粉漿。奶糕條先拍上一層乾玉米粉，再均勻浸入脆皮粉漿中裹滿外層。","en":"Mix batter with cold water. Lightly dust milk bars with dry cornstarch, then submerge into wet batter.","ja":"天ぷら粉と冷水を混ぜ、ミルクに軽く粉をまぶしてから衣をしっかり絡めます。","ko":"튀김가루를 찬물에 개어 우유 스틱에 마른 전분을 묻힌 후 반죽을 듬뿍 입힙니다.","vi":"Lăn thanh sữa qua bột khô rồi nhúng đều vào âu bột chiên giòn ướt."},"durationSeconds":180,"image":"/images/tw/taiwan-fried-milk-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"高溫快炸至外殼金黃酥脆出鍋","en":"Flash Fry at High Heat to Golden Crisp","ja":"高温の油でカリッと短時間揚げる","ko":"고온에서 바삭하게 튀겨내기","vi":"Chiên nhanh tay cho vàng giòn rụm"},"instruction":{"zh-TW":"油溫加熱至 180°C，將裹好粉漿的牛奶條下鍋。大火快炸約 40~60 秒至外殼金黃酥脆，撈起瀝油插竹籤趁熱享用！","en":"Heat oil to 180°C (350°F). Flash fry for 40-60 secs until golden puffed shell forms. Drain immediately and serve hot!","ja":"180℃の油で40〜60秒間短時間で揚げ、油を切って竹串に刺し熱々をいただきます！","ko":"180°C 기름에 넣고 40-60초간 빠르게 튀겨 황금빛이 되면 바로 건져 꼬치에 꽂아 즐깁니다.","vi":"Thả vào dầu nóng 180°C chiên nhanh 40-60 giây cho vàng phồng vỏ ngoài, vớt ra xiên que thưởng thức."},"durationSeconds":60,"image":"/images/tw/taiwan-fried-milk-step4.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer 200°C (395°F): 6~8 mins (Spray Oil & Flip at 4 mins)","instructionOverride":{"zh-TW":"氣炸鍋預熱至 200°C。炸籃鋪上烘焙紙，將裹好粉漿的牛奶條排入（表面均勻噴上一層食用油）。以 200°C 氣炸 4 分鐘後拉出翻面補噴油，再氣炸 3~4 分鐘至表皮金黃硬脆、內餡滾燙絲滑爆漿！","en":"Preheat air fryer to 200°C (395°F). Line basket with parchment, place coated milk bars in and spray generously with oil. Air fry for 4 mins, flip, spray oil again and fry for 3-4 mins until golden crispy with a silky lava center!","ja":"ノンフライヤーを200℃に予熱。クッキングシートを敷き、衣をつけたミルクバーを並べて油をスプレー。200℃で4分加熱後、裏返して油を吹きさらに3〜4分加熱。外サク中トロに！","ko":"에어프라이어를 200°C로 예열합니다. 바스켓에 종이호일을 깔고 우유스틱을 올린 뒤 오일을 골고루 분사합니다. 4분 조리 후 뒤집어 오일을 뿌리고 3~4분 더 구우면 겉바속촉 완성!","vi":"Làm nóng nồi chiên không dầu ở 200°C, lót giấy nến, xếp thanh sữa vào xịt dầu đều. Nướng 4 phút rồi lật mặt xịt dầu nướng thêm 3-4 phút cho vỏ giòn tan nhân sữa tan chảy!"}}]}],"troubleshooting":[{"id":"melt-in-oil","problem":{"zh-TW":"炸的時候牛奶條融化流出？","en":"Milk bar melted and leaked?","ja":"揚げている途中で中身が溶け出す？","ko":"튀길 때 속이 터져 녹아내리나요?","vi":"Thanh sữa bị nứt chảy nhân khi chiên?"},"cause":{"zh-TW":"油溫過低或炸太久，或是奶糕未徹底冷藏凝固。","en":"Oil temp was too low or paste not chilled firm.","ja":"油温が低いか冷やす時間が不足していました。","ko":"기름 온도가 낮거나 굳히는 시간이 부족했습니다.","vi":"Dầu chưa đủ nóng hoặc chưa để đông đủ thời gian."},"solution":{"zh-TW":"冷藏足 2 小時，油溫保持 180°C 快炸 50 秒出鍋！","en":"Chill 2+ hours and flash fry at 180°C for only 50s!","ja":"しっかり冷やし、180℃で短時間揚げてください。","ko":"2시간 이상 굳히고 180°C에서 50초만 튀기세요.","vi":"Để tủ lạnh đủ 2 tiếng và chiên nhanh ở 180°C."}}],"proTips":[{"zh-TW":"加入 1 大匙煉乳，奶香更加濃郁醇厚，宛如熱騰騰的固態牛奶冰淇淋！","en":"Add condensed milk for ultra-luxurious dairy fragrance!","ja":"練乳を加えると格段にミルキーな味わいになります！","ko":"연유를 추가하면 고소한 풍미가 극대화됩니다!","vi":"Thêm sữa đặc giúp nhân thơm ngậy như kem sữa tươi tan chảy!"}]},{"country":"tw","id":"night-market-steak","slug":"night-market-steak","title":{"zh-TW":"台式夜市鐵板牛排","en":"Taiwanese Night Market Sizzling Steak","ja":"台湾夜市名物 熱々鉄板ステーキ","ko":"대만 야시장 철판 스테이크 (예스 뉴파이)","vi":"Bò bít tết chảo gang chợ đêm Đài Loan"},"subtitle":{"zh-TW":"滋滋作響鐵板・半熟太陽蛋・黃金油麵與雙醬交織","en":"Sizzling Cast Iron, Sunny Egg, Yellow Noodles & Dual Gravy","ja":"ジュージュー鳴る鉄板・半熟目玉焼き・台湾麺と特製ダブルソース","ko":"지글지글 철판 소리, 반숙 계란, 쫄깃한 면과 블랙페퍼/머쉬룸 소스","vi":"Chảo gang xèo xèo, trứng ốp la lòng đào, mì sợi vàng ngập sốt tiêu đen nấm"},"tagline":{"zh-TW":"全台夜市最霸氣的煙火氣！大塊原肉淋上滾燙雙醬的無敵滋味","en":"The most iconic sizzling performance in Taiwanese night markets","ja":"夜市で誰もが一度は食べる、豪快で熱々の鉄板ステーキ体験！","ko":"대만 야시장의 열기를 그대로 느낄 수 있는 가성비 최고의 철판 스테이크","vi":"Món ăn bùng nổ hương vị trên chảo gang nóng rực đặc trưng chợ đêm Đài Loan"},"heroImage":"/images/tw/taiwan-night-market-steak-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":650,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北師大 / 全台灣夜市","en":"Taipei Shida / All Night Markets","ja":"台北師大 / 全台湾夜市","ko":"타이베이 스다 / 대만 전역","vi":"Shida Đài Bắc / Toàn Đài Loan"},"famousNightMarkets":[{"zh-TW":"師大夜市","en":"Shida Night Market","ja":"師大夜市","ko":"스다 야시장","vi":"Chợ đêm Shida"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"}],"historyStory":{"zh-TW":"1970年代台灣夜市開創出平民化西餐形式。用高溫鑄鐵牛排盤盛裝厚切醃牛排、台式油麵與一顆生雞蛋，上桌時淋上滾燙黑胡椒醬與蘑菇醬，用紙巾擋油煙的儀式感風靡全台數十年。","en":"Invented in the 1970s making steak accessible to everyone, served on blazing iron skillets with noodles, egg and sizzling dual gravies.","ja":"1970年代に誕生した台湾式ステーキ。熱々の鉄板で肉、麺、卵を特製ソースで豪快に食す大人気庶民派グルメ。","ko":"1970년대 서민들을 위해 탄생한 요리로, 뜨거운 철판 위에 고기, 면, 계란을 올리고 소스를 뿌려 먹는 대표 야시장 메뉴입니다.","vi":"Xuất hiện từ thập niên 1970, món bò bít tết phục vụ trên chảo gang xèo xèo kèm mì vàng và trứng ốp la đã trở thành biểu tượng ẩm thực bình dân."},"taiwaneseHokkien":"Gû-phai (ㄍㄨˊ ㄆㄞˋ)","mandarinPinyin":"Yèshì Niúpái (ㄧㄝˋ ㄕˋ ㄋㄧㄡˊ ㄆㄞˊ)","audioPronunciationText":"老闆，牛排一份七分熟，醬要綜合雙醬"},"ingredients":[{"id":"sirloin-steak","name":{"zh-TW":"沙朗牛排或板腱牛排 (厚切)","en":"Thick Cut Sirloin / Flat Iron Steak","ja":"サーロインまたはミスジステーキ","ko":"두툼한 서로인 / 부채살 스테이크","vi":"Thăn bò cắt dày"},"amount":300,"unitMetric":"g","unitUS":"10 oz","isKeyFlavor":true,"chineseName":"厚切牛排","chinesePinyin":"Hòupiè niúpái"},{"id":"yellow-noodles","name":{"zh-TW":"台式油麵或螺旋麵","en":"Taiwanese Oil Noodles or Fusilli","ja":"台湾風油麺またはパスタ","ko":"대만식 옐로우 누들 또는 푸실리","vi":"Mì sợi vàng Đài Loan hoặc nui xoắn"},"amount":150,"unitMetric":"g","unitUS":"5 oz","chineseName":"油麵鐵板麵","chinesePinyin":"Yóumiàn"},{"id":"fresh-egg","name":{"zh-TW":"新鮮全蛋","en":"Fresh Eggs","ja":"新鮮な生卵","ko":"신선한 계란","vi":"Trứng gà tươi"},"amount":2,"unitMetric":"piece","unitUS":"2 eggs","chineseName":"生雞蛋","chinesePinyin":"Shēng jīdàn"},{"id":"steak-sauce","name":{"zh-TW":"特製黑胡椒醬與蘑菇醬 (綜合醬)","en":"Taiwanese Dual Steak Gravy (Black Pepper & Mushroom)","ja":"黒胡椒ソース＆マッシュルームソース","ko":"블랙페퍼 소스 및 머쉬룸 소스","vi":"Sốt tiêu đen và sốt nấm"},"amount":120,"unitMetric":"ml","unitUS":"0.5 cup","isKeyFlavor":true,"chineseName":"黑胡椒蘑菇綜合醬","chinesePinyin":"Hēihújiāo mógu jiàng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"牛排拍鬆與特製醃料入味","en":"Tenderize and Marinate Steak","ja":"肉をたたいて特製タレで下味をつける","ko":"고기를 두드려 부드럽게 한 뒤 밑간하기","vi":"Dần mềm thịt bò và ướp gia vị đậm đà"},"instruction":{"zh-TW":"牛排兩面用肉槌或刀背輕輕拍鬆斷筋。加入蒜末、少許醬油、黑胡椒粉、米酒與 1/2 小匙小蘇打粉抓勻醃漬 15 分鐘，口感鮮嫩多汁不柴。","en":"Tenderize steak with mallet. Marinate with minced garlic, soy sauce, black pepper, rice wine and pinch of baking soda for 15 mins.","ja":"肉の筋を叩いて切り、ニンニク、醤油、黒胡椒、酒で15分漬け込みジューシーに仕上げます。","ko":"고기망치로 가볍게 두드린 뒤 마늘, 간장, 후추, 맛술로 15분간 재워 육질을 부드럽게 만듭니다.","vi":"Dần nhẹ miếng thịt, ướp cùng tỏi băm, nước tương, tiêu đen và rượu trong 15 phút cho ngấm mềm."},"durationSeconds":900,"image":"/images/tw/taiwan-night-market-steak-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"大火炙煎牛排鎖住鮮甜肉汁","en":"Sear Steak on High Flame to Lock Juices","ja":"強火でステーキを一気に焼き肉汁を閉じ込める","ko":"센 불에서 스테이크를 노릇하게 구워 육즙 가두기","vi":"Áp chảo lửa lớn cho xém vàng hai mặt giữ trọn độ mọng nước"},"instruction":{"zh-TW":"平底鍋或鐵板燒熱至冒微煙，下 1 大匙牛油或奶油。放入牛排大火每面煎約 1.5~2 分鐘（7分熟），表面金黃微焦香，盛起靜置 2 分鐘。","en":"Heat pan with butter until sizzling hot. Sear steak on high heat 1.5-2 mins per side (medium doneness), rest for 2 mins.","ja":"フライパンにバターを熱し、強火で両面を1.5〜2分ずつ香ばしく焼き上げ、少し休ませます。","ko":"달군 팬에 버터를 두르고 센 불에서 양면을 1.5-2분씩 노릇하게 구워낸 뒤 2분간 레스팅합니다.","vi":"Đun nóng bơ trên chảo, áp chảo mỗi mặt 1.5-2 phút cho vàng nâu thơm lừng rồi để thịt nghỉ 2 phút."},"durationSeconds":300,"image":"/images/tw/taiwan-night-market-steak-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"滾燙鑄鐵盤煎荷包蛋與油麵","en":"Sizzle Noodles and Sunny Egg on Iron Pan","ja":"熱々の鉄板で麺と目玉焼きを豪快に焼く","ko":"뜨거운 철판에 면과 계란을 올려 지글지글 굽기","vi":"Đặt mì vàng và đập trứng ốp la lên chảo gang nóng bỏng"},"instruction":{"zh-TW":"將鐵板燒至高溫，刷上薄油。放入已汆燙的油麵，並在空位打入一顆新鮮全蛋，利用鐵板高溫將雞蛋底部煎至酥香焦脆、蛋黃保持流心。","en":"Heat cast iron plate blazing hot, brush with oil. Add boiled noodles and crack a fresh egg next to it, letting the bottom crisp up while yolk stays runny.","ja":"熱した鉄板に油をひき、茹でた麺をのせ、生卵を落とします。鉄板の余熱で卵がジュージューと焼けます。","ko":"철판을 아주 뜨겁게 달궈 기름을 두르고 삶은 면과 생계란을 올립니다. 계란 바닥이 바삭하게 익도록 둡니다.","vi":"Làm nóng chảo gang, quét dầu rồi xếp mì và đập trứng gà vào, lòng trắng xém giòn còn lòng đỏ dẻo mịn."},"durationSeconds":180,"image":"/images/tw/taiwan-night-market-steak-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"擺上厚切牛排、淋滾燙綜合雙醬！","en":"Top with Steak & Pour Dual Sizzling Gravies","ja":"ステーキをのせ、熱々の特製ダブルソースをかける！","ko":"스테이크를 얹고 특제 소스를 부어 지글지글 완성하기!","vi":"Đặt miếng bò lên trên và rưới ngập sốt tiêu nấm sôi sùng sục!"},"instruction":{"zh-TW":"將煎好的牛排鋪在鐵板麵旁，迅速淋上滾燙熱氣騰騰的黑胡椒蘑菇綜合醬，伴隨爆裂的滋滋聲與濃烈香氣，用紙巾半遮擋住油花，趁熱豪邁開吃！","en":"Place steak onto iron plate, immediately drench with bubbling black pepper & mushroom gravy. Grab a napkin to shield sizzling splatter and feast!","ja":"ステーキをのせ、熱々のダブルソースを一気に回しかけます！ジュージューと跳ねるソースをナプキンで防ぎながら熱々をいただきます！","ko":"고기를 올리고 뜨거운 블랙페퍼/머쉬룸 소스를 듬뿍 붓습니다. 냅킨으로 기름을 살짝 가리며 지글거리는 소리와 함께 맛있게 드세요!","vi":"Xếp miếng bò lên đĩa gang, rưới đẫm hỗn hợp sốt nóng hổi xèo xèo bốc khói nghi ngút rồi thưởng thức ngay lập tức!"},"durationSeconds":60,"image":"/images/tw/taiwan-night-market-steak-step4.jpg"}],"troubleshooting":[{"id":"steak-tough","problem":{"zh-TW":"牛排煎出來太硬咬不動？","en":"Why is my steak chewy & dry?","ja":"お肉が固くなってしまった？","ko":"고기가 질기고 퍽퍽한가요?","vi":"Thịt bò bị dai và khô cứng?"},"cause":{"zh-TW":"沒有斷筋或煎太久過熟。","en":"Fibers weren't tenderized or overcooked.","ja":"筋切りが不十分か、焼きすぎが原因です。","ko":"힘줄을 끊지 않았거나 너무 오래 구웠기 때문입니다.","vi":"Chưa dần đứt gân hoặc nấu quá lửa."},"solution":{"zh-TW":"用刀背拍鬆，大火快煎鎖住肉汁，起鍋後務必靜置 2 分鐘再切。","en":"Pound meat, sear on high heat and rest 2 mins.","ja":"しっかり肉を叩き、強火短時間で焼き休ませてください。","ko":"고기를 두드려 센 불에 굽고 2분간 레스팅하세요.","vi":"Dần mềm thịt, áp chảo nhanh lửa lớn và để thịt nghỉ trước khi ăn."}}],"proTips":[{"zh-TW":"夜市靈魂在於「綜合雙醬（蘑菇醬的清甜＋黑胡椒醬的辛香）」，兩者 1:1 調和是台灣人最愛的完美比例！","en":"The secret is the 50/50 dual blend of sweet tomato-mushroom and spicy black pepper gravies!","ja":"甘いマッシュルームソースと辛い黒胡椒ソースの1:1ブレンドが台湾夜市の黄金比です！","ko":"달콤한 머쉬룸 소스와 매콤한 블랙페퍼 소스를 1:1로 섞는 것이 야시장 단골들의 비법입니다!","vi":"Bí quyết chính là tỷ lệ 1:1 giữa sốt nấm ngọt dịu và sốt tiêu đen cay nồng chuẩn vị Đài Loan!"}]},{"country":"tw","id":"stinky-tofu","slug":"stinky-tofu","title":{"zh-TW":"經典夜市酥炸黃金臭豆腐","en":"Crispy Golden Taiwanese Stinky Tofu","ja":"本場台湾夜市 揚げ臭豆腐（炸臭豆腐）","ko":"대만 야시장 바삭한 황금 취두부 튀김 (처우더우푸)","vi":"Đậu hũ thối chiên giòn chợ đêm Đài Loan"},"subtitle":{"zh-TW":"外脆內爆汁・中心戳洞塞蒜泥醬・爽脆台式糖醋泡菜","en":"Crispy Puffed Shell, Garlic Soy Center & Sweet-Sour Pickled Cabbage","ja":"サクサク食感・特製にんにく醤油ダレ・さっぱり台湾風甘酢キャベツ漬け","ko":"바삭한 겉면과 촉촉한 속, 마늘간장 소스와 새콤달콤 대만식 양배추 피클","vi":"Vỏ giòn rụm bên trong mọng nước, chan sốt tỏi ớt kèm dưa chua bắp cải giòn sần sật"},"tagline":{"zh-TW":"聞著臭吃著香的極致夜市靈魂！金黃酥脆的臭豆腐狂熱","en":"The iconic paradox of Taiwanese street food: pungent aroma, unforgettable delicious taste","ja":"独特の香りと一度食べたら病みつきになるカリふわ食感！台湾屋台の真髄","ko":"냄새는 강렬하지만 한 입 베어 물면 잊을 수 없는 고소함과 감칠맛의 향연","vi":"Món ăn gây nghiện bậc nhất chợ đêm với hương vị độc đáo không thể chối từ"},"heroImage":"/images/tw/taiwan-stinky-tofu-hero.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":380,"category":"fried","dietaryTags":["classic","vegetarian","vegan"],"supportedCookware":["traditional","airFryer"],"culture":{"originCity":{"zh-TW":"新北深坑 / 全台灣夜市","en":"New Taipei Shenkeng / All Night Markets","ja":"新北深坑 / 全台湾夜市","ko":"신베이 선컹 / 대만 전역","vi":"Shenkeng Tân Bắc / Toàn Đài Loan"},"famousNightMarkets":[{"zh-TW":"饒河街觀光夜市","en":"Raohe Night Market","ja":"饒河街夜市","ko":"라오허제 야시장","vi":"Chợ đêm Raohe"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"},{"zh-TW":"深坑老街","en":"Shenkeng Old Street","ja":"深坑老街","ko":"선컹 라오제","vi":"Phố cổ Shenkeng"}],"historyStory":{"zh-TW":"源自傳統蔬菜發酵滷水醃漬豆腐，台灣夜市獨創「二次高低溫油炸法」，炸出外殼金黃酥脆如薄餅、內部多孔吸飽蒜泥醬汁的獨特口感，搭配酸甜爽脆的台式高麗菜泡菜，成為全台最富盛名的代表小吃。","en":"Fermented in natural herbal brine, Taiwanese night market vendors perfected the double-fry technique: low heat to cook through, flash high heat for puffing crisp crust. Pierced in the center and filled with garlic soy paste and pickled cabbage.","ja":"発酵液に漬け込んだ豆腐を二度揚げしてカリカリに仕上げ、ニンニク醤油と特製キャベツ漬けを添えて食べる台湾を代表する名物。","ko":"자연 발효액에 숙성한 두부를 두 번 튀겨내어 겉은 바삭하고 속은 부드럽게 만든 뒤 마늘 소스와 양배추 절임을 곁들여 먹는 국민 간식입니다.","vi":"Đậu hũ lên men gia truyền được chiên hai lần giòn rụm, chọc lỗ giữa để chan đẫm sốt tỏi ớt cay nồng ăn cùng dưa bắp cải chua ngọt thanh mát."},"taiwaneseHokkien":"Tshàu-tāu-hū (ㄘㄠˋ ㄉㄠ ㄏㄨ)","mandarinPinyin":"Chòu Dòufu (ㄔㄡˋ ㄉㄡˋ ㄈㄨˇ)","audioPronunciationText":"老闆，臭豆腐一份大辣，泡菜多一點"},"ingredients":[{"id":"stinky-tofu-blocks","name":{"zh-TW":"手工發酵臭豆腐 (正方形厚塊)","en":"Fermented Stinky Tofu Blocks","ja":"発酵臭豆腐（角型厚切り）","ko":"발효 취두부 (네모난 통두부)","vi":"Đậu hũ thối lên men (Cắt vuông dày)"},"amount":4,"unitMetric":"piece","unitUS":"4 squares","isKeyFlavor":true,"chineseName":"發酵臭豆腐","chinesePinyin":"Chòu dòufu"},{"id":"taiwan-pickled-cabbage","name":{"zh-TW":"台式糖醋高麗菜泡菜","en":"Taiwanese Sweet & Sour Pickled Cabbage","ja":"台湾風甘酢キャベツ漬け（泡菜）","ko":"대만식 새콤달콤 양배추 절임 (파오차이)","vi":"Dưa cải bắp ngâm chua ngọt Đài Loan"},"amount":150,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"chineseName":"台式泡菜","chinesePinyin":"Tái shì pàocài"},{"id":"garlic-soy-paste","name":{"zh-TW":"特調蒜泥油膏 (蒜泥+醬油膏+香油)","en":"Garlic Thick Soy Paste Sauce","ja":"おろしにんにく入り特製とろみ醤油","ko":"다진 마늘 데리야끼 소스","vi":"Sốt tương tỏi đặc sánh"},"amount":60,"unitMetric":"ml","unitUS":"4 tbsp","chineseName":"蒜泥油膏","chinesePinyin":"Suànní yóugāo"},{"id":"taiwan-chili-paste","name":{"zh-TW":"台灣生辣椒醬或豆瓣辣椒","en":"Taiwanese Fresh Red Chili Paste","ja":"台湾産 特製生チリペースト","ko":"대만식 생고추장","vi":"Ớt tươi xay cay nồng"},"amount":20,"unitMetric":"g","unitUS":"1 tbsp","chineseName":"生辣椒醬","chinesePinyin":"Làjiāo jiàng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"臭豆腐吸乾表面水分切塊","en":"Drain and Cut Tofu Squares","ja":"豆腐の水気を拭き取り四角く切る","ko":"취두부 물기를 제거하고 네모나게 썰기","vi":"Thấm khô nước trên bề mặt đậu hũ"},"instruction":{"zh-TW":"將臭豆腐用廚房紙巾徹底吸乾表面水分，防止油炸時噴油。可保持整塊大正方形，或對角斜切成三角形小塊。","en":"Thoroughly pat fermented tofu dry with paper towels to prevent oil splatter. Keep whole or slice diagonally into triangles.","ja":"油ハネを防ぐため、豆腐の表面の水気をキッチンペーパーでしっかり拭き取ります。","ko":"키친타월로 두부의 물기를 꼼꼼히 닦아내고 통으로 쓰거나 삼각형으로 자릅니다.","vi":"Dùng khăn giấy thấm thật ráo nước miếng đậu để tránh bị bắn dầu khi chiên."},"durationSeconds":180,"image":"/images/tw/taiwan-stinky-tofu-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"中溫油炸定型熟透","en":"First Fry at Medium Heat to Cook Through","ja":"中温の油でじっくり中まで火を通す","ko":"중온의 기름에서 속까지 골고루 1차 튀기기","vi":"Chiên lần 1 ở nhiệt độ vừa cho chín đều bên trong"},"instruction":{"zh-TW":"油鍋加熱至 150°C，將臭豆腐一塊塊輕輕放入。以中小火慢炸約 4~5 分鐘至豆腐微微浮起、外皮呈淡黃色結皮，撈起瀝油 2 分鐘。","en":"Heat oil to 150°C (300°F). Fry tofu over medium-low heat for 4-5 mins until floating and pale golden. Drain for 2 mins.","ja":"150℃の油に入れ、弱中火で4〜5分揚げて豆腐が浮き上がり薄いきつね色になったら一度取り出します。","ko":"150°C 기름에 넣고 중약불에서 4-5분간 천천히 튀겨 두부가 떠오르면 건져내어 2분간 기름을 뺍니다.","vi":"Thả đậu vào dầu 150°C chiên nhỏ lửa 4-5 phút cho nổi lên và se mặt vàng nhạt, vớt ra để ráo."},"durationSeconds":300,"image":"/images/tw/taiwan-stinky-tofu-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"高溫二次復炸搶酥膨脹","en":"Second Flash Fry at High Heat for Maximum Crispness","ja":"高温で二度揚げしてカリカリに膨らませる","ko":"고온에서 2차로 바삭하게 튀겨 팽창시키기","vi":"Chiên lần 2 lửa lớn cho vỏ ngoài phồng giòn rụm"},"instruction":{"zh-TW":"將油溫拉高至 190°C，再次下鍋大火高溫快炸 1~2 分鐘，外皮瞬間金黃膨脹、敲擊發出清脆聲響時迅速撈起瀝乾油分！","en":"Raise oil heat to 190°C (375°F). Flash fry tofu for 1-2 mins until puffed, deeply golden and shatteringly crisp. Drain well.","ja":"油温を190℃に上げ、一気に1〜2分強火で二度揚げし、外側をカリッとキツネ色に仕上げます！","ko":"기름 온도를 190°C로 올려 1-2분간 센 불에 빠르게 튀겨 바삭하고 황금빛으로 부풀어 오르면 건집니다.","vi":"Tăng nhiệt lên 190°C, thả đậu vào chiên nhanh 1-2 phút cho vỏ ngoài giòn rụm vàng ươm rồi vớt ra ngay."},"durationSeconds":120,"image":"/images/tw/taiwan-stinky-tofu-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer 200°C (395°F): 15 mins (Spray Oil & Flip at 8 mins)","instructionOverride":{"zh-TW":"臭豆腐切塊用廚房紙巾徹底吸乾水分，表面均勻刷或噴上一層食用油。放入預熱至 200°C 的氣炸鍋炸籃中，氣炸 8 分鐘後拉出翻面補噴少許油，再氣炸 7 分鐘至表皮金黃起泡膨脹、外脆內嫩！","en":"Thoroughly pat tofu cubes dry with paper towels. Brush or spray all sides generously with cooking oil. Air fry at 200°C (395°F) for 8 mins, flip, light oil spray and air fry 7 mins until golden puffed and super crispy!","ja":"豆腐の水気をペーパーで完全に拭き取り油を塗ります。200℃に予熱したノンフライヤーで8分加熱後、裏返して油を吹きさらに7分。表面がカリッと膨らむまで加熱します！","ko":"두부 물기를 완전히 제거하고 식용유를 골고루 바릅니다. 200°C로 예열된 에어프라이어에 넣고 8분 조리 후 뒤집어 오일을 뿌리고 7분 더 바삭하게 굽습니다.","vi":"Thấm khô hoàn toàn miếng đậu, quét dầu đều các mặt. Cho vào nồi chiên không dầu 200°C nướng 8 phút, lật mặt xịt dầu nướng thêm 7 phút cho vàng phồng giòn rụm."}}]},{"stepNumber":4,"title":{"zh-TW":"中央戳洞灌入蒜泥醬、配爽脆泡菜！","en":"Pierce Center, Fill with Garlic Sauce & Serve with Pickled Cabbage","ja":"中心に穴を開けて特製ニンニクタレを流し込み、泡菜を添える！","ko":"가운데 구멍을 뚫어 마늘소스를 붓고 양배추 절임 곁들이기!","vi":"Chọc thủng giữa rót sốt tỏi ớt và bày cùng dưa chua bắp cải!"},"instruction":{"zh-TW":"將炸好的酥脆臭豆腐排入盤中，用筷子在豆腐中心戳開一個小洞，灌入滿滿特調蒜泥醬油膏與辣椒醬，旁邊夾上一大坨爽脆多汁的台式糖醋泡菜，一口咬下爆汁過癮！","en":"Arrange crisp tofu on plate, poke a hole in the center of each block with chopstick, fill generously with garlic soy paste & chili. Serve alongside refreshing pickled cabbage!","ja":"箸で豆腐の真ん中に穴を開け、ニンニク醤油とチリソースをたっぷり注ぎます。シャキシャキの甘酢キャベツを添えて熱々をいただきます！","ko":"튀긴 두부 가운데를 젓가락으로 찔러 구멍을 내고 마늘간장 소스와 고추장을 듬뿍 채운 뒤 새콤한 양배추 절임을 곁들여 먹습니다.","vi":"Dùng đũa chọc thủng một lỗ giữa miếng đậu, chan đẫm sốt tỏi ớt vào lòng bánh rồi gắp kèm dưa bắp cải chua ngọt thưởng thức ngay!"},"durationSeconds":60,"image":"/images/tw/taiwan-stinky-tofu-step4.jpg"}],"troubleshooting":[{"id":"tofu-soggy","problem":{"zh-TW":"臭豆腐炸出來不夠酥脆、很快軟塌？","en":"Why isn't my stinky tofu crunchy enough?","ja":"揚げた臭豆腐がサクサクにならずベチャッとする？","ko":"취두부가 바삭하지 않고 눅눅한가요?","vi":"Đậu hũ chiên xong không đủ độ giòn xốp?"},"cause":{"zh-TW":"沒有經過二次高溫復炸，或是油溫不夠逼油。","en":"Skipped the second high-heat fry step.","ja":"二度揚げをしていないか、油の温度が低すぎました。","ko":"2차 고온 튀김을 건너뛰었거나 기름 온도가 낮았습니다.","vi":"Bỏ qua bước chiên lần hai lửa lớn ép dầu."},"solution":{"zh-TW":"必須分兩次炸：先 150°C 炸熟，再用 190°C 高溫大火搶酥 1 分鐘！","en":"Must double-fry: first 150°C to cook, then 190°C for 1 min to crisp!","ja":"150℃で火を通し、最後に190℃の強火でサッと二度揚げしてください！","ko":"150°C에서 익힌 뒤 190°C 고온에서 1분간 재벌 튀김을 하세요!","vi":"Bắt buộc chiên 2 lần: lần đầu 150°C và lần 2 ở 190°C trong 1 phút!"}}],"proTips":[{"zh-TW":"一定要用筷子在豆腐中心戳出小洞，將蒜泥醬油膏直接灌入多孔內部，搭配一口酸甜泡菜，才是正宗老饕吃法！","en":"Poke a hole to pour garlic sauce directly into the spongy interior, paired with cold pickled cabbage!","ja":"穴を開けてタレを中に染み込ませ、キャベツ漬けと一緒に頬張るのが本場の食べ方です！","ko":"두부 가운데 구멍을 내 소스를 듬뿍 채운 뒤 차가운 양배추 피클을 얹어 한입에 드세요!","vi":"Chọc lỗ rót sốt thẳng vào bên trong và ăn kèm dưa chua là phong cách thưởng thức chuẩn nhất!"}]},{"country":"tw","id":"taiwanese-ba-wan","slug":"taiwanese-ba-wan","title":{"zh-TW":"彰化傳承脆皮肉圓","en":"Changhua Crispy Fried Ba-Wan (Taiwanese Meat Disc)","ja":"彰化名物 外カリ中モチ肉団子（彰化肉圓）","ko":"대만 장화 전통 바삭 쫄깃 바완 (고기 딤섬)","vi":"Bánh Ba-wan thịt băm măng nấm giòn dẻo Chương Hóa"},"subtitle":{"zh-TW":"晶瑩Q彈外皮・大塊黑豬肉筍丁香菇・靈魂粉紅甜米醬","en":"Translucent Chewy Crust, Pork & Bamboo Shoot Filling & Sweet Pink Sauce","ja":"モチモチ半透明の生地・大粒豚肉とタケノコ椎茸餡・特製ピンクの甘ダレ","ko":"투명하고 쫄깃한 피, 큼직한 돼지고기・죽순・표고버섯 소, 핑크빛 달콤한 쌀 소스","vi":"Vỏ bột trong dẻo dai, nhân thịt heo măng giòn nấm hương cùng sốt hồng ngọt ngào"},"tagline":{"zh-TW":"《千與千尋》原型靈感美食！低溫泡油炸出極致彈牙的台灣奇蹟","en":"The real-world dish that inspired animated feasts: bouncy skin with savory meat","ja":"映画のモデルにもなった台湾屈指のB級グルメ！外はカリッ、中は驚きの弾力","ko":"애니메이션 먹방의 원조! 저온 기름에 튀겨 극강의 쫄깃함을 자랑하는 장화의 자랑","vi":"Món ăn trứ danh với lớp vỏ dẻo dai bao trọn nhân thịt đậm đà quyến rũ khó cưỡng"},"heroImage":"/images/tw/taiwan-ba-wan-hero.jpg","difficulty":"hard","prepTimeMinutes":45,"cookTimeMinutes":25,"defaultServings":4,"caloriesPerServing":420,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"彰化縣 / 北斗","en":"Changhua / Beidou","ja":"彰化県 / 北斗","ko":"장화현 / 베이더우","vi":"Chương Hóa / Bắc Đẩu"},"famousNightMarkets":[{"zh-TW":"彰化八卦山肉圓老店","en":"Changhua Baguashan Ba-Wan","ja":"彰化八卦山肉圓","ko":"장화 바과산 바완","vi":"Ba-wan Baguashan Chương Hóa"},{"zh-TW":"通化夜市 (臨江街夜市)","en":"Tonghua Night Market","ja":"通化夜市","ko":"퉁화 야시장","vi":"Chợ đêm Tonghua"}],"historyStory":{"zh-TW":"清末戊戌大水災時，彰化北斗文人范萬居先生將地瓜粉揉漿包入熟肉竹筍蒸熟賑災，演化為全台最具代表性的「肉圓」。彰化派以低溫溫油泡炸、高溫搶酥最為聞名。","en":"Invented during late Qing disaster relief in Changhua using sweet potato starch to wrap seasoned pork and bamboo shoots. Now famous across Taiwan for its unique warm-oil poaching and flash-crisping.","ja":"清朝末期に水害の救済食として考案されたのが始まり。サツマイモ澱粉の弾力ある生地に豚肉や筍を包み、油で低温揚げする彰化スタイルが全国で愛されています。","ko":"청나라 말기 수해 구호 음식에서 유래하여 발전한 음식으로, 쫄깃한 고구마 전분 피에 고기와 죽순을 채워 온기름에 튀겨내는 장화의 대표 명물입니다.","vi":"Ra đời từ thời nhà Thanh, món bánh bột khoai lang bọc thịt heo măng tươi hấp rồi chiên ngập dầu ấm đã trở thành tinh hoa ẩm thực xứ Chương Hóa."},"taiwaneseHokkien":"Bah-uân (ㄅㄚˊ ㄨㄢˊ)","mandarinPinyin":"Zhānghuà Ròuyuán (ㄓㄤ ㄏㄨㄚˋ ㄖㄡˋ ㄩㄢˊ)","audioPronunciationText":"肉圓兩顆，要加辣、皮要炸酥一點"},"ingredients":[{"id":"sweet-potato-starch","name":{"zh-TW":"純地瓜粉與在來米粉 (粉皮漿)","en":"Sweet Potato Starch & Rice Flour Blend","ja":"サツマイモ澱粉と米粉ミックス","ko":"고구마 전분 및 멥쌀가루","vi":"Bột khoai lang và bột gạo tẻ"},"amount":250,"unitMetric":"g","unitUS":"2 cups","isKeyFlavor":true,"chineseName":"地瓜粉在來米漿","chinesePinyin":"Dìguāfěn zàiláimǐ jiāng"},{"id":"pork-chunks","name":{"zh-TW":"台灣溫體梅花豬肉塊 (醬油五香醃漬)","en":"Marinated Pork Shoulder Chunks","ja":"下味をつけた豚肩ロース角切り","ko":"양념한 돼지 목심 깍둑썰기","vi":"Thịt nạc vai heo ướp ngũ vị hương"},"amount":300,"unitMetric":"g","unitUS":"10 oz","isKeyFlavor":true,"chineseName":"五香豬肉餡","chinesePinyin":"Wǔxiāng zhūròu xiàn"},{"id":"bamboo-shoots","name":{"zh-TW":"熟麻竹筍丁與乾香菇丁","en":"Bamboo Shoot Cubes & Shiitake","ja":"筍の角切りと干し椎茸","ko":"죽순 다이스 및 표고버섯","vi":"Măng luộc thái hạt lựu và nấm hương"},"amount":120,"unitMetric":"g","unitUS":"4 oz","chineseName":"筍丁香菇","chinesePinyin":"Sǔndīng xiānggū"},{"id":"pink-sweet-sauce","name":{"zh-TW":"台式粉紅甜米醬與蒜泥醬油","en":"Taiwanese Pink Sweet Rice Sauce & Garlic Paste","ja":"特製ピンクの甘米ダレとニンニク醤油","ko":"핑크빛 달콤한 쌀 소스 및 마늘간장","vi":"Sốt hồng ngọt ngào và sốt tương tỏi"},"amount":100,"unitMetric":"ml","unitUS":"0.4 cup","isKeyFlavor":true,"chineseName":"粉紅甜米醬","chinesePinyin":"Fěnhóng tiánmǐjiàng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"煮在來米糊並與地瓜粉揉勻成晶瑩粉漿","en":"Cook Rice Slurry & Mix Sweet Potato Dough","ja":"米粉ペーストを炊き、サツマイモ澱粉と混ぜる","ko":"쌀풀을 쑤어 고구마 전분과 섞어 반죽 만들기","vi":"Nấu hồ bột gạo rồi trộn đều bột khoai lang tạo hỗn hợp dẻo dai"},"instruction":{"zh-TW":"在來米粉加水煮成濃稠米糊，放涼後與地瓜粉、太白粉徹底拌勻，調成濃稠柔滑的半透明生粉漿。","en":"Cook rice flour with water into paste. Cool and mix thoroughly with sweet potato starch into a thick smooth batter.","ja":"米粉と水を弱火で練り、冷ましてからサツマイモ粉を混ぜ合わせて滑らかな生地を作ります。","ko":"멥쌀가루로 풀을 쑨 뒤 식혀 고구마 전분을 섞어 찰진 반죽을 만듭니다.","vi":"Nấu bột gạo với nước thành hồ đặc, để nguội trộn cùng bột khoai lang cho dẻo quánh."},"durationSeconds":600,"image":"/images/tw/taiwan-ba-wan-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"小碟抹油填漿、包入筍丁肉餡封口","en":"Fill Saucers with Batter, Add Meat Filling & Seal","ja":"小皿に生地を敷き、筍と肉餡を詰めて包む","ko":"작은 종지에 반죽을 깔고 고기소를 넣어 감싸기","vi":"Quét dầu vào chén nhỏ, tráng bột rồi cho nhân thịt măng vào bọc kín"},"instruction":{"zh-TW":"淺碟塗薄油，抹上一大匙粉漿，放上大塊醃豬肉、筍丁與香菇，再覆蓋一層粉漿將餡料完全包覆抹圓。","en":"Coat small saucer with oil, spread a layer of batter, place meat & bamboo shoots, then top with another layer of batter to seal.","ja":"小皿に油を塗り、生地を敷いて肉餡と筍をのせ、上からさらに生地をかぶせて丸く包み込みます。","ko":"종지에 기름을 바르고 반죽을 깐 뒤 고기소를 얹고 다시 반죽을 덮어 둥글게 밀봉합니다.","vi":"Thoa dầu vào chén, múc bột lót đáy, cho nhân thịt măng vào rồi múc thêm lớp bột phủ kín mặt."},"durationSeconds":600,"image":"/images/tw/taiwan-ba-wan-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"大火蒸 15 分鐘至晶瑩透亮定型","en":"Steam on High Heat for 15 Mins until Translucent","ja":"強火で15分蒸して半透明に固める","ko":"센 불에서 15분간 쪄서 투명하게 굳히기","vi":"Hấp lửa lớn 15 phút cho vỏ bánh chuyển trong suốt"},"instruction":{"zh-TW":"放入蒸籠大火蒸 15 分鐘，肉圓外皮由白轉為半透明晶瑩Q彈狀，出爐稍微放涼脫模。","en":"Steam in steamer on high for 15 mins until skin turns glossy translucent and chewy. Cool slightly and unmold.","ja":"蒸し器で強火15分蒸し、生地が透明でプルプルになったら取り出して冷まします。","ko":"찜기에 넣고 센 불에서 15분간 쪄서 피가 투명해지면 꺼내어 한 김 식힙니다.","vi":"Đặt vào xửng hấp lửa lớn 15 phút đến khi vỏ bánh trong veo dẻo quánh thì lấy ra gỡ khỏi chén."},"durationSeconds":900,"image":"/images/tw/taiwan-ba-wan-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"溫油慢浸炸酥、剪開淋上粉紅甜醬！","en":"Warm Oil Poach, Snip Open & Drizzle Sweet Sauce","ja":"低温油でじっくり揚げ、ハサミで切り込みを入れてタレをかける！","ko":"온기름에 튀겨 가위로 자르고 특제 소스 뿌려 완성하기!","vi":"Chiên ngập dầu ấm cho giòn vỏ, cắt chữ thập và rưới sốt hồng!"},"instruction":{"zh-TW":"將蒸熟的肉圓放入 100°C 溫油鍋中慢浸泡炸 3 分鐘，最後拉高油溫炸出微酥外皮。撈起瀝油入碗，用剪刀剪出十字開口，淋上靈魂粉紅甜米醬、蒜泥與香菜！","en":"Poach steamed Ba-Wan in 100°C warm oil for 3 mins, then flash high heat for crispy crust. Snip top in a cross pattern, ladle pink sweet sauce, garlic & cilantro!","ja":"100℃のぬるめの油で3分じっくり揚げ、ハサミで十字に切り込みを入れて甘ダレとニンニク醤油をたっぷりかけて完成！","ko":"100°C 온기름에 3분간 부드럽게 튀긴 뒤 그릇에 담아 가위로 십자 모양을 내고 달콤한 핑크 소스와 마늘을 부어 먹습니다.","vi":"Thả bánh vào chảo dầu 100°C chiên nhỏ lửa 3 phút cho phồng giòn vỏ. Vớt ra bát dùng kéo cắt chữ thập rồi chan đẫm sốt hồng ngọt và tỏi băm ngò rí!"},"durationSeconds":240,"image":"/images/tw/taiwan-ba-wan-step4.jpg"}],"troubleshooting":[{"id":"skin-hard","problem":{"zh-TW":"肉圓皮吃起來硬硬的沒有彈性？","en":"Why is the Ba-Wan skin hard and not chewy?","ja":"肉圓の皮が固くてモチモチしない？","ko":"바완 피가 딱딱하고 쫄깃하지 않나요?","vi":"Vỏ bánh bị cứng không có độ dẻo dai?"},"cause":{"zh-TW":"地瓜粉比例過低或沒有用在來米糊燙熟熟化粉心。","en":"Not enough sweet potato starch or rice paste wasn't pre-cooked.","ja":"サツマイモ澱粉の比率が低いか、米粉の加熱不足です。","ko":"고구마 전분 비율이 낮거나 쌀풀이 덜 익었기 때문입니다.","vi":"Tỷ lệ bột khoai lang quá ít hoặc hồ bột gạo chưa chín kỹ."},"solution":{"zh-TW":"嚴格遵循純地瓜粉搭配燙在來米糊，粉漿呈透明濃稠狀，蒸熟後口感極致軟Q！","en":"Use authentic coarse sweet potato starch mixed into hot cooked rice paste!","ja":"熱い米粉ペーストにサツマイモ澱粉を練り込み、蒸し上げてください！","ko":"뜨거운 쌀풀에 고구마 전분을 섞어 쪄내면 극상의 쫄깃함이 완성됩니다!","vi":"Dùng đúng bột khoai lang nguyên chất nhào với hồ bột gạo nóng để vỏ bánh dẻo trong."}}],"proTips":[{"zh-TW":"老饕吃法是用扁竹籤將肉圓十字劃開，先吃吸飽粉紅醬汁的Q彈外皮，最後肉餡留在碗底加高湯喝完！","en":"Eat the chewy skin first with the sweet pink sauce, then pour hot broth into leftover filling to drink!","ja":"十字に切って皮をタレで味わった後、残った具に熱いスープを注いで飲むのが通の楽しみ方！","ko":"쫄깃한 껍질을 먼저 소스와 즐긴 뒤 남은 고기소에 뜨거운 육수를 부어 마시는 것이 전통입니다!","vi":"Thưởng thức lớp vỏ dẻo ngập sốt trước, sau đó chan nước dùng nóng vào phần nhân còn lại trong bát để húp trọn vẹn!"}]},{"country":"tw","id":"giant-chicken-cutlet","slug":"giant-chicken-cutlet","title":{"zh-TW":"士林夜市豪大大雞排","en":"Giant Taiwanese Fried Chicken Cutlet","ja":"士林夜市名物 巨大フライドチキン（大鶏排）","ko":"스린 야시장 얼굴보다 큰 지파이 (대왕 닭가슴살 튀김)","vi":"Gà rán khổng lồ chợ đêm Shilin (Ji Pai)"},"subtitle":{"zh-TW":"比臉還大・鮮嫩爆汁厚切・粗顆粒地瓜粉酥脆外衣","en":"Bigger Than Your Face, Juicy Thick Cut & Crunchy Tapioca Crust","ja":"顔より大きい特大サイズ・肉汁ジュワッ・粗挽き地瓜粉のザクザク衣","ko":"얼굴보다 큰 압도적 크기, 촉촉한 육즙과 타피오카 전분의 바삭한 튀김옷","vi":"Kích thước khổng lồ siêu to, thịt mềm mọng nước cùng lớp vỏ bột khoai lang giòn tan"},"tagline":{"zh-TW":"名揚全球的夜市神話！雙手握不住的酥脆狂潮與五香椒鹽香","en":"The worldwide night market phenomenon: unbeatable size, crunch, and aroma","ja":"台湾夜市といえばコレ！両手でも収まらない迫力満点の看板グルメ","ko":"세계적으로 유명한 대만 야시장의 상징! 한 손에 쥐기 힘들 만큼 거대한 바삭함","vi":"Cơn sốt ẩm thực đường phố toàn cầu với hương thơm nức mũi của tiêu ngũ vị"},"heroImage":"/images/tw/taiwan-chicken-cutlet-hero.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":680,"category":"fried","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originCity":{"zh-TW":"台北士林 / 台中一中街","en":"Taipei Shilin / Taichung Yizhong","ja":"台北士林 / 台中一中街","ko":"타이베이 스린 / 타이중 이중제","vi":"Shilin Đài Bắc / Yizhong Đài Trung"},"famousNightMarkets":[{"zh-TW":"士林夜市","en":"Shilin Night Market","ja":"士林夜市","ko":"스린 야시장","vi":"Chợ đêm Shilin"},{"zh-TW":"一中街夜市","en":"Yizhong Night Market","ja":"一中街夜市","ko":"이중제 야시장","vi":"Chợ đêm Yizhong"}],"historyStory":{"zh-TW":"1990年代起在台北士林夜市興起，將整塊新鮮帶骨大雞胸肉連同蝴蝶刀橫剖展開，呈現驚人的巨無霸面積。經五香、肉桂、蒜粉、米酒24小時醃製入味，裹上粗顆粒地瓜粉酥炸，成為台灣夜市最引以為傲的國民炸物。","en":"Originating in Shilin Night Market in the 1990s, butterflying a whole chicken breast into a massive cutlet marinated in five-spice and garlic, coated in coarse tapioca starch and fried golden.","ja":"1990年代に士林夜市で広まった、鶏むね肉を観音開きにして特大サイズに仕上げるフライドチキン。五香粉やニンニクで下味をつけ、地瓜粉でザクッと揚げます。","ko":"1990년대 스린 야시장에서 시작되어 닭가슴살을 넓게 펴서 마늘과 오향 가루에 재운 뒤 고구마 전분으로 바삭하게 튀겨낸 대만의 대표 간식입니다.","vi":"Bắt nguồn từ chợ đêm Shilin thập niên 1990, miếng ức gà được lạng mỏng to bản ướp đẫm ngũ vị tỏi rượu rồi tẩm bột chiên vàng giòn rụm."},"taiwaneseHokkien":"Ke-phai (ㄍㄟ ㄆㄞˋ)","mandarinPinyin":"Háo Dà Jīpái (ㄏㄠˊ ㄉㄚˋ ㄐㄧ ㄆㄞˊ)","audioPronunciationText":"老闆，大雞排一份要辣、不切！"},"ingredients":[{"id":"chicken-breast","name":{"zh-TW":"特大帶骨大雞胸肉 (蝴蝶刀剖開)","en":"Giant Chicken Breast (Butterflied)","ja":"特大鶏むね肉（観音開き）","ko":"대형 닭가슴살 (넓게 펴기)","vi":"Ức gà bản to khổng lồ lạng mỏng"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"chineseName":"大雞胸肉","chinesePinyin":"Jīxiōng ròu"},{"id":"coarse-sweet-potato-starch","name":{"zh-TW":"粗顆粒地瓜粉 (木薯澱粉)","en":"Coarse Sweet Potato / Tapioca Starch","ja":"粗挽きサツマイモ澱粉（地瓜粉）","ko":"굵은 고구마/타피오카 전분","vi":"Bột khoai lang hạt thô"},"amount":150,"unitMetric":"g","unitUS":"1.2 cups","isKeyFlavor":true,"chineseName":"粗地瓜粉","chinesePinyin":"Cū dìguāfěn"},{"id":"marinade-spice","name":{"zh-TW":"五香蒜香醃醬 (蒜泥+醬油+米酒+五香粉+肉桂粉+糖)","en":"Five-Spice Garlic Marinade Blend","ja":"特製五香ガーリック漬けダレ","ko":"오향 마늘 간장 양념","vi":"Nước sốt ướp tỏi ngũ vị hương"},"amount":60,"unitMetric":"ml","unitUS":"4 tbsp","isKeyFlavor":true,"chineseName":"五香醃料","chinesePinyin":"Wǔxiāng yānliào"},{"id":"pepper-salt","name":{"zh-TW":"台灣特製中藥胡椒鹽與辣椒粉","en":"Taiwanese Spiced Pepper Salt & Chili Powder","ja":"台湾特製スパイス胡椒塩と唐辛子粉","ko":"대만 특제 한방 후추소금 및 고춧가루","vi":"Muối tiêu thảo mộc và bột ớt"},"amount":15,"unitMetric":"g","unitUS":"1 tbsp","chineseName":"胡椒鹽辣椒粉","chinesePinyin":"Hújiāoyán"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"蝴蝶刀橫剖大雞胸肉並拍鬆斷筋","en":"Butterfly Chicken Breast & Tenderize","ja":"鶏むね肉を観音開きにし、肉叩きで広げる","ko":"닭가슴살을 포 떠서 넓게 펼치고 두드리기","vi":"Lạng mỏng ức gà hình cánh bướm và dần mềm"},"instruction":{"zh-TW":"將厚實大雞胸肉從側面用刀橫向切開不切斷，向兩側攤平展開成比臉大的巨型薄片。用肉槌均勻敲打拍鬆，破壞肉質纖維使肉質軟嫩多汁。","en":"Slice chicken breast horizontally from the thick side almost all the way through, open like a book. Gently pound with meat mallet until uniformly thin.","ja":"鶏肉の厚い部分から横に包丁を入れて観音開きにし、肉叩きで叩いて均一の厚さに広げます。","ko":"닭가슴살 측면을 포 떠서 넓게 펼친 후 고기망치로 골고루 두드려 얇고 부드럽게 만듭니다.","vi":"Dùng dao lạng ngang thân miếng ức gà mở rộng hình cánh bướm, dần nhẹ cho mỏng đều và mềm thịt."},"durationSeconds":300,"image":"/images/tw/taiwan-chicken-cutlet-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"特製五香蒜泥醬汁深層醃漬入味","en":"Marinate in Five-Spice Garlic Sauce","ja":"特製五香ダレに漬け込んで味を染み込ませる","ko":"오향 마늘 양념에 재워 깊은 풍미 입히기","vi":"Ướp đẫm sốt tỏi ngũ vị hương cho ngấm sâu"},"instruction":{"zh-TW":"將雞排浸入蒜泥、醬油膏、米酒、五香粉、白胡椒粉、肉桂粉與少許糖調製的醃料中，抓捏按摩 5 分鐘，冷藏醃漬至少 2 小時（隔夜風味更佳）。","en":"Massage chicken with garlic paste, soy sauce, rice wine, five-spice, white pepper, cinnamon and sugar. Chill in fridge for at least 2 hours or overnight.","ja":"ニンニク、醤油、酒、五香粉、コショウなどの調味料でよく揉み込み、冷蔵庫で2時間以上漬け込みます。","ko":"마늘, 간장, 맛술, 오향분, 후추를 넣고 5분간 주무른 뒤 냉장실에서 2시간 이상 숙성합니다.","vi":"Bóp đều thịt gà với tỏi, nước tương, rượu, ngũ vị hương, quế và tiêu. Để tủ lạnh ướp ít nhất 2 tiếng."},"durationSeconds":7200,"image":"/images/tw/taiwan-chicken-cutlet-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"壓裹粗顆粒地瓜粉並靜置反潮","en":"Dredge in Coarse Tapioca Starch & Rest to Hydrate","ja":"粗挽き地瓜粉をしっかりまぶし、粉を馴染ませる","ko":"굵은 고구마 전분을 꼼꼼히 묻히고 수분 흡수시키기","vi":"Tẩm bột khoai lang hạt thô và để nghỉ cho bột bám chặt"},"instruction":{"zh-TW":"將醃好的雞排平鋪在粗顆粒地瓜粉盤中，用手掌用力按壓使表面緊密沾滿粉粒。翻面重複動作，提起源起多餘乾粉，靜置 3~5 分鐘等待粉粒反潮受潮黏牢。","en":"Press marinated chicken firmly into coarse sweet potato starch to coat every crevice. Shake off excess and let rest 3-5 mins until starch moistens naturally to prevent flaking.","ja":"粗挽き地瓜粉をたっぷりと押し付けるようにまぶし、3〜5分置いて粉がしっとり馴染むのを待ちます。","ko":"고구마 전분을 손바닥으로 꾹꾹 눌러가며 빈틈없이 입힌 뒤 3-5분간 두어 튀김옷이 착 달라붙게 합니다.","vi":"Ấn mạnh miếng gà vào đĩa bột khoai lang thô cho bám kín, để nghỉ 3-5 phút cho bột ngấm ẩm không bị rơi khi chiên."},"durationSeconds":300,"image":"/images/tw/taiwan-chicken-cutlet-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"大火酥炸至金黃金脆、撒滿椒鹽！","en":"Deep Fry to Golden Crisp & Dust with Spiced Pepper Salt","ja":"高温の油でカリッと揚げ、特製スパイス塩を振る！","ko":"바삭하게 튀겨내고 특제 후추소금을 듬뿍 뿌려 완성!","vi":"Chiên ngập dầu vàng giòn rụm và rắc đẫm muối tiêu thảo mộc!"},"instruction":{"zh-TW":"油鍋加熱至 175°C，雙手展開雞排輕輕滑入油鍋。炸約 4~5 分鐘至兩面金黃浮起，起鍋前 30 秒拉高油溫至 190°C 逼油搶酥。瀝乾油後豪邁撒上特調胡椒鹽與辣椒粉，整片趁熱啃咬！","en":"Heat oil to 175°C (345°F). Slide giant cutlet into oil, fry 4-5 mins until buoyant and golden. Raise heat to 190°C for final 30s to shed oil. Drain and dust generously with pepper salt & chili!","ja":"175℃の油で4〜5分揚げ、最後に強火でカリッと油を切ります。熱いうちに特製スパイス塩と唐辛子粉をたっぷり振って豪快にかぶりつきます！","ko":"175°C 기름에 넣고 4-5분간 튀긴 뒤 마지막에 온도를 올려 바삭하게 건져냅니다. 후추소금과 고춧가루를 듬뿍 뿌려 완성합니다!","vi":"Thả miếng gà vào dầu 175°C chiên 4-5 phút, tăng nhiệt lên 190°C trong 30 giây cuối ép dầu. Vớt ra rắc đẫm muối tiêu ớt thưởng thức nguyên miếng!"},"durationSeconds":300,"image":"/images/tw/taiwan-chicken-cutlet-step4.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer 190°C (375°F): 14 mins (Spray Oil & Flip at 8 mins)","instructionOverride":{"zh-TW":"氣炸鍋預熱至 190°C。將裹好粗地瓜粉並反潮完成的大雞排平鋪於炸籃中，雙面均勻噴上一層食用油。以 190°C 氣炸 8 分鐘後拉出翻面補噴油再氣炸 6 分鐘，最後以 200°C 氣炸 2 分鐘逼油，出鍋撒滿特製中藥胡椒鹽與辣椒粉，金黃卡滋極致香脆！","en":"Preheat air fryer to 190°C (375°F). Place coated cutlet in basket, spray both sides generously with oil. Air fry for 8 mins, flip, spray again and fry 6 mins. Finish at 200°C for 2 mins to crisp up, dust with pepper salt!","ja":"ノンフライヤーを190℃に予熱。衣をまとわせたチキンの両面にオイルスプレーをし、190℃で8分加熱後に裏返してさらに6分、仕上げに200℃で2分加熱。熱々のうちに特製スパイス塩を振って完成！","ko":"에어프라이어를 190°C로 예열하고 닭가슴살 양면에 오일을 골고루 분사합니다. 190°C에서 8분 조리 후 뒤집어 6분 더 굽고, 200°C에서 2분간 바삭하게 마무리한 뒤 특제 후추소금을 듬뿍 뿌립니다.","vi":"Làm nóng nồi chiên không dầu ở 190°C, xịt dầu đều 2 mặt miếng gà. Nướng 8 phút rồi lật mặt nướng thêm 6 phút, chỉnh 200°C nướng 2 phút cuối cho giòn rụm rồi rắc đẫm muối tiêu thảo mộc!"}}]}],"troubleshooting":[{"id":"crust-fall-off","problem":{"zh-TW":"雞排下鍋炸的時候外皮麵衣全部脫落？","en":"Why did the crispy batter fall off in the oil?","ja":"揚げているときに衣が剥がれてしまう？","ko":"튀길 때 튀김옷이 다 벗겨지나요?","vi":"Lớp bột chiên bị bong tróc rời ra khi thả vào dầu?"},"cause":{"zh-TW":"沾粉後沒有靜置「反潮」，乾粉遇到高溫油流失。","en":"Skipped the resting step; starch didn't hydrate with the chicken's surface moisture.","ja":"粉をつけた後、馴染ませる時間（反潮）を取らなかったためです。","ko":"가루를 묻힌 후 전분이 수분을 머금을 때까지 기다리지 않았기 때문입니다.","vi":"Chưa để bột nghỉ hồi ẩm trước khi chiên nên bột khô bị dầu cuốn trôi."},"solution":{"zh-TW":"沾滿粗地瓜粉後，務必在常溫靜置 3~5 分鐘，看到粉粒變深色受潮後再下鍋！","en":"Always let dusted chicken sit for 3-5 mins until starch darkens and adheres firmly!","ja":"粉をまぶした後、必ず3〜5分置いて粉がしっとりしてから揚げてください！","ko":"반드시 3-5분간 두어 튀김옷이 촉촉해진 것을 확인한 후 기름에 넣으세요!","vi":"Bắt buộc để nghỉ 3-5 phút cho bột chuyển màu sẫm ẩm dính chặt vào da gà mới đem chiên!"}}],"proTips":[{"zh-TW":"台灣老饕口訣「雞排不切」！整片直接啃咬才能牢牢鎖住豐沛肉汁，切塊會導致鮮甜精華流失！","en":"The golden rule is 'Never Cut the Chicken Cutlet'! Biting whole locks in steaming hot juices!","ja":"台湾ツウの鉄則は『切らずにそのまま食べる』！かぶりつくことでジューシーな肉汁を閉じ込めます！","ko":"대만 로컬들의 철칙은 '자르지 않고 통째로 먹기'! 육즙이 빠져나가지 않아 가장 맛있습니다!","vi":"Bí quyết ăn ngon là để nguyên miếng không cắt để giữ trọn vẹn dòng nước thịt ngọt lịm bên trong!"}]},{"country":"tw","id":"tian-bu-la","slug":"tian-bu-la","title":{"zh-TW":"經典台式關東煮甜不辣","en":"Taiwanese Tian Bu La (Fish Paste Tempura Pot)","ja":"台湾風おでん・テンプラ（甜不辣）","ko":"대만식 어묵 튀김 조림 텐부라 (오뎅 요리)","vi":"Chả cá chiên sốt ngọt chợ đêm Đài Loan (Tian Bu La)"},"subtitle":{"zh-TW":"Q彈魚漿條・清甜白蘿蔔・靈魂甜辣味噌醬・最後免費加湯","en":"Bouncy Fish Cakes, Simmered Daikon, Sweet Miso Sauce & Broth Refill","ja":"モチモチすり身・出汁の染みた大根・秘伝の甘辛味噌ダレ・〆の無料スープ","ko":"탱글탱글한 어묵, 달콤하게 익은 무, 특제 달콤 매콤 소스와 육수 리필의 맛","vi":"Chả cá dai giòn, củ cải hầm ngọt nước, sốt tương ngọt cay và húp trọn nước dùng"},"tagline":{"zh-TW":"吃完食材一定要把碗端去加滿柴魚高湯！台灣人最溫暖的夜市儀式","en":"Eat the fish cakes, then bring your bowl for a rich piping-hot broth refill!","ja":"具を食べ終わったら残ったタレに熱々出汁を注いで飲むのが台湾流！","ko":"건더기를 다 먹고 남은 소스에 뜨거운 육수를 부어 마시는 따뜻한 한 그릇","vi":"Nét văn hóa độc đáo: ăn hết chả cá rồi chan nước dùng ngọt thanh vào bát húp sạch!"},"heroImage":"/images/tw/taiwan-tian-bu-la-hero.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":20,"defaultServings":3,"caloriesPerServing":340,"category":"soups","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"基隆廟口 / 台北萬華","en":"Keelung Miaokou / Taipei Wanhua","ja":"基隆廟口 / 台北万華","ko":"지룽 먀오커우 / 타이베이 완화","vi":"Keelung Miaokou / Vạn Hoa Đài Bắc"},"famousNightMarkets":[{"zh-TW":"基隆廟口夜市","en":"Keelung Miaokou Night Market","ja":"基隆廟口夜市","ko":"지룽 먀오커우 야시장","vi":"Chợ đêm Keelung Miaokou"},{"zh-TW":"通化夜市","en":"Tonghua Night Market","ja":"通化夜市","ko":"퉁화 야시장","vi":"Chợ đêm Tonghua"}],"historyStory":{"zh-TW":"源自日治時期日式黑輪（Oden）與天婦羅（Tempura），融入台灣在地旗魚漿、油豆腐、米血糕與貢丸。經過柴魚白蘿蔔大骨湯久煮入味，淋上獨門甜辣味噌紅醬，最精髓的是吃完後留碗底醬汁『免費加高湯』一飲而盡！","en":"Evolved from Japanese oden and tempura into a distinct Taiwanese comfort food with sailfish paste, rice blood cake, and tofu simmering in bonito-daikon broth.","ja":"日本の『おでん』や『天ぷら』が台湾で独自進化した料理。甘辛ダレで具材を食べた後、残ったタレに熱いスープを注いで飲み干すのが定番。","ko":"일제강점기 오뎅에서 유래하여 대만식 어묵, 유부, 쌀피떡 등을 가쓰오부시 무 육수에 끓여 특제 소스에 찍어 먹는 대표 분식입니다.","vi":"Biến tấu từ món oden Nhật Bản, kết hợp chả cá, huyết nếp, đậu hũ hầm trong nước dùng củ cải cá ngừ thanh ngọt và sốt tương ớt đặc trưng."},"taiwaneseHokkien":"Thian-pú-lah (ㄊㄧㄢ ㄅㄨ ㄌㄚ)","mandarinPinyin":"Tiánbùlà (ㄊㄧㄢˊ ㄅㄨˋ ㄌㄚˋ)","audioPronunciationText":"老闆，甜不辣一碗，要小辣，等一下要加湯"},"ingredients":[{"id":"fish-paste-cakes","name":{"zh-TW":"台式炸旗魚漿甜不辣條與圓片","en":"Taiwanese Fried Fish Paste Cakes & Bars","ja":"台湾産 揚げ魚肉すり身棒＆さつま揚げ","ko":"대만식 튀긴 어묵 바 및 둥근 어묵","vi":"Chả cá chiên dạng thanh và lát tròn"},"amount":250,"unitMetric":"g","unitUS":"9 oz","isKeyFlavor":true,"chineseName":"甜不辣魚漿條","chinesePinyin":"Tiánbùlà tiáo"},{"id":"white-daikon","name":{"zh-TW":"台灣白蘿蔔 (去皮厚切滾刀塊)","en":"Taiwanese White Daikon Radish (Chunky Cut)","ja":"大根（乱切り）","ko":"무 (큼직하게 썰기)","vi":"Củ cải trắng gọt vỏ cắt miếng to"},"amount":300,"unitMetric":"g","unitUS":"10 oz","isKeyFlavor":true,"chineseName":"白蘿蔔塊","chinesePinyin":"Báilúobo"},{"id":"tofu-rice-cake","name":{"zh-TW":"油豆腐、豬血糕、貢丸","en":"Fried Tofu Puffs, Pig Blood Rice Cake, Meatballs","ja":"厚揚げ、米血糕、豚つみれ","ko":"유부, 돼지피 찹쌀떡, 고기완자","vi":"Đậu hũ chiên, huyết nếp, bò viên"},"amount":200,"unitMetric":"g","unitUS":"7 oz","chineseName":"油豆腐米血貢丸","chinesePinyin":"Yóudòufu mǐxiě"},{"id":"tianbula-sauce","name":{"zh-TW":"靈魂甜不辣醬 (甜辣醬+味噌+糖+番茄醬+高湯)","en":"Signature Sweet Miso Chili Dipping Sauce","ja":"特製甘辛味噌ダレ","ko":"특제 스위트 미소 칠리 소스","vi":"Sốt tương ngọt cay vị miso gia truyền"},"amount":100,"unitMetric":"ml","unitUS":"0.4 cup","isKeyFlavor":true,"chineseName":"甜辣味噌醬","chinesePinyin":"Tiánlà jiàng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火熬煮柴魚大骨白蘿蔔清甜高湯","en":"Simmer Bonito & Daikon Sweet Broth","ja":"大根と鰹節を弱火でじっくり煮込み出汁をとる","ko":"무와 가쓰오부시를 약불에 끓여 시원한 육수 내기","vi":"Ninh củ cải trắng với cá ngừ bào và xương lấy nước dùng thanh ngọt"},"instruction":{"zh-TW":"湯鍋中加入 1500ml 大骨高湯或清水，放入厚切白蘿蔔塊與一大把柴魚片、昆布。中小火慢煮 15~20 分鐘直至白蘿蔔晶瑩透亮、軟爛入味。","en":"Bring 1500ml stock or water to boil with thick-cut daikon, bonito flakes and kombu. Simmer 15-20 mins until daikon is translucent, fork-tender and sweet.","ja":"鍋に水1.5L、大根、鰹節、昆布を入れ、弱火で15〜20分じっくり煮て大根を柔らかくします。","ko":"냄비에 육수 1.5L와 큼직하게 썬 무, 가쓰오부시, 다시마를 넣고 15-20분간 무가 투명해질 때까지 끓입니다.","vi":"Cho 1.5L nước vào nồi cùng củ cải, cá ngừ bào và tảo bẹ. Ninh nhỏ lửa 15-20 phút cho củ cải trong mềm ngọt nước."},"durationSeconds":1200,"image":"/images/tw/taiwan-tian-bu-la-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"下甜不辣條、油豆腐、米血糕慢浸入味","en":"Add Fish Cakes, Tofu Puffs & Blood Rice Cakes","ja":"テンプラ、厚揚げ、米血糕を加えて旨味を吸わせる","ko":"어묵, 유부, 찹쌀떡을 넣고 은근하게 조리기","vi":"Thả chả cá, đậu hũ chiên, huyết nếp vào hầm cho ngấm đẫm vị ngọt"},"instruction":{"zh-TW":"將甜不辣條、片、油豆腐、米血糕、貢丸放入滾燙清甜高湯中，轉微小火浸泡煨煮約 8~10 分鐘，讓食材吸飽柴魚蘿蔔高湯精華，膨脹軟Q。","en":"Add fish cakes, fried tofu puffs, blood rice cake and meatballs into broth. Simmer gently on low for 8-10 mins until swollen, bouncy and soaked with broth flavor.","ja":"すり身天ぷら、厚揚げ、米血糕などをスープに入れ、弱火で8〜10分煮て出汁をしっかり染み込ませます。","ko":"어묵과 유부, 찹쌀떡을 넣고 약불에서 8-10분간 천천히 익혀 육수가 듬뿍 배어들게 합니다.","vi":"Cho chả cá, đậu hũ, huyết nếp vào nồi đun nhỏ lửa 8-10 phút cho nở mềm ngập tràn vị ngọt thanh."},"durationSeconds":600,"image":"/images/tw/taiwan-tian-bu-la-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"撈出食材入碗、淋上靈魂粉紅甜辣味噌醬","en":"Plate Ingredients & Drench in Signature Sweet Sauce","ja":"具材を器に盛り、秘伝の甘辛味噌ダレをかける","ko":"그릇에 담고 특제 달콤 매콤 소스를 듬뿍 붓기","vi":"Gắp thức ăn ra bát và rưới đẫm sốt tương ngọt cay"},"instruction":{"zh-TW":"用漏勺將煮至軟Q的白蘿蔔、甜不辣、油豆腐撈出盛入深碗中。澆上 2 大勺特調溫熱甜辣味噌醬，撒上香菜與少許辣椒醬，趁熱大口品嚐！","en":"Use slotted spoon to transfer tender daikon, fish cakes and tofu puffs into a bowl. Generously ladle warm sweet miso chili sauce over top with fresh cilantro!","ja":"柔らかく煮えた具材を器に盛り付け、温かい特製甘辛味噌ダレをたっぷり回しかけます！","ko":"익은 재료들을 건져 그릇에 담고 따뜻한 달콤 매콤 소스를 듬뿍 부어 고수와 함께 즐깁니다.","vi":"Dùng muôi thủng vớt củ cải, chả cá ra bát sâu lòng, chan ngập sốt tương ngọt cay ấm nóng rắc ngò rí."},"durationSeconds":120,"image":"/images/tw/taiwan-tian-bu-la-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"吃完食材碗底留醬、衝入滾燙柴魚高湯一飲而盡！","en":"Pour Piping-Hot Broth into Leftover Sauce Bowl","ja":"食べ終わった碗に残ったタレに熱々出汁を注いで飲む！","ko":"남은 소스 그릇에 뜨거운 육수를 부어 마시기!","vi":"Rót nước dùng nóng hổi vào bát còn đọng sốt và húp trọn vẹn!"},"instruction":{"zh-TW":"吃完所有的甜不辣與配料後，將留有紅褐色濃郁醬汁的碗拿到鍋邊，舀入滿滿一勺滾燙的柴魚白蘿蔔高湯，拌勻後化為一碗極致鮮甜的精華熱湯，暖心暖胃！","en":"After finishing the fish cakes, take the bowl with remaining savory sauce and ladle boiling bonito daikon broth straight in. Stir well and drink the heavenly sweet nectar!","ja":"具を食べ終えたら、残ったタレに鍋の熱々出汁を注ぎます。タレと出汁が溶け合った最高のスープを最後の一滴までお楽しみください！","ko":"건더기를 다 먹고 남은 소스에 끓는 가쓰오부시 무 육수를 가득 부어 섞어 마십니다. 이것이 대만 현지의 진정한 맛!","vi":"Sau khi ăn hết chả cá, múc muôi nước dùng củ cải sôi sùng sục vào bát sốt còn lại, khuấy đều húp sạch sảng khoái ấm bụng!"},"durationSeconds":60,"image":"/images/tw/taiwan-tian-bu-la-step4.jpg"}],"troubleshooting":[{"id":"fish-cake-soggy","problem":{"zh-TW":"甜不辣煮太久軟爛爛沒有彈性？","en":"Why are my fish cakes overly mushy?","ja":"テンプラが煮崩れて食感が悪くなってしまった？","ko":"어묵이 너무 퍼져서 흐물거리나요?","vi":"Chả cá bị nhũn nát mất độ dai giòn?"},"cause":{"zh-TW":"大火滾煮過久，魚漿彈性流失。","en":"Boiled on rolling high heat for too long.","ja":"強火でグツグツ長く煮すぎたことが原因です。","ko":"센 불에서 너무 오래 끓였기 때문입니다.","vi":"Đun sôi lửa quá to trong thời gian dài."},"solution":{"zh-TW":"蘿蔔先煮透，甜不辣只需中小火微滾浸泡 8 分鐘即可保持絕佳Q度！","en":"Cook radish first, then simmer fish cakes on low for just 8 mins!","ja":"大根を先に煮て、すり身は弱火で8分ほど温める程度にしてください！","ko":"무를 먼저 푹 익힌 뒤 어묵은 약불에서 8분 정도만 데치듯 익히세요!","vi":"Ninh nhừ củ cải trước rồi mới cho chả cá vào đun nhỏ lửa 8 phút là chuẩn nhất!"}}],"proTips":[{"zh-TW":"甜不辣靈魂全在醬汁！用紅味噌、台灣甜辣醬、番茄醬與少許砂糖用高湯化開小火熬煮，比例濃郁醇厚是老店不外傳的配方！","en":"The secret sauce: whisk red miso, sweet chili sauce, ketchup and sugar in broth on low heat!","ja":"赤味噌、甘辛チリソース、ケチャップ、砂糖を出汁で煮詰めるのが絶品タレの秘訣です！","ko":"붉은 미소된장, 스위트 칠리, 케첩, 설탕을 육수에 풀어 졸여내면 노포의 소스 완성!","vi":"Nấu sốt bằng tương miso đỏ, tương ớt ngọt, sốt cà chua và đường hòa cùng nước dùng thơm ngậy!"}]},{"country":"tw","id":"candied-fruit-tanghulu","slug":"candied-fruit-tanghulu","title":{"zh-TW":"夜市古早味番茄蜜餞糖葫蘆","en":"Candied Tomato & Preserved Plum Tanghulu","ja":"台湾夜市名物 トマトとドライプラムのフルーツ飴（糖葫芦）","ko":"대만 야시장 토마토 & 매실 탕후루 (탕후루)","vi":"Kẹo hồ lô cà chua kẹp xí muội chợ đêm Đài Loan"},"subtitle":{"zh-TW":"薄脆晶瑩糖衣・多汁聖女小番茄・夾入鹹甜黑化應子蜜餞","en":"Glass-Crisp Candy Shell, Juicy Cherry Tomatoes & Salted Plum Preserves","ja":"パリッパリの薄氷糖衣・ジューシーなプチトマト・甘酸っぱいドライプラム（化応子）","ko":"유리처럼 얇고 바삭한 설탕 코팅, 과즙 가득 방울토마토, 짭짤달콤한 건매실","vi":"Lớp đường giòn tan mỏng tang, cà chua bi mọng nước kẹp xí muội mặn ngọt độc đáo"},"tagline":{"zh-TW":"全台夜市人手一支的童年甜蜜回憶！酸甜多汁又脆口的夢幻紅寶石","en":"The nostalgic jewel of Taiwanese night markets: shatteringly crisp and tangy-sweet","ja":"台湾夜市の定番スイーツ！カリッとした飴と甘酸っぱいトマト蜜餞の絶妙なハーモニー","ko":"대만 야시장의 필수 길거리 간식! 아삭한 설탕 껍질과 새콤달콤한 과즙의 폭발","vi":"Món kẹo que tuổi thơ rực rỡ chợ đêm với lớp đường giòn rụm bọc quả ngọt thanh mát"},"heroImage":"/images/tw/taiwan-tanghulu-hero.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":180,"category":"desserts","dietaryTags":["classic","vegetarian","vegan","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北饒河 / 台中逢甲","en":"Taipei Raohe / Taichung Fengjia","ja":"台北饒河 / 台中逢甲","ko":"타이베이 라오허 / 타이중 펑자","vi":"Raohe Đài Bắc / Fengjia Đài Trung"},"famousNightMarkets":[{"zh-TW":"饒河街觀光夜市","en":"Raohe Night Market","ja":"饒河街夜市","ko":"라오허제 야시장","vi":"Chợ đêm Raohe"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"}],"historyStory":{"zh-TW":"傳統糖葫蘆傳入台灣後，夜市小販創造性地改用多汁的台灣在地聖女小番茄，並在番茄中央橫切一刀，夾入古早味鹹甜黑『化應子』蜜餞，酸、甜、鹹、脆四重層次絕妙平衡，成為台灣獨樹一幟的經典甜品。","en":"Taiwanese vendors innovated the traditional candied fruit by stuffing sweet cherry tomatoes with savory salted black plum preserves (Hua Ying Zi), creating the perfect balance of crisp, sweet, tangy and salty.","ja":"伝統のフルーツ飴を台湾風にアレンジ。甘酸っぱいプチトマトにドライプラム（化応子）を挟み、薄い飴でコーティングした台湾オリジナル。","ko":"전통 탕후루에 대만의 달콤한 방울토마토와 짭조름한 건매실을 샌드하여 얇은 설탕 코팅을 입힌 대만만의 독창적인 디저트입니다.","vi":"Biến tấu độc đáo của Đài Loan khi rạch đôi quả cà chua bi nhét miếng xí muội chua mặn rồi áo lớp đường giòn tan bóng bẩy."},"taiwaneseHokkien":"Thn̂g-hóo-lôo (ㄊㄥˊ ㄏㄛ ㄌㄛ)","mandarinPinyin":"Tánghúlu (ㄊㄤˊ ㄏㄨˊ ㄌㄨ˙)","audioPronunciationText":"老闆，番茄蜜餞糖葫蘆來兩支，要脆皮冰過的"},"ingredients":[{"id":"cherry-tomatoes","name":{"zh-TW":"新鮮聖女小番茄 (洗淨徹底擦乾)","en":"Fresh Cherry Tomatoes (Washed & Thoroughly Dried)","ja":"新鮮なプチトマト（水気を完全に拭き取る）","ko":"신선한 방울토마토 (물기 완전 제거)","vi":"Cà chua bi tươi (Rửa sạch thấm khô)"},"amount":300,"unitMetric":"g","unitUS":"10 oz","isKeyFlavor":true,"chineseName":"聖女小番茄","chinesePinyin":"Shèngnǚ fānqié"},{"id":"salted-plum-preserves","name":{"zh-TW":"台灣古早味化應子蜜餞 (切厚片)","en":"Taiwanese Dried Salted Black Plum (Hua Ying Zi)","ja":"台湾ドライプラム（化応子）","ko":"대만 전통 건매실 (화잉즈)","vi":"Xí muội đen mặn ngọt (Hóa ứng tử)"},"amount":80,"unitMetric":"g","unitUS":"3 oz","isKeyFlavor":true,"chineseName":"化應子蜜餞","chinesePinyin":"Huàyìngzǐ"},{"id":"sugar","name":{"zh-TW":"白砂糖或二砂","en":"Granulated White Sugar","ja":"グラニュー糖","ko":"백설탕","vi":"Đường cát trắng"},"amount":200,"unitMetric":"g","unitUS":"1 cup","chineseName":"白砂糖","chinesePinyin":"Báishātáng"},{"id":"water-syrup","name":{"zh-TW":"水與麥芽糖 (增加光澤與防返砂)","en":"Water & Maltose Syrup","ja":"水と水飴（ツヤ出し用）","ko":"물 및 물엿","vi":"Nước và mạch nha"},"amount":100,"unitMetric":"ml","unitUS":"0.4 cup","chineseName":"清水麥芽糖","chinesePinyin":"Màiyátáng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"番茄橫切切口並夾入化應子蜜餞","en":"Slit Tomatoes & Stuff with Salted Plum Preserves","ja":"トマトに切り目を入れドライプラムを挟む","ko":"토마토에 칼집을 내어 건매실 끼우기","vi":"Rạch ngang thân cà chua bi và nhét miếng xí muội vào giữa"},"instruction":{"zh-TW":"小番茄洗淨摘蒂，用廚房紙巾徹底擦乾表面水分（水分會使糖衣化水）。在番茄腰部切一刀不切斷，塞入一片厚實的化應子蜜餞，用竹籤串起 4~5 顆。","en":"Wash and completely dry cherry tomatoes. Slit waist without cutting through, insert a slice of salted plum preserve. Skewer 4-5 tomatoes per bamboo stick.","ja":"トマトの水気を完全に拭き取り、真ん中に切り込みを入れてドライプラムを挟み、竹串に4〜5個ずつ刺します。","ko":"물기를 완벽히 닦은 방울토마토에 칼집을 내고 건매실을 끼운 뒤 꼬치에 4-5개씩 꽂습니다.","vi":"Lau thật khô từng quả cà chua, rạch một đường ngang nhét miếng xí muội vào rồi xiên 4-5 quả vào que tre."},"durationSeconds":600,"image":"/images/tw/taiwan-tanghulu-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"慢火熬煮黃金晶瑩糖漿至 150°C","en":"Simmer Sugar Syrup to 150°C (Hard Crack Stage)","ja":"砂糖と水を弱火で煮詰め150℃のべっ甲飴を作る","ko":"설탕물을 약불에서 150°C까지 끓여 시럽 만들기","vi":"Đun đường và mạch nha trên lửa nhỏ đạt nhiệt độ 150°C"},"instruction":{"zh-TW":"厚底小鍋加入砂糖、水與麥芽糖（比例 2:1）。中小火加熱，切記熬煮過程中絕對不要攪拌（攪拌會反砂翻白）。煮約 8~10 分鐘，糖漿冒出密集細小泡沫且呈微淡琥珀色、溫度達 150°C。","en":"Combine sugar, water and maltose in saucepan. Simmer over medium-low heat WITHOUT stirring (stirring causes crystallization). Cook 8-10 mins until dense small bubbles form and reaches 150°C (300°F).","ja":"鍋に砂糖、水、水飴を入れ、決してかき混ぜずに弱火で8〜10分煮詰めます。薄い琥珀色になり150℃に達したら火を止めます。","ko":"냄비에 설탕과 물, 물엿을 넣고 절대 젓지 않은 채 약불에서 8-10분간 끓입니다. 옅은 호박색을 띠고 150°C가 되면 완성입니다.","vi":"Cho đường, nước, mạch nha vào nồi đun nhỏ lửa, tuyệt đối không khuấy tránh lại đường. Đun 8-10 phút đến khi ngả vàng nhạt 150°C."},"durationSeconds":600,"image":"/images/tw/taiwan-tanghulu-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"冷水筷子測糖法確認硬脆度","en":"Cold Water Chopstick Test for Crispness","ja":"冷水テストで飴の固さを確認する","ko":"찬물 테스트로 바삭한 굳기 확인하기","vi":"Thử đường bằng nước lạnh kiểm tra độ giòn rụm"},"instruction":{"zh-TW":"用竹筷沾取少許熱糖漿，迅速浸入冰水中 3 秒。取出用牙齒咬一口，如果發出清脆的『咔嚓』聲且不黏牙，即代表糖漿熬製完美！","en":"Dip chopstick into hot syrup then instantly submerge into ice water for 3 secs. Bite it: if it shatters with a crisp crunch and doesn't stick to teeth, it's ready!","ja":"箸の先に飴をつけ氷水に3秒浸します。噛んでみて『カリッ』と音がして歯にくっつかなければ完璧です！","ko":"젓가락 끝에 시럽을 묻혀 얼음물에 3초간 담근 뒤 깨물었을 때 '딱' 소리가 나며 바삭하면 준비 완료!","vi":"Chấm đầu đũa vào đường rồi nhúng ngay vào bát nước đá 3 giây, cắn thử thấy giòn tan không dính răng là đạt chuẩn!"},"durationSeconds":60,"image":"/images/tw/taiwan-tanghulu-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"極速旋轉裹上一層超薄糖衣冷卻！","en":"Quick Spin to Coat Thin Glass Shell & Cool","ja":"素早く回して極薄の飴をまとわせ、冷やす！","ko":"빠르게 회전시켜 얇은 설탕 코팅을 입히고 식히기!","vi":"Lăn nhanh quả cà chua qua lớp đường mỏng và làm nguội giòn tan!"},"instruction":{"zh-TW":"將番茄串傾斜貼著糖漿表面迅速旋轉一圈（薄薄一層即可，過厚會硬咬不動）。立即平放在塗抹薄油的烘焙紙或鐵板上，常溫冷卻 2 分鐘即可凝固成玻璃般清脆的糖葫蘆！","en":"Tilt skewered tomatoes and spin swiftly across surface for an ultra-thin coat. Transfer immediately to oiled parchment paper. Cool for 2 mins to form a glass-like crunch!","ja":"串を素早く回して薄く飴を絡め、薄く油を塗ったクッキングシートに置きます。2分冷ませばパリパリの糖葫芦が完成！","ko":"꼬치를 시럽 표면에 대고 재빠르게 한 바퀴 굴려 얇게 코팅한 뒤 기름 바른 유산지에 올려 2분간 식힙니다.","vi":"Nghiêng xiên que lăn nhanh 1 vòng qua mặt đường tạo lớp vỏ siêu mỏng, đặt lên giấy nướng thoa dầu để nguội 2 phút là thưởng thức!"},"durationSeconds":120,"image":"/images/tw/taiwan-tanghulu-step4.jpg"}],"troubleshooting":[{"id":"sugar-sticky","problem":{"zh-TW":"糖葫蘆吃起來黏牙、糖衣很快融化化水？","en":"Why is the candy shell sticky and melting?","ja":"飴が歯にくっついたり、溶けてベチャベチャになる？","ko":"탕후루가 치아에 달라붙고 쉽게 녹아내리나요?","vi":"Kẹo hồ lô bị dính răng hoặc nhanh chảy nước?"},"cause":{"zh-TW":"糖漿溫度不足 150°C，或番茄表面殘留生水。","en":"Syrup did not reach 150°C or tomatoes had surface moisture.","ja":"飴の加熱温度が低かったか、トマトの水気が残っていました。","ko":"시럽 온도가 150°C 미만이었거나 토마토에 물기가 남아있었기 때문입니다.","vi":"Đường chưa đạt đủ nhiệt 150°C hoặc cà chua còn ướt nước."},"solution":{"zh-TW":"番茄務必用紙巾擦到全乾；糖漿熬到淡琥珀色、冷水咬下清脆咔嚓聲再裹！","en":"Completely dry fruit; cook syrup to light amber and pass the ice water snap test!","ja":"水気を完全に拭き、氷水テストでカリッと割れるまでしっかり煮詰めてください！","ko":"물기를 완전히 없애고 시럽이 맑은 호박색이 될 때까지 끓이세요!","vi":"Thấm thật khô quả cà chua và thử nước đá thấy giòn đanh mới bắt đầu nhúng!"}}],"proTips":[{"zh-TW":"糖衣越薄越高級！裹糖時只要在表面漂浮旋轉半圈，甩掉多餘糖液，吃起來才會有薄如蟬翼的清脆爆汁快感！","en":"Thinner is better! Spin lightly across surface and shake off excess for that paper-thin glass crunch!","ja":"飴は薄いほど美味！サッと表面を一回転させて余分な飴を落とすのがプロの技です！","ko":"설탕 코팅은 얇을수록 예술! 살짝만 굴려 여분의 시럽을 털어내야 유리처럼 바삭합니다!","vi":"Lớp đường càng mỏng càng đỉnh! Chỉ cần lướt nhẹ một vòng lắc nhẹ cho rơi bớt đường thừa để cắn giòn tan bùng nổ vị giác!"}]},{"country":"tw","id":"frog-eggs-drink","slug":"frog-eggs-drink","title":{"zh-TW":"士林王記檸檬愛玉青蛙下蛋","en":"Shilin Frog Eggs Drink (Aiyu Jelly & Tapioca)","ja":"士林名物 レモン愛玉タピオカ（青蛙下蛋）","ko":"스린 야시장 레몬 아이위 흑당 버블티 (개구리알 음료)","vi":"Thạch Ái Ngọc trân châu chanh tươi chợ đêm (Thanh Oa Hạ Đản)"},"subtitle":{"zh-TW":"慢火黑糖大粉圓・野生手洗愛玉凍・鮮榨九如檸檬碎冰","en":"Slow-Simmered Black Sugar Pearls, Hand-Washed Aiyu Jelly & Fresh Lemon Ice","ja":"黒糖大粒タピオカ・天然手揉み愛玉ゼリー・搾りたてレモンのクラッシュアイス","ko":"흑당에 졸인 쫀득한 대왕 타피오카펄, 수제 아이위 젤리, 생레몬 슬러시","vi":"Trân châu đen dẻo quánh, thạch ái ngọc thiên nhiên cùng đá bào chanh tươi mát lạnh"},"tagline":{"zh-TW":"士林夜市最解膩的排隊聖品！黑亮如蛙卵的晶瑩珍珠與天然愛玉","en":"The ultimate refreshing palate cleanser of Shilin Night Market: tangy, bouncy and icy cold","ja":"士林夜市の看板ドリンク！タピオカの形がカエルの卵に似ていることから名付けられた爽快スイーツ","ko":"스린 야시장의 전설적인 갈증 해소 음료! 쫀득한 펄과 새콤달콤 레몬의 조화","vi":"Thức uống giải nhiệt huyền thoại chợ đêm Shilin xua tan mọi cảm giác ngấy mỡ"},"heroImage":"/images/tw/taiwan-frog-eggs-hero.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":25,"defaultServings":2,"caloriesPerServing":220,"category":"desserts","dietaryTags":["classic","vegetarian","vegan","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北士林夜市","en":"Taipei Shilin Night Market","ja":"台北士林夜市","ko":"타이베이 스린 야시장","vi":"Chợ đêm Shilin Đài Bắc"},"famousNightMarkets":[{"zh-TW":"士林夜市（王記青蛙下蛋）","en":"Shilin Night Market (Wang's)","ja":"士林夜市（王記青蛙下蛋）","ko":"스린 야시장 (왕지 칭와샤단)","vi":"Chợ đêm Shilin (Vương Ký)"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"}],"historyStory":{"zh-TW":"創始於台北士林夜市陽明戲院前，因黑糖大粉圓煮好後圓潤黑亮、中心微透白心宛如『青蛙卵』而得名。搭配台灣特有阿里山野生愛玉子手搓愛玉凍與屏東九如鮮榨檸檬汁，酸爽Q彈。","en":"Originated in front of Shilin Yangming Cinema, playfully named 'Frog Eggs' because shiny black tapioca pearls resemble frog eggs. Paired with wild Alishan Aiyu jelly and fresh lemon juice.","ja":"士林夜市発祥のユニークな名前のデザート。大粒タピオカの見た目がカエルの卵に似ていることから命名。阿里山の天然愛玉ゼリーと生レモン果汁で爽やかにいただきます。","ko":"스린 야시장에서 탄생한 명물 음료로, 흑당 버블의 둥글고 반짝이는 모양이 개구리알을 닮아 붙여진 이름입니다. 천연 아이위 젤리와 레몬즙이 어우러져 상큼합니다.","vi":"Món tráng miệng độc đáo chợ đêm Shilin, tên gọi 'Ếch đẻ trứng' xuất phát từ hình dáng trân châu đen tròn bóng như trứng ếch kết hợp thạch ái ngọc Alishan và chanh tươi."},"taiwaneseHokkien":"Tshinn-ua-lo̍h-nn̄g (ㄑㄧㄥ ㄨㄚ ㄌㄜ ㄋㄥ)","mandarinPinyin":"Qīngwā Xiàdàn (ㄑㄧㄥ ㄨㄚ ㄒㄧㄚˋ ㄉㄢˋ)","audioPronunciationText":"老闆，檸檬愛玉青蛙下蛋一杯，半糖少冰"},"ingredients":[{"id":"black-tapioca-pearls","name":{"zh-TW":"天然黑糖大粉圓 (波霸珍珠)","en":"Large Black Sugar Tapioca Pearls","ja":"大粒黒糖タピオカ","ko":"대왕 흑당 타피오카 펄","vi":"Trân châu đen hạt to nấu đường nâu"},"amount":150,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"chineseName":"黑糖大粉圓","chinesePinyin":"Hēitáng fěnyuán"},{"id":"wild-aiyu-jelly","name":{"zh-TW":"台灣野生手搓愛玉凍 (切大塊)","en":"Hand-Washed Wild Taiwanese Aiyu Jelly","ja":"台湾産 手揉み天然愛玉ゼリー","ko":"수제 천연 대만 아이위 젤리","vi":"Thạch Ái Ngọc thiên nhiên Đài Loan"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"chineseName":"天然愛玉凍","chinesePinyin":"Àiyù dòng"},{"id":"fresh-lemon-juice","name":{"zh-TW":"屏東九如鮮榨檸檬汁","en":"Freshly Squeezed Taiwan Lemon Juice","ja":"搾りたて生レモン果汁","ko":"갓 짠 생레몬즙","vi":"Nước cốt chanh tươi nguyên chất"},"amount":50,"unitMetric":"ml","unitUS":"3 tbsp","isKeyFlavor":true,"chineseName":"鮮榨檸檬汁","chinesePinyin":"Níngméng zhī"},{"id":"crushed-ice-syrup","name":{"zh-TW":"冬瓜黑糖蜜與碎冰","en":"Brown Sugar Winter Melon Syrup & Crushed Ice","ja":"冬瓜黒糖シロップ＆クラッシュアイス","ko":"흑당 시럽 및 갈은 얼음","vi":"Siro đường nâu bí đao và đá bào"},"amount":150,"unitMetric":"g","unitUS":"1 cup","chineseName":"黑糖蜜碎冰","chinesePinyin":"Hēitáng mì"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"滾水煮透大粉圓並慢火悶出極致Q彈","en":"Boil & Steam Pearls to Chewy Perfection","ja":"タピオカを芯まで茹でて蒸らし、モチモチに仕上げる","ko":"타피오카펄을 삶고 뜸 들여 극강의 쫀득함 만들기","vi":"Luộc chín trân châu hạt to và ủ cho dẻo dai từng hạt"},"instruction":{"zh-TW":"大鍋水燒至大滾，以放射狀撒入黑糖大粉圓。大火煮 20 分鐘（期間攪拌防止黏底），關火蓋上鍋蓋悶 20 分鐘使粉心徹底熟透軟Q。","en":"Bring large pot of water to rolling boil. Sprinkle in tapioca pearls, cook on high for 20 mins stirring occasionally. Turn off heat, cover and let steam for 20 mins until chewy throughout.","ja":"沸騰した湯にタピオカを入れ強火で20分茹で、火を止めてフタをし20分蒸らします。","ko":"끓는 물에 펄을 넣고 20분간 저어가며 삶은 뒤 불을 끄고 뚜껑을 덮어 20분간 뜸을 들입니다.","vi":"Thả trân châu vào nước sôi sùng sục luộc 20 phút, tắt bếp đậy vung ủ tiếp 20 phút cho trân châu dẻo quánh từ trong ra ngoài."},"durationSeconds":2400,"image":"/images/tw/taiwan-frog-eggs-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"冰水冰鎮瀝乾並拌入濃郁黑糖蜜浸漬","en":"Ice Shock, Drain & Steep in Brown Sugar Syrup","ja":"冷水で締めてから黒糖シロップに漬け込む","ko":"얼음물에 헹궈 탱글탱글하게 만든 뒤 흑당에 절이기","vi":"Xả nước đá lạnh cho săn chắc rồi ngâm đẫm siro đường nâu"},"instruction":{"zh-TW":"撈出熱粉圓倒入冰水中迅速沖洗降溫，瀝乾水分。倒入厚底鍋中，加入 50g 黑糖粉微火拌炒 3 分鐘至黑糖融化拉絲，讓每顆珍珠裹上晶瑩香濃的黑糖蜜。","en":"Rinse cooked pearls in ice water to shock them bouncy. Drain and mix in a pot with 50g brown sugar over low heat for 3 mins until glossy sugar syrup coats each pearl.","ja":"氷水で冷やして引き締め、水気を切ってから黒糖を加えて弱火で3分絡め、ツヤツヤの黒糖漬けにします。","ko":"얼음물에 헹궈 쫄깃함을 살린 후 흑당을 넣고 약불에서 3분간 졸여 반짝이는 흑당 펄을 만듭니다.","vi":"Xả qua nước đá cho săn hạt, để ráo rồi trộn với đường nâu trên lửa nhỏ 3 phút cho trân châu bóng bẩy ngấm ngọt."},"durationSeconds":300,"image":"/images/tw/taiwan-frog-eggs-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"切大塊野生愛玉凍鋪入杯底","en":"Cut Wild Aiyu Jelly into Chunks & Add to Cup","ja":"手揉み愛玉ゼリーを大きめに切ってグラスに入れる","ko":"수제 아이위 젤리를 큼직하게 썰어 컵에 담기","vi":"Cắt thạch ái ngọc thành từng miếng to cho vào đáy ly"},"instruction":{"zh-TW":"將晶瑩剔透、軟滑如果凍的手搓野生愛玉切成 2~3cm 的大方塊，舀入透明玻璃杯或大碗底部約半滿。","en":"Slice translucent bouncy wild aiyu jelly into generous 2-3cm cubes. Spoon into cups filling about half way.","ja":"プルプルの天然愛玉ゼリーを一口大の大きめに切り、グラスの底にたっぷり敷き詰めます。","ko":"탱글탱글하고 투명한 아이위 젤리를 큼직하게 깍둑썰기하여 컵에 절반 정도 채웁니다.","vi":"Cắt thạch ái ngọc trong veo mềm mướt thành miếng vuông lớn rồi cho vào nửa cốc."},"durationSeconds":120,"image":"/images/tw/taiwan-frog-eggs-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"鋪上黑亮青蛙下蛋、澆入檸檬汁與碎冰！","en":"Top with 'Frog Eggs' Pearls, Lemon Juice & Crushed Ice","ja":"黒糖タピオカをのせ、生レモン果汁とクラッシュアイスを注ぐ！","ko":"흑당 펄을 얹고 생레몬즙과 갈은 얼음을 부어 완성!","vi":"Múc trân châu đen lên trên, rót nước cốt chanh và đá bào mát lạnh!"},"instruction":{"zh-TW":"在愛玉凍上大勺鋪上溫熱黑亮的黑糖粉圓（青蛙下蛋），淋上鮮榨屏東檸檬汁與冬瓜糖蜜，最後鋪滿細碎冰塊，插上粗吸管攪勻大口啜飲，酸甜Q滑無比清爽！","en":"Top aiyu with glossy black pearls (Frog Eggs), drizzle fresh lemon juice & winter melon syrup, then fill with crushed ice. Stir with boba straw and enjoy the icy refreshing chew!","ja":"愛玉の上に熱々の黒糖タピオカをたっぷり盛り、搾りたてレモン汁とクラッシュアイスを加えて完成！ストローで混ぜながら爽快な喉越しを楽しんでください！","ko":"아이위 위에 윤기 나는 흑당 펄을 듬뿍 얹고 신선한 레몬즙과 얼음을 채워 굵은 빨대로 시원하게 마십니다.","vi":"Múc trân châu đường nâu lên trên thạch, rưới nước chanh tươi cùng siro bí đao rồi phủ đầy đá bào, cắm ống hút to khuấy đều thưởng thức!"},"durationSeconds":60,"image":"/images/tw/taiwan-frog-eggs-step4.jpg"}],"troubleshooting":[{"id":"boba-hard","problem":{"zh-TW":"粉圓遇到冰水後很快變硬咬不動？","en":"Why do the tapioca pearls get hard in ice?","ja":"氷に入れるとタピオカが固くなってしまう？","ko":"얼음과 닿으면 펄이 딱딱하게 굳나요?","vi":"Trân châu bị cứng đơ khi gặp đá lạnh?"},"cause":{"zh-TW":"粉心沒有悶透，或是直接浸泡在冰水裡太久。","en":"Pearls weren't fully steamed to the core or chilled too long.","ja":"蒸らし時間が足りず芯が残っていたか、氷水に長く浸けすぎました。","ko":"뜸 들이는 시간이 부족했거나 얼음 속에 너무 오래 방치되었기 때문입니다.","vi":"Chưa ủ chín lõi hoặc để ngâm trong đá quá lâu."},"solution":{"zh-TW":"煮 20 分鐘後務必關火悶 20 分鐘；用溫熱黑糖蜜保溫，喝之前再加碎冰！","en":"Always steam 20 mins with lid on, keep warm in brown sugar and add ice just before serving!","ja":"茹でた後しっかり20分蒸らし、温かいシロップで保温してお召し上がり直前に氷を入れてください！","ko":"삶은 후 20분간 반드시 뜸을 들이고, 따뜻한 시럽에 두었다가 마시기 직전에 얼음을 넣으세요!","vi":"Bắt buộc đậy nắp ủ 20 phút, giữ ấm trong siro đường và chỉ cho đá bào vào ngay trước khi uống!"}}],"proTips":[{"zh-TW":"愛玉必須是『天然野生愛玉子手搓』才會有入口即化的天然果膠清香，搭配九如檸檬的酸度是解膩第一名！","en":"Hand-washed wild Aiyu has a melt-in-mouth herbal aroma that harmonizes perfectly with acidic lemon!","ja":"天然の手揉み愛玉ゼリーの口どけと、フレッシュレモンの酸味が脂っこい夜市料理の後に最高です！","ko":"천연 수제 아이위 젤리의 부드러움과 신선한 레몬의 산미는 야시장 기름기를 싹 씻어줍니다!","vi":"Thạch Ái Ngọc vò tay tự nhiên mềm tan thanh mát kết hợp chanh tươi tạo nên tuyệt phẩm giải ngấy số 1!"}]},{"country":"tw","id":"oyster-vermicelli","slug":"oyster-vermicelli","title":{"zh-TW":"廟口經典大腸蚵仔麵線","en":"Taiwanese Braised Intestine & Oyster Vermicelli","ja":"台湾名物 牡蠣とホルモン入りとろみ素麺（蚵仔麵線）","ko":"대만 전통 곱창 굴 국수 (아종면선 스타일 오아미엔시엔)","vi":"Mì tuyến lòng heo hàu sữa chợ đêm Đài Loan"},"subtitle":{"zh-TW":"手工紅麵線・軟嫩入味滷大腸・肥美裹粉鮮蚵・柴魚薄芡","en":"Handmade Red Vermicelli, Braised Pork Intestines, Plump Oysters & Bonito Thick Broth","ja":"手延べ赤素麺・トロトロ豚ホルモン・ぷりぷり牡蠣・鰹出汁の効いた熱々とろみスープ","ko":"쫄깃한 붉은 쌀국수, 부드럽게 졸인 돼지곱창, 통통한 생굴과 감칠맛 가득 가쓰오부시 육수","vi":"Mì tuyến đỏ thủ công, lòng heo hầm nhừ, hàu sữa béo ngậy cùng nước súp cá ngừ sánh đậm"},"tagline":{"zh-TW":"全台廟口與西門町的排隊神話！站著吃也心甘情願的柴魚濃香","en":"The iconic street soup of Taiwan: standing on the curb slurping piping-hot vermicelli","ja":"西門町や台湾全土の廟口で大行列！立ち食いでも食べたい濃厚出汁の絶品とろみ麺","ko":"시먼딩 골목에서 서서 먹는 전설의 국민 국수! 뜨끈하고 걸쭉한 국물이 일품","vi":"Món mì súp huyền thoại phố Ximending khiến thực khách sẵn sàng đứng ăn xì xụp trên vỉa hè"},"heroImage":"/images/tw/taiwan-oyster-vermicelli-hero.jpg","difficulty":"medium","prepTimeMinutes":30,"cookTimeMinutes":25,"defaultServings":3,"caloriesPerServing":410,"category":"soups","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北萬華 / 鹿港廟口","en":"Taipei Wanhua / Lukang Miaokou","ja":"台北万華 / 鹿港廟口","ko":"타이베이 완화 / 루강 먀오커우","vi":"Vạn Hoa Đài Bắc / Lukang Miaokou"},"famousNightMarkets":[{"zh-TW":"艋舺夜市 / 廣州街夜市","en":"Bangka Night Market","ja":"艋舺夜市","ko":"방카 야시장","vi":"Chợ đêm Bangka"},{"zh-TW":"板橋湳雅夜市","en":"Banqiao Nanya Night Market","ja":"板橋湳雅夜市","ko":"반차오 난야 야시장","vi":"Chợ đêm Nanya"}],"historyStory":{"zh-TW":"源自台灣早期農耕社會的宴客點心，將蒸曬製成的手工紅麵線入柴魚高湯慢煮不爛。搭配嘉義東石鮮蚵裹地瓜粉防縮水，以及中藥醬油滷透的軟嫩豬大腸，佐工研烏醋、蒜泥、香菜，成就台灣最具代表性的一碗羹麵。","en":"A signature Taiwanese noodle soup made with steamed red vermicelli that remains silky and intact in rich bonito broth, paired with starch-coated fresh oysters and slow-braised pork intestines.","ja":"蒸して天日干ししたコシのある赤素麺を鰹出汁で煮込み、ぷりぷりの牡蠣と下味をつけた豚ホルモンをトッピング。黒酢とニンニクを効かせて食す国民的スープ麺。","ko":"가쓰오부시 육수에 붉은 면을 넣고 끓여 전분으로 걸쭉하게 만든 뒤 부드러운 곱창과 신선한 굴, 마늘즙, 흑식초를 넣어 먹는 대만의 대표 면 요리입니다.","vi":"Món mì truyền thống nấu từ sợi mì tuyến đỏ dẻo dai trong nước dùng cá ngừ đậm đà, ăn kèm lòng heo hầm ngũ vị và hàu sữa béo bùi."},"taiwaneseHokkien":"Ô-á mī-suànn (ㄛˊ ㄚˋ ㄇㄧˇ ㄙㄨㄊ)","mandarinPinyin":"Dàcháng Kēzǎi Miànxiàn (ㄉㄚˋ ㄔㄤˊ ㄎㄜ ㄗˇ ㄇㄧㄢˋ ㄒㄧㄢˋ)","audioPronunciationText":"大腸蚵仔麵線一碗，大碗、多蒜泥、多烏醋香菜"},"ingredients":[{"id":"red-vermicelli","name":{"zh-TW":"台灣手工紅麵線 (剪小段先泡水洗鹽分)","en":"Taiwanese Red Vermicelli (Rinsed)","ja":"台湾産 手延べ赤素麺","ko":"대만 전통 붉은 쌀국수 면","vi":"Mì tuyến đỏ Đài Loan (Ngâm xả bớt mặn)"},"amount":180,"unitMetric":"g","unitUS":"6 oz","isKeyFlavor":true,"chineseName":"手工紅麵線","chinesePinyin":"Hóng miànxiàn"},{"id":"fresh-oysters","name":{"zh-TW":"台灣東石肥美鮮蚵 (裹地瓜粉汆燙)","en":"Fresh Plump Oysters (Coated in Starch)","ja":"新鮮な生牡蠣（地瓜粉をまぶして湯通し）","ko":"신선한 통통한 생굴 (전분 코팅)","vi":"Hàu sữa tươi mọng (Lăn bột khoai lang chần sơ)"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"chineseName":"東石鮮蚵","chinesePinyin":"Xiān kē"},{"id":"braised-pork-intestines","name":{"zh-TW":"特製中藥滷豬大腸段","en":"Braised Savory Pork Intestines (Sliced)","ja":"特製醤油ダレで煮込んだ豚ホルモン","ko":"양념에 푹 조린 돼지곱창 슬라이스","vi":"Lòng già heo hầm ngũ vị cắt khúc"},"amount":150,"unitMetric":"g","unitUS":"5 oz","isKeyFlavor":true,"chineseName":"滷大腸","chinesePinyin":"Lǔ dàcháng"},{"id":"bonito-broth-seasoning","name":{"zh-TW":"柴魚片、冰糖、工研烏醋、蒜泥、香菜、太白粉芡水","en":"Bonito Flakes, Black Vinegar, Garlic Paste, Cilantro & Starch Slurry","ja":"鰹節、台湾黒酢、おろしニンニク、パクチー、水溶き片栗粉","ko":"가쓰오부시, 대만 흑식초, 다진 마늘, 고수, 전분물","vi":"Cá ngừ bào, giấm đen Đài Loan, tỏi băm, rau ngò rí và nước bột năng"},"amount":120,"unitMetric":"g","unitUS":"4 oz","isKeyFlavor":true,"chineseName":"柴魚烏醋蒜泥","chinesePinyin":"Cháiyú wūcù"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"鮮蚵洗淨裹地瓜粉汆燙鎖住鮮嫩","en":"Coat Fresh Oysters in Starch & Blanch","ja":"牡蠣を洗い地瓜粉をまぶしてサッと湯通しする","ko":"굴을 씻어 전분을 묻힌 뒤 살짝 데쳐 육즙 가두기","vi":"Rửa sạch hàu lăn qua bột khoai lang rồi chần nhanh qua nước sôi"},"instruction":{"zh-TW":"鮮蚵用少許鹽與生粉輕輕抓洗乾淨，瀝乾水分。均勻裹上一層地瓜粉，投入滾水中微火汆燙 30 秒至表面定型，撈出泡冰水防縮水變老。","en":"Rinse oysters gently with pinch of salt. Coat evenly in sweet potato starch. Drop into simmering water for 30 secs to set coating, transfer to cold water to lock plump juiciness.","ja":"牡蠣を優しく洗って水気を切り、地瓜粉を全体にまぶします。沸騰した湯で30秒湯通しし、冷水に取って身をぷりぷりに保ちます。","ko":"굴을 살살 씻어 물기를 뺀 뒤 고구마 전분을 고루 묻힙니다. 끓는 물에 30초간 데친 후 찬물에 담가 탱탱함을 유지합니다.","vi":"Rửa nhẹ hàu với chút muối, lăn đều bột khoai lang rồi thả vào nước sôi chần 30 giây, vớt ra ngâm nước lạnh giữ độ béo mọng."},"durationSeconds":300,"image":"/images/tw/taiwan-oyster-vermicelli-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"柴魚高湯煮紅麵線與調味","en":"Simmer Red Vermicelli in Bonito Broth","ja":"鰹出汁で赤素麺を煮込み調味する","ko":"가쓰오부시 육수에 붉은 면을 넣고 끓여 간 맞추기","vi":"Nấu mì tuyến đỏ trong nước dùng cá ngừ bào và nêm gia vị"},"instruction":{"zh-TW":"鍋中加入 1800ml 大骨高湯與一大把柴魚片煮滾出香氣。紅麵線剪成 5cm 小段洗去表面鹽分，放入鍋中煮約 10 分鐘，加入醬油、油蔥酥、冰糖與白胡椒粉調味。","en":"Boil 1800ml pork stock with generous bonito flakes. Cut red vermicelli to 5cm, rinse to remove excess salt, and simmer in broth for 10 mins. Season with soy sauce, fried shallots, rock sugar and white pepper.","ja":"出汁に鰹節を入れて煮立たせ、水洗いした赤素麺を加えて10分煮ます。醤油、揚げエシャロット、氷砂糖、コショウで味を調えます。","ko":"육수에 가쓰오부시를 넣고 끓이다가 씻은 붉은 면을 넣어 10분간 끓입니다. 간장, 샬롯튀김, 설탕, 후추로 간을 합니다.","vi":"Đun sôi 1.8L nước dùng với cá ngừ bào. Cắt mì thành khúc 5cm rửa sạch muối rồi thả vào nấu 10 phút, nêm nước tương, hành phi và tiêu."},"durationSeconds":600,"image":"/images/tw/taiwan-oyster-vermicelli-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"淋入太白粉水勾薄芡使湯汁濃滑","en":"Stir in Starch Slurry to Thicken Broth","ja":"水溶き片栗粉を回し入れ、とろみをつける","ko":"전분물을 둘러 국물을 걸쭉하게 만들기","vi":"Rót từ từ nước bột năng khuấy đều tạo độ sánh mượt"},"instruction":{"zh-TW":"將太白粉加水調勻成芡水。轉微火，邊順時針攪動麵線邊緩緩倒入芡水，煮至湯汁呈現晶瑩油亮、絲滑濃稠的微羹狀。","en":"Whisk starch with water. Lower heat and stir vermicelli clockwise while slowly pouring in slurry. Simmer until broth becomes glossy, velvety and thickened.","ja":"弱火にして水溶き片栗粉を少しずつ回し入れ、絶え間なくかき混ぜてツヤのあるなめらかなとろみをつけます。","ko":"약불로 줄이고 국수를 저어가며 전분물을 천천히 부어 윤기 있고 걸쭉한 농도를 만듭니다.","vi":"Hạ nhỏ lửa, vừa khuấy đều mì vừa rót từ từ nước bột năng vào đun đến khi nước súp sánh óng ả."},"durationSeconds":180,"image":"/images/tw/taiwan-oyster-vermicelli-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"盛碗鋪上大腸鮮蚵、淋蒜泥烏醋辣油！","en":"Ladle into Bowl, Top with Intestines, Oysters & Seasonings","ja":"器に盛り、ホルモンと牡蠣をのせ、ニンニク黒酢と辣油をかける！","ko":"그릇에 담고 곱창과 굴을 올린 뒤 마늘, 흑식초, 고추기름 뿌리기!","vi":"Múc ra bát xếp lòng heo hàu sữa lên trên, chan giấm đen tỏi ớt và ngò rí!"},"instruction":{"zh-TW":"將滾燙滑順的麵線舀入大碗中。表面鋪上滿滿的軟嫩滷大腸段與飽滿鮮蚵，淋上一大匙特調蒜泥汁、工研烏醋與自製辣椒油，撒上一大撮新鮮香菜，趁熱大口稀里呼嚕滑入喉嚨！","en":"Ladle piping-hot vermicelli into bowl. Crown with generous braised intestines and plump oysters. Spoon over minced garlic water, Taiwanese black vinegar, chili oil and fresh cilantro. Slurp enthusiastically!","ja":"熱々のとろみ素麺を器に盛り、煮込みホルモンと牡蠣をたっぷりトッピング。ニンニク水、台湾黒酢、ラー油、パクチーを添えて熱々をすするようにいただきます！","ko":"뜨거운 면선을 대접에 담고 부드러운 곱창과 통통한 굴을 듬뿍 얹습니다. 마늘즙, 대만 흑식초, 고추기름, 고수를 얹어 호로록 맛있게 드세요!","vi":"Múc mì súp nóng hổi ra bát, bày lòng heo hầm thơm lừng và hàu sữa mọng nước lên trên. Rưới sốt tỏi, giấm đen, sa tế và ngò rí thưởng thức xì xụp!"},"durationSeconds":60,"image":"/images/tw/taiwan-oyster-vermicelli-step4.jpg"}],"troubleshooting":[{"id":"vermicelli-watery","problem":{"zh-TW":"麵線吃到一半湯汁變清、出水化水？","en":"Why does my thick broth turn watery halfway through?","ja":"食べている途中でとろみがなくなってシャバシャバになる？","ko":"먹다 보면 국물이 묽어지며 물처럼 변하나요?","vi":"Nước súp đang ăn thì bị loãng ra thành nước trong?"},"cause":{"zh-TW":"口腔唾液中的澱粉酶分解了勾芡，或是太白粉未完全滾透熟化。","en":"Salivary amylase broke down the starch, or the starch slurry wasn't boiled through to activate properly.","ja":"唾液の酵素でデンプンが分解されたか、片栗粉の加熱不足です。","ko":"침 속 아밀라아제 효소가 전분을 분해했거나 전분이 덜 끓었기 때문입니다.","vi":"Do men amylase trong nước bọt phân giải tinh bột hoặc bột năng chưa được đun sôi chín kỹ."},"solution":{"zh-TW":"勾芡後務必維持微滾煮透 1 分鐘；吃的時候盡量用湯匙由邊緣舀取，避免攪拌整碗！","en":"Boil 1 full minute after slurring; scoop gently from the edge rather than stirring whole bowl!","ja":"とろみをつけた後1分しっかり沸騰させ、食べる時はかき混ぜずに端からすくってください！","ko":"전분물을 넣고 1분간 충분히 끓이고, 먹을 때는 휘젓지 말고 가장자리부터 떠드세요!","vi":"Đun sôi kỹ 1 phút sau khi xuống bột năng, khi ăn múc từ mép bát tránh khuấy đảo liên tục!"}}],"proTips":[{"zh-TW":"老饕精髓在於『三寶調料』：蒜泥水、工研烏醋與生辣椒醬，三者缺一不可，酸、香、辣交織才是台灣正宗夜市魂！","en":"The Holy Trinity of condiments: Garlic juice, Taiwanese black vinegar & fresh chili paste!","ja":"おろしニンニク水・台湾黒酢・生チリの三位一体が本場夜市の味を決定づけます！","ko":"마늘즙, 대만 흑식초, 생고추장 삼총사를 듬뿍 넣어야 진정한 대만의 맛이 완성됩니다!","vi":"Bộ ba thần thánh: nước tỏi, giấm đen Đài Loan và sa tế ớt là linh hồn không thể thiếu!"}]},{"country":"tw","id":"tube-rice-pudding","slug":"tube-rice-pudding","title":{"zh-TW":"台中清水傳承筒仔米糕","en":"Taichung Qingshui Tube Rice Pudding","ja":"台中国宝級 筒入り蒸しおこわ（筒仔米糕）","ko":"대만 타이중 칭수이 전통 원통 찹쌀밥 (통자이미가오)","vi":"Xôi hấp ống kim loại Chương Hóa / Thanh Thủy (Thùng Tử Mễ Cao)"},"subtitle":{"zh-TW":"油蔥炒圓糯米・底部鋪肥瘦滷肉與香菇・倒扣成筒・淋甜辣醬","en":"Shallot Stir-Fried Sticky Rice, Braised Pork Belly & Shiitake Inverted with Sweet Chili Sauce","ja":"エシャロット香る丸もち米・底に敷き詰めた豚角煮と椎茸・型抜きして特製甘辛ダレ","ko":"샬롯 기름에 볶은 찹쌀, 바닥에 깐 돼지고기 조림과 표고버섯, 뒤집어 빼내는 원통 찹쌀떡밥","vi":"Gạo nếp xào hành phi thơm lừng, thịt ba chỉ nấm hương lót đáy úp ngược chan sốt ngọt cay"},"tagline":{"zh-TW":"傳承百年的清水老城靈魂！小鐵筒蒸出粒粒分明又油潤黏糯的米香","en":"A century-old culinary treasure of central Taiwan: fragrant sticky rice steamed in metal tubes","ja":"100年の歴史を誇る名物！小さな筒で蒸し上げる、一粒一粒に旨味が染み渡った絶品おこわ","ko":"100년 전통의 타이중 명물! 작은 쇠원통에서 쪄내 밥알 하나하나 감칠맛이 가득한 찹쌀밥","vi":"Tinh hoa ẩm thực trăm năm với từng hạt nếp dẻo thơm ngậm trọn vị đậm đà của thịt kho"},"heroImage":"/images/tw/taiwan-tube-rice-hero.jpg","difficulty":"medium","prepTimeMinutes":35,"cookTimeMinutes":45,"defaultServings":4,"caloriesPerServing":460,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originCity":{"zh-TW":"台中清水 / 台北大橋頭延三","en":"Taichung Qingshui / Taipei Yansan","ja":"台中清水 / 台北大橋頭延三","ko":"타이중 칭수이 / 타이베이 옌싼","vi":"Qingshui Đài Trung / Yansan Đài Bắc"},"famousNightMarkets":[{"zh-TW":"大橋頭延三夜市","en":"Yansan Night Market","ja":"延三夜市","ko":"옌싼 야시장","vi":"Chợ đêm Yansan"},{"zh-TW":"清水王塔 / 阿財米糕老店","en":"Qingshui Wangta / Acai Rice Cake","ja":"清水王塔米糕","ko":"칭수이 왕타 미가오","vi":"Qingshui Acai Mễ Cao"}],"historyStory":{"zh-TW":"相傳源自北宋蘇東坡的『盤游飯』，近代在台中清水發揚光大。早期用竹筒盛裝，後改良為特製小鐵筒。將炒過蔥油醬汁的圓糯米填入鋪有滷肉、香菇、蝦米的小鐵筒蒸透，食用時倒扣脫模，淋上紅豔甜辣醬與香菜。","en":"Dating back to traditional banquet rice, perfected in Qingshui, Taichung. Glutinous rice stir-fried with shallot oil is packed into small metal cylinders over braised pork and shiitake, steamed tender and unmolded upside down.","ja":"昔は竹筒で作られていた台中・清水の名物料理。炒めたもち米を豚肉や干しエビと一緒に金属の小筒に詰めて蒸し上げ、皿にひっくり返して甘辛ダレをかけて食します。","ko":"옛날 대나무통에서 유래하여 쇠원통에 볶은 찹쌀과 돼지고기, 버섯을 넣고 쪄내 뒤집어 담아내는 대만 중부의 대표 전통 요리입니다.","vi":"Xuất phát từ cách hấp trong ống tre, ngày nay được gói trong ống kim loại nhỏ hấp chín úp ngược ra đĩa rưới sốt tương ớt đỏ rực thơm ngon."},"taiwaneseHokkien":"Tâng-á bí-ko (ㄉㄤˊ ㄚˋ ㄅㄧˋ ㄍㄜ)","mandarinPinyin":"Tǒngzǎi Mǐgāo (ㄊㄨㄥˇ ㄗˇ ㄇㄧˇ ㄍㄠ)","audioPronunciationText":"米糕兩筒，都要加辣醬加香菜，再配一碗肉羹湯"},"ingredients":[{"id":"round-glutinous-rice","name":{"zh-TW":"台灣優質圓糯米 (泡水 2 小時瀝乾)","en":"Round Glutinous Rice (Soaked 2 Hours)","ja":"台湾産 丸もち米（2時間浸水）","ko":"둥근 찹쌀 (2시간 불린 것)","vi":"Gạo nếp cái hạt tròn (Ngâm 2 tiếng)"},"amount":300,"unitMetric":"g","unitUS":"1.5 cups","isKeyFlavor":true,"chineseName":"圓糯米","chinesePinyin":"Yuán nuòmǐ"},{"id":"pork-belly-slices","name":{"zh-TW":"帶皮五花肉片與豬後腿肉丁","en":"Pork Belly Slices & Lean Pork Dices","ja":"皮付き豚バラ肉スライス＆豚もも肉角切り","ko":"껍질 붙은 삼겹살 슬라이스 및 돼지고기 깍둑썰기","vi":"Thịt ba chỉ heo có bì và thịt nạc thái nhỏ"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"chineseName":"五花肉後腿肉","chinesePinyin":"Wǔhuā ròu"},{"id":"shallots-dried-shrimp","name":{"zh-TW":"紅蔥頭酥、乾香菇片、金鉤蝦米","en":"Crispy Fried Shallots, Dried Shiitake, Dried Shrimp","ja":"揚げエシャロット、干し椎茸、干しエビ","ko":"샬롯 튀김, 건표고버섯, 건새우","vi":"Hành tím phi, nấm hương khô, tôm nõn khô"},"amount":80,"unitMetric":"g","unitUS":"3 oz","isKeyFlavor":true,"chineseName":"油蔥香菇蝦米","chinesePinyin":"Yóucōng xiānggū"},{"id":"rice-pudding-sauce","name":{"zh-TW":"清水秘製甜辣醬與新鮮香菜","en":"Signature Qingshui Sweet Chili Sauce & Cilantro","ja":"清水特製甘辛ダレ＆フレッシュパクチー","ko":"칭수이 특제 스위트 칠리소스 및 고수","vi":"Sốt tương ớt ngọt Thanh Thủy và rau ngò tươi"},"amount":80,"unitMetric":"ml","unitUS":"3 tbsp","isKeyFlavor":true,"chineseName":"甜辣醬香菜","chinesePinyin":"Tiánlà jiàng"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"炒香紅蔥肉燥、香菇與蝦米配料","en":"Sauté Braised Pork, Shiitake & Dried Shrimp","ja":"豚肉、椎茸、干しエビ、エシャロットを香ばしく炒める","ko":"돼지고기, 표고버섯, 건새우, 샬롯을 볶아 조리기","vi":"Xào thơm thịt ba chỉ với nấm hương, tôm khô và hành phi"},"instruction":{"zh-TW":"熱鍋下少許豬油，炒香香菇片、金鉤蝦米與五花肉片。加入醬油、米酒、五香粉、白胡椒粉與油蔥酥慢炒至上色入味，撈出部分肉片與香菇留作筒底配料。","en":"Heat lard in wok, sauté shiitake, dried shrimp and pork belly. Season with soy sauce, rice wine, five-spice, white pepper and crispy shallots until fragrant. Set aside slices for tube bottom.","ja":"ラードで椎茸、干しエビ、豚肉を炒め、醤油、酒、五香粉、揚げエシャロットで香ばしく味付けします。筒底用の具を少し取り分けておきます。","ko":"팬에 라드를 두르고 버섯, 건새우, 삼겹살을 볶다가 간장, 맛술, 오향분, 샬롯튀김을 넣어 조립니다. 바닥에 깔 고기 일부를 따로 덜어둡니다.","vi":"Đun nóng mỡ heo xào thơm nấm, tôm khô và thịt ba chỉ. Nêm nước tương, rượu, ngũ vị hương và hành phi cho vàng óng, múc riêng một ít thịt để lót đáy ống."},"durationSeconds":480,"image":"/images/tw/taiwan-tube-rice-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"圓糯米入鍋拌炒吸飽紅蔥醬汁香氣","en":"Stir-Fry Soaked Glutinous Rice in Shallot Sauce","ja":"浸水させた丸もち米を加え、旨味タレを吸わせるように炒める","ko":"불린 찹쌀을 넣고 소스가 배어들도록 볶기","vi":"Cho gạo nếp đã ngâm vào xào cho hạt nếp ngậm no nước sốt"},"instruction":{"zh-TW":"將泡好瀝乾的圓糯米倒入留有濃郁肉汁的炒鍋中，中小火快速翻炒 3~5 分鐘，讓每粒糯米均勻裹上一層琥珀色油蔥醬香，米粒呈半透明微熟狀。","en":"Add drained soaked glutinous rice to remaining savory gravy in wok. Stir-fry over medium heat for 3-5 mins until grains turn glossy amber and absorb all flavors.","ja":"水気を切ったもち米をフライパンに残ったタレに加え、中火で3〜5分炒めて米粒に旨味を吸わせます。","ko":"물기 뺀 찹쌀을 남은 양념에 넣고 중불에서 3-5분간 볶아 밥알이 양념을 듬뿍 머금게 합니다.","vi":"Đổ nếp ráo nước vào chảo sốt xào đều tay 3-5 phút cho từng hạt nếp bóng bẩy ngấm màu nâu vàng cánh gián."},"durationSeconds":300,"image":"/images/tw/taiwan-tube-rice-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"鐵筒底部鋪肉片香菇、填米壓實蒸透","en":"Layer Pork in Tubes, Pack with Rice & Steam","ja":"筒の底に具を敷き、炒めたもち米を詰めて蒸し上げる","ko":"원통 바닥에 고기를 깔고 찹쌀을 채워 찌기","vi":"Lót thịt nấm dưới đáy ống, xúc nếp nén chặt và đem hấp"},"instruction":{"zh-TW":"在小鐵筒（或耐熱小杯）內壁塗薄油，底部先鋪上炒香的五花肉片、香菇與鹹蛋黃。填入炒好的糯米至九分滿，用湯匙輕輕壓實。放入蒸籠大火蒸 40~45 分鐘至米粒軟糯彈牙。","en":"Brush inside of metal tubes with oil. Place pork slices, shiitake and salted egg yolk at bottom. Pack in seasoned rice to 90% full, press lightly. Steam on high for 40-45 mins until tender and chewy.","ja":"小筒の内側に油を塗り、底に豚肉と椎茸を敷いてから炒めたもち米を詰めます。蒸し器で強火40〜45分ふっくら蒸し上げます。","ko":"작은 원통 안쪽에 기름을 바르고 바닥에 고기와 버섯을 깐 뒤 찹쌀을 90% 채워 꾹 누릅니다. 찜기에서 40-45분간 푹 쪄냅니다.","vi":"Quét dầu lòng ống kim loại, xếp thịt nấm trứng muối xuống đáy, múc nếp vào nén vừa tay. Hấp lửa lớn 40-45 phút cho xôi chín dẻo mềm."},"durationSeconds":2700,"image":"/images/tw/taiwan-tube-rice-step3.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Steam Mode High Pressure: 25 mins + Quick Release","instructionOverride":{"zh-TW":"在 Instant Pot 內膽中注入 1.5 杯清水，放入高腳蒸架。將裝好料與糯米的鐵筒平穩排在蒸架上，鎖上鍋蓋。設定 Steam（蒸煮）高壓模式 25 分鐘，時間到後手動快速洩壓。米粒顆顆晶瑩剔透、軟糯Q彈！","en":"Pour 1.5 cups water into Instant Pot, insert trivet. Place loaded metal tubes on trivet, lock lid. Set Steam mode on High Pressure for 25 mins, then Quick Release. Perfectly chewy and aromatic!","ja":"インスタントポットに水1.5カップを入れ蒸し台をセット。筒を並べて蓋をし、Steam高圧モードで25分加熱後クイック減圧。驚くほどモチモチに！","ko":"인스턴트팟에 물 1.5컵을 붓고 찜기를 올린 뒤 원통을 얹습니다. Steam 모드 고압 25분 설정 후 쾌속 감압합니다. 밥알이 쫀득쫀득 완벽하게 익습니다!","vi":"Đổ 1.5 cốc nước vào nồi Instant Pot, đặt giá hấp rồi xếp ống xôi lên. Chọn chế độ Steam áp suất cao 25 phút rồi xả van nhanh."}}]},{"stepNumber":4,"title":{"zh-TW":"倒扣脫模出筒、淋滿靈魂甜辣醬！","en":"Invert Tube onto Plate & Drench in Sweet Chili Sauce","ja":"皿の上にひっくり返して抜き取り、特製甘辛ダレをかける！","ko":"접시에 거꾸로 뒤집어 빼내고 달콤 매콤 소스 뿌리기!","vi":"Úp ngược ống ra đĩa gỡ bánh và chan đẫm sốt tương ngọt cay!"},"instruction":{"zh-TW":"蒸好後取出小鐵筒，沿邊緣用扁竹籤劃一圈，倒扣在盤中央輕敲脫模。立體圓柱狀的米糕頂端呈現油亮五花肉與香菇，淋上濃郁的台灣紅甜辣醬與鮮香菜，熱氣騰騰開動！","en":"Run thin spatula around tube edge and invert firmly onto plate. The freestanding cylinder reveals glistening pork and mushrooms on top. Ladle signature sweet chili sauce and fresh cilantro over top!","ja":"ヘラで縁を外し、お皿の上にポンとひっくり返して抜きます。艶やかな豚肉が頂点に現れたら、特製甘辛ダレとパクチーをたっぷりかけて熱々をどうぞ！","ko":"가장자리를 긁어 접시에 뒤집어 빼내면 윤기 나는 고기가 얹어진 원통형 찹쌀밥이 완성됩니다. 달콤 매콤 소스와 고수를 뿌려 즐깁니다.","vi":"Dùng que mỏng lách quanh miệng ống úp ngược ra đĩa. Khối xôi hình trụ lộ ra lớp thịt ba chỉ óng ả trên đỉnh, chan đẫm sốt tương ngọt cay rắc ngò rí nóng hổi hấp dẫn!"},"durationSeconds":60,"image":"/images/tw/taiwan-tube-rice-step4.jpg"}],"troubleshooting":[{"id":"rice-hard","problem":{"zh-TW":"米糕蒸出來米粒夾生或太硬？","en":"Why is my steamed rice undercooked or too hard?","ja":"おこわが芯残りして固くなってしまった？","ko":"찹쌀밥에 설익은 심이 남고 딱딱한가요?","vi":"Xôi hấp xong bị sượng cứng chưa chín thấu?"},"cause":{"zh-TW":"圓糯米浸泡時間不足，或蒸鍋蒸汽不夠大。","en":"Rice wasn't soaked long enough or low steam heat.","ja":"浸水時間が短かったか、蒸気の火力が弱かったためです。","ko":"찹쌀을 불리는 시간이 짧았거나 찜기 화력이 약했기 때문입니다.","vi":"Chưa ngâm nếp đủ 2 tiếng hoặc lửa hấp quá yếu."},"solution":{"zh-TW":"圓糯米必須浸泡足 2 小時；炒米時加少許高湯吸水，全程大火足汽蒸 45 分鐘！","en":"Soak 2 hours minimum; add splash of stock during stir-fry and steam on full blast for 45 mins!","ja":"最低2時間浸水させ、炒める際に出汁を吸わせ、強火で45分蒸してください！","ko":"최소 2시간 불리고 볶을 때 육수를 조금 주어 센 불에서 45분간 찌세요!","vi":"Phải ngâm đủ 2 tiếng, khi xào nếp châm thêm chút nước dùng và hấp lửa lớn đủ 45 phút!"}}],"proTips":[{"zh-TW":"筒底一定要放一片帶皮厚切肥瘦五花肉，蒸透後豬油精華自頂向下滲透整筒糯米，粒粒油亮噴香！","en":"Place fatty pork belly at the bottom so rendered lard drips down through all rice grains during steaming!","ja":"底に敷く豚バラ肉の脂が蒸気で溶け出し、下のもち米全体に染み渡るのが最高の美味しさの秘密！","ko":"바닥에 비계가 적당한 삼겹살을 깔아야 찌는 동안 돼지기름이 밥 전체로 스며들어 윤기가 흐릅니다!","vi":"Lót miếng ba chỉ có mỡ dưới đáy ống để khi hấp mỡ heo chảy thấm đều xuống từng hạt nếp thơm lừng béo ngậy!"}]},{"country":"tw","id":"mee-tai-bak","slug":"mee-tai-bak","title":{"zh-TW":"台東柴魚肉燥乾拌米苔目","en":"Taitung Dry-Tossed Mee Tai Bak (Rice Noodles with Bonito)","ja":"台東名物 鰹節と肉味噌の和え米苔目（ミータイバック）","ko":"대만 타이둥 가쓰오부시 돼지고기 비빔 미타이목 (쌀국수)","vi":"Bánh lọt khô xào thịt băm cá ngừ bào Đài Đông (Mee Tai Bak)"},"subtitle":{"zh-TW":"純在來米手工滑溜粗麵條・飛舞極薄柴魚片・香濃紅蔥肉燥・爽脆豆芽","en":"Silky Pure Rice Noodles, Dancing Bonito Flakes, Fragrant Shallot Pork Gravy & Bean Sprouts","ja":"ツルツル米粉極太麺・踊る極薄花鰹・香り高いエシャロット肉味噌・シャキシャキもやし","ko":"순쌀로 만든 미끄러운 굵은 쌀면, 춤추는 얇은 가쓰오부시, 고소한 샬롯 고기볶음, 아삭한 숙주","vi":"Sợi bánh lọt gạo tẻ trơn tuột, cá ngừ bào mỏng tang nhảy múa, thịt kho hành phi và giá đỗ giòn"},"tagline":{"zh-TW":"台東老饕無人不曉的傳奇主食！熱氣騰騰上桌時柴魚片在碗中翩翩起舞","en":"The legendary culinary emblem of Taitung: silky rice noodles crowned with dancing bonito flakes","ja":"台東を訪れたら必食のソウルフード！熱々の湯気で鰹節が踊る、出汁と肉味噌の香ばしい一杯","ko":"타이둥 여행의 필수 코스! 뜨거운 면 위에서 가쓰오부시가 춤을 추는 잊지 못할 풍미","vi":"Đặc sản nức tiếng Đài Đông với những lát cá ngừ bào nhảy múa sinh động trên làn khói nghi ngút"},"heroImage":"/images/tw/taiwan-mee-tai-bak-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":390,"category":"mains","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台東市 / 台北大同延三","en":"Taitung City / Taipei Yansan","ja":"台東市 / 台北延三","ko":"타이둥시 / 타이베이 옌싼","vi":"Thành phố Đài Đông / Yansan Đài Bắc"},"famousNightMarkets":[{"zh-TW":"台東觀光夜市","en":"Taitung Night Market","ja":"台東観光夜市","ko":"타이둥 야시장","vi":"Chợ đêm Đài Đông"},{"zh-TW":"大橋頭延三夜市","en":"Yansan Night Market","ja":"延三夜市","ko":"옌싼 야시장","vi":"Chợ đêm Yansan"}],"historyStory":{"zh-TW":"米苔目為客家與閩南傳統米食，用在來米磨漿漏篩入滾水中燙熟。台東因鄰近成功漁港盛產柴魚，老店獨創在熱騰騰乾拌米苔目上撒上大把極薄柴魚片，搭配油蔥肉燥、烏醋與辣椒醬，鹹鮮甘甜。","en":"A traditional Hakka and Taiwanese rice noodle extruded through sieves into boiling water. Taitung locals ingeniously paired it with local artisan bonito flakes from Chenggong Fishing Port.","ja":"米粉を穴の開いたヘラから押し出して茹でる伝統の米麺。成功漁港の鰹節をたっぷりトッピングした台東スタイルが全国的に有名。","ko":"멥쌀 반죽을 구멍 뚫린 틀에 밀어 넣어 삶아낸 전통 쌀국수로, 가쓰오부시 명산지인 타이둥에서 특화된 대표 지역 음식입니다.","vi":"Bánh lọt làm từ bột gạo tẻ ép qua khuôn vào nước sôi, kết hợp cá ngừ bào Chenggong nức tiếng Đài Đông tạo nên hương vị mặn ngọt đậm đà."},"taiwaneseHokkien":"Bí-thai-ba̍k (ㄅㄧˋ ㄊㄞ ㄅㄚˊ)","mandarinPinyin":"Mǐtáimù (ㄇㄧˇ ㄊㄞˊ ㄇㄨˋ)","audioPronunciationText":"米苔目乾的一碗，加一顆滷蛋、柴魚多一點"},"ingredients":[{"id":"fresh-rice-noodles","name":{"zh-TW":"純在來米手工生米苔目","en":"Fresh Handmade Pure Rice Noodles (Mee Tai Bak)","ja":"生米苔目（米粉の極太麺）","ko":"신선한 수제 순쌀 미타이목 생면","vi":"Sợi bánh lọt gạo tẻ tươi"},"amount":300,"unitMetric":"g","unitUS":"10 oz","isKeyFlavor":true,"chineseName":"生米苔目","chinesePinyin":"Shēng mǐtáimù"},{"id":"taitung-bonito-flakes","name":{"zh-TW":"台東成功特產頂級細薄柴魚片","en":"Taitung Artisan Thin-Shaved Bonito Flakes","ja":"台東特産 極薄削り節（花鰹）","ko":"타이둥 특산 얇은 가쓰오부시","vi":"Cá ngừ bào mỏng cao cấp Đài Đông"},"amount":25,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"chineseName":"台東柴魚片","chinesePinyin":"Cháiyú piàn"},{"id":"shallot-pork-gravy","name":{"zh-TW":"古早味紅蔥頭肉燥 (淋醬用)","en":"Taiwanese Braised Shallot Minced Pork Gravy","ja":"エシャロット香る特製豚ひき肉ダレ","ko":"샬롯 기름 돼지고기 소스 (루로우)","vi":"Thịt băm kho hành tím phi thơm lừng"},"amount":100,"unitMetric":"g","unitUS":"0.5 cup","isKeyFlavor":true,"chineseName":"紅蔥肉燥","chinesePinyin":"Yóucōng ròuzào"},{"id":"bean-sprouts-chives","name":{"zh-TW":"鮮脆綠豆芽與韭菜段、工研烏醋","en":"Crisp Bean Sprouts, Chinese Chives & Black Vinegar","ja":"シャキシャキもやし、ニラ、台湾黒酢","ko":"아삭한 숙주, 부추, 대만 흑식초","vi":"Giá đỗ tươi, hẹ lá và giấm đen"},"amount":100,"unitMetric":"g","unitUS":"1 cup","chineseName":"豆芽韭菜烏醋","chinesePinyin":"Dòuyá jiǔcài"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"大滾水汆燙新鮮米苔目保持滑溜彈性","en":"Blanch Fresh Rice Noodles in Boiling Water","ja":"熱湯で米苔目をサッと茹でてコシを残す","ko":"끓는 물에 쌀국수 면을 살짝 데쳐 쫄깃함 살리기","vi":"Chần sợi bánh lọt trong nước sôi giữ độ dai trơn bóng"},"instruction":{"zh-TW":"大鍋水燒至大滾，投入新鮮米苔目、豆芽菜與韭菜段。大火汆燙約 40~60 秒至米苔目完全透亮浮起，立即用撈杓撈起、充分瀝乾水分。","en":"Bring pot of water to rolling boil. Drop in fresh rice noodles, bean sprouts and chives. Blanch for 40-60 secs until translucent and floating, drain thoroughly.","ja":"沸騰した湯に生米苔目、もやし、ニラを入れ、強火で40〜60秒茹でてザルに上げ、水気をしっかり切ります。","ko":"끓는 물에 면, 숙주, 부추를 넣고 40-60초간 살짝 데친 후 건져 물기를 완전히 뺍니다.","vi":"Cho sợi bánh lọt, giá đỗ và hẹ vào nồi nước sôi sùng sục chần nhanh 40-60 giây cho trong vớt ra để ráo nước."},"durationSeconds":60,"image":"/images/tw/taiwan-mee-tai-bak-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"裝入碗中並澆淋大勺滾燙古早味肉燥","en":"Place in Bowl & Ladle Piping-Hot Minced Pork Gravy","ja":"器に盛り、熱々のエシャロット肉味噌をたっぷりかける","ko":"그릇에 담고 뜨거운 돼지고기 소스를 듬뿍 붓기","vi":"Cho vào bát và chan ngập sốt thịt băm kho hành phi nóng hổi"},"instruction":{"zh-TW":"將燙好的米苔目與鮮脆豆芽韭菜盛入大碗中。趁熱澆上 2 大勺熬煮得濃郁噴香、帶有豬油蔥香的古早味肉燥滷汁，淋上半小匙工研烏醋提鮮。","en":"Transfer drained noodles and greens into a large serving bowl. Ladle 2 generous scoops of piping-hot shallot pork gravy over top with 1/2 tsp Taiwanese black vinegar.","ja":"器に盛り付け、豚の脂とエシャロットの旨味が凝縮された熱々の肉味噌ダレをたっぷりかけ、黒酢を少し垂らします。","ko":"그릇에 담고 깊은 풍미의 뜨거운 샬롯 고기소스를 2큰술 듬뿍 끼얹은 뒤 흑식초를 살짝 둘러줍니다.","vi":"Cho bánh lọt và rau vào bát, múc 2 muôi thịt kho hành phi nóng rực rưới lên trên thêm chút giấm đen thơm nồng."},"durationSeconds":60,"image":"/images/tw/taiwan-mee-tai-bak-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"大把撒上極薄柴魚片、看熱氣中翩翩起舞","en":"Top with Handful of Dancing Bonito Flakes","ja":"極薄の花鰹を山盛りにのせ、熱気で踊るのを楽しむ","ko":"얇은 가쓰오부시를 한 줌 듬뿍 얹어 춤추는 모습 보기","vi":"Rắc đầy cá ngừ bào mỏng ngắm nhìn từng lát cá nhảy múa trên làn khói"},"instruction":{"zh-TW":"在熱氣騰騰的肉燥上方，豪邁地撒上一大把極細薄的台東成功柴魚片。熱氣蒸騰上升時，只見粉紅褐色的柴魚片在碗中生動地翻滾翩翩起舞，香氣四溢！","en":"Heap a generous mound of paper-thin Taitung bonito flakes over the hot noodles. Watch the flakes dance and curl mesmerizingly in the rising steam!","ja":"熱々の肉味噌の上に、台東特産の極薄削り節を山盛りにのせます。立ち上る湯気で鰹節が生きているように踊り、食欲をそそる香りが広がります！","ko":"뜨거운 고기 위에 얇은 가쓰오부시를 수북하게 올립니다. 모락모락 피어오르는 김에 가쓰오부시가 춤을 추며 고소한 향을 풍깁니다!","vi":"Rắc một nắm lớn cá ngừ bào mỏng lên đỉnh bát, hơi nóng bốc lên khiến từng lát cá uốn lượn nhảy múa tỏa hương thơm quyến rũ!"},"durationSeconds":30,"image":"/images/tw/taiwan-mee-tai-bak-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"加入蒜泥辣醬拌勻、大口吸入極致滑溜！","en":"Mix with Garlic & Chili, Slurp the Silky Goodness!","ja":"おろしニンニクと特製チリを混ぜ合わせ、豪快にすする！","ko":"다진 마늘과 고추장을 넣어 비벼 호로록 맛보기!","vi":"Trộn đều cùng tỏi ớt băm và xì xụp thưởng thức sợi mì mềm mướt!"},"instruction":{"zh-TW":"加入半茶匙新鮮蒜泥與特製辣椒醬。用筷子由底向上充分攪拌，讓每根純米米苔目都裹滿油亮肉燥、黏附著融化的柴魚香氣，大口吸入，滑溜過癮！","en":"Add minced garlic and chili paste. Toss thoroughly from the bottom so every smooth noodle strand is glossy with pork sauce and clings with savory bonito umami!","ja":"ニンニクと唐辛子ペーストを加え、底からしっかり混ぜ合わせます。米麺のツルッとした喉越しと鰹節の深いコクを一気にすすって堪能してください！","ko":"마늘과 매콤한 소스를 더해 골고루 비벼줍니다. 밥알처럼 매끄러운 쌀면과 진한 가쓰오부시 고기 양념이 어우러져 입안 가득 감동을 줍니다!","vi":"Thêm tỏi ớt băm trộn đều từ đáy bát cho từng sợi bánh lọt thấm đẫm sốt thịt và vụn cá ngừ thơm lừng húp trọn từng sợi trơn tuột tuyệt đỉnh!"},"durationSeconds":60,"image":"/images/tw/taiwan-mee-tai-bak-step4.jpg"}],"troubleshooting":[{"id":"noodles-mushy","problem":{"zh-TW":"米苔目汆燙後糊成一團或斷碎？","en":"Why are my rice noodles breaking into mushy bits?","ja":"米苔目が切れたりベチャベチャに崩れてしまう？","ko":"면이 뚝뚝 끊어지거나 죽처럼 퍼지나요?","vi":"Sợi bánh lọt bị nhũn nát đứt vụn?"},"cause":{"zh-TW":"水溫不夠滾就下鍋，或燙煮時間過長。","en":"Water wasn't at a rolling boil, or overcooked.","ja":"お湯の沸騰が不十分だったか、茹ですぎが原因です。","ko":"물이 충분히 끓지 않았거나 너무 오래 삶았기 때문입니다.","vi":"Nước chưa sôi bùng đã thả vào hoặc luộc quá lâu."},"solution":{"zh-TW":"水必須大滾才能下鍋，燙 40~60 秒一浮起立刻撈出瀝乾！","en":"Must plunge into rolling boil, blanch for only 40-60 secs until floating and drain immediately!","ja":"しっかり沸騰した湯で40〜60秒サッと茹で、浮いたらすぐ湯切りしてください！","ko":"물이 팔팔 끓을 때 넣고 40-60초만 가볍게 데쳐 바로 건져내세요!","vi":"Nước phải sôi sùng sục mới thả vào, chần 40-60 giây thấy nổi là vớt ra ráo nước ngay!"}}],"proTips":[{"zh-TW":"正宗台東老饕吃法：乾拌吃完留下一點柴魚肉燥底，再跟老闆討一碗熱騰騰的大骨大腸湯沖入碗中喝個精光！","en":"Taitung tradition: finish the dry noodles, then pour hot bone broth into the leftover savory bowl!","ja":"食べ終わった後の丼に熱い豚骨スープを注いで飲み干すのが本場台東のツウの流儀！","ko":"비빔면을 다 먹고 남은 양념에 따뜻한 사골 육수를 부어 마시는 것이 로컬들의 비법!","vi":"Cách ăn sành điệu: ăn hết mì khô châm thêm nước dùng xương hầm nóng hổi vào bát húp sạch!"}]},{"country":"tw","id":"pot-burn-e-noodle","slug":"pot-burn-e-noodle","title":{"zh-TW":"台南府城經典鍋燒意麵","en":"Tainan Pot-Burn E-Noodles (Nabeyaki Seafood Soup)","ja":"台南名物 鍋焼き揚げたまご麺（鍋焼意麺）","ko":"대만 타이난 전통 뚝배기 튀김 에그누들 (궈샤오 이미엔)","vi":"Mì trứng chiên thố nhôm hải sản Đài Nam (Quoa Shao Yi Mien)"},"subtitle":{"zh-TW":"金黃炸全蛋意麵・鮮甜柴魚高湯・炸蝦天婦羅・水波半熟蛋・復古井字木架","en":"Deep-Fried Egg Noodles, Sweet Bonito Dashi, Tempura Shrimp, Poached Egg & Wooden Lattice Stand","ja":"サクサク揚げ卵麺・甘みのある鰹出汁・エビ天ぷら・半熟卵・レトロな井桁木台の小鍋","ko":"바삭하게 튀긴 계란면, 달큰한 가쓰오부시 육수, 새우튀김, 반숙란, 복고풍 나무 받침 알루미늄 냄비","vi":"Mì trứng chiên giòn, nước dùng cá ngừ ngọt thanh, tôm chiên xù, trứng lòng đào trong nồi nhôm đế gỗ"},"tagline":{"zh-TW":"台南早餐到宵夜的靈魂美食！吸飽鮮美柴魚高湯的澎鬆油炸意麵","en":"The iconic comfort bowl of Tainan: crispy fried noodles soaking up sweet seafood broth","ja":"台南人が朝食から夜食まで愛してやまない名物！スープを吸った揚げ麺の独特な食感がたまらない","ko":"타이난 사람들의 아침부터 야식까지 책임지는 소울푸드! 감칠맛 육수를 듬뿍 머금은 튀김면","vi":"Món mì quốc dân Đài Nam từ sáng sớm đến đêm khuya với sợi mì trứng nở phồng ngậm trọn tinh túy biển cả"},"heroImage":"/images/tw/taiwan-pot-burn-noodle-hero.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":12,"defaultServings":2,"caloriesPerServing":520,"category":"soups","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台南市中西區 / 國華街","en":"Tainan Guohua Street","ja":"台南市国華街","ko":"타이난 궈화제","vi":"Phố Guohua Đài Nam"},"famousNightMarkets":[{"zh-TW":"台南花園夜市","en":"Tainan Flower Night Market","ja":"花園夜市","ko":"타이난 화위안 야시장","vi":"Chợ đêm Hoa Viên Đài Nam"},{"zh-TW":"國華街美食街","en":"Guohua Street Food Court","ja":"国華街","ko":"궈화제 먹자골목","vi":"Phố ẩm thực Guohua"}],"historyStory":{"zh-TW":"日治時期台南將日式鍋燒烏龍麵（Nabeyaki Udon）在地化改良，換上福州傳入的全蛋油炸『意麵』。麵條經油炸後形成無數微小孔隙，放入復古小鋁鍋中吸飽清甜柴魚大骨湯，搭配炸蝦、蛤蜊、半熟蛋與魚板，成為全台灣最著名的麵食之一。","en":"Adapted during the Japanese era from Nabeyaki Udon into a uniquely Taiwanese dish using deep-fried egg noodles that rapidly drink up sweet bonito broth.","ja":"日本の『鍋焼きうどん』が台南で油揚げたまご麺と融合して進化した料理。レトロな井桁付きのアルミ小鍋で煮込む台南の定番グルメ。","ko":"일제강점기 나베야키 우동이 타이난에서 튀긴 계란면과 결합하여 발전한 요리로, 달착지근한 해물 육수와 튀김의 조화가 환상적입니다.","vi":"Biến tấu từ món mì Nabeyaki Nhật Bản kết hợp mì trứng chiên giòn Phúc Kiến, nấu trong nồi nhôm nhỏ đặt trên đế gỗ chữ Tỉnh truyền thống."},"taiwaneseHokkien":"Ue-sio-ì-mī (ㄨㄟ ㄒㄧㄜ ㄧˇ ㄇㄧˇ)","mandarinPinyin":"Guōshāo Yìmiàn (ㄍㄨㄛ ㄕㄠ ㄧˋ ㄇㄧㄢˋ)","audioPronunciationText":"鍋燒意麵一碗，蛋要半熟，加一份炸蝦"},"ingredients":[{"id":"fried-egg-noodles","name":{"zh-TW":"台南古法手工油炸全蛋意麵","en":"Tainan Traditional Deep-Fried Egg Noodles (E-Noodles)","ja":"台南伝統 揚げたまご意麺","ko":"타이난 전통 튀김 계란 이미엔","vi":"Mì trứng chiên giòn Đài Nam"},"amount":2,"unitMetric":"piece","unitUS":"2 noodle nests","isKeyFlavor":true,"chineseName":"油炸意麵","chinesePinyin":"Yóuzhá yìmiàn"},{"id":"bonito-dashi-broth","name":{"zh-TW":"台南清甜柴魚大骨昆布高湯","en":"Tainan Sweet Bonito & Pork Bone Broth","ja":"台南風 甘口鰹昆布豚骨出汁","ko":"달큰한 가쓰오부시 사골 육수","vi":"Nước dùng cá ngừ xương hầm ngọt thanh"},"amount":800,"unitMetric":"ml","unitUS":"3.5 cups","isKeyFlavor":true,"chineseName":"柴魚大骨高湯","chinesePinyin":"Cháiyú gāotāng"},{"id":"seafood-toppings","name":{"zh-TW":"台式裹粉炸蝦天婦羅、鮮蛤蜊、豬肉片、魚板片","en":"Tempura Shrimp, Fresh Clams, Sliced Pork, Fish Cakes","ja":"エビ天ぷら、生アサリ、豚肉スライス、かまぼこ","ko":"새우튀김, 신선한 바지락, 돼지고기, 어묵","vi":"Tôm tẩm bột chiên, nghêu tươi, thịt heo, chả cá xoắn"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"chineseName":"炸蝦蛤蜊肉片魚板","chinesePinyin":"Zhàxiā gélí"},{"id":"egg-greens","name":{"zh-TW":"新鮮雞蛋 (煮半熟水波蛋)、小白菜、蔥花、沙茶醬","en":"Fresh Eggs (for Poached Egg), Baby Greens, Scallions & Shacha Paste","ja":"生卵（半熟水波蛋用）、青菜、ネギ、サーチャージャン","ko":"신선한 계란 (반숙 수란), 청경채, 파, 사차장","vi":"Trứng gà tươi (chần lòng đào), cải ngọt, hành hoa, sốt Sa Trà"},"amount":100,"unitMetric":"g","unitUS":"1 cup","chineseName":"雞蛋青菜沙茶","chinesePinyin":"Jīdàn shāchá"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"小鋁鍋煮滾清甜柴魚高湯與海鮮肉片","en":"Boil Bonito Broth with Seafood & Pork in Small Pot","ja":"アルミ小鍋で鰹出汁を沸かし、アサリと肉を煮る","ko":"알루미늄 냄비에 육수를 끓이고 해물과 고기 익히기","vi":"Đun sôi nước dùng cá ngừ trong nồi nhôm cùng nghêu và thịt"},"instruction":{"zh-TW":"將特製小鋁鍋放在爐上，倒入 400ml 柴魚大骨高湯大火煮沸。放入蛤蜊、豬肉片、魚板與小白菜，煮至蛤蜊殼自然張開釋放鮮味。","en":"Place small aluminum pot on stove, pour in 400ml sweet bonito broth and bring to boil. Add clams, pork slices, fish cakes and greens until clams open.","ja":"アルミ小鍋に鰹出汁400mlを入れて沸騰させ、アサリ、豚肉、かまぼこ、青菜を入れてアサリの口が開くまで煮ます。","ko":"알루미늄 냄비에 육수 400ml를 붓고 끓으면 바지락, 돼지고기, 어묵, 야채를 넣어 조개가 입을 열 때까지 끓입니다.","vi":"Đặt nồi nhôm lên bếp, đổ 400ml nước dùng đun sôi. Thả nghêu, thịt heo, chả cá và rau vào nấu cho nghêu mở miệng ngọt nước."},"durationSeconds":180,"image":"/images/tw/taiwan-pot-burn-noodle-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"打入新鮮全蛋微火凝結成水波半熟蛋","en":"Crack in Fresh Egg to Form Soft Poached Center","ja":"生卵を落とし、弱火でとろとろ半熟に仕上げる","ko":"생계란을 넣고 약불에서 반숙 수란으로 익히기","vi":"Đập trứng gà vào nấu nhỏ lửa tạo lòng đào béo ngậy"},"instruction":{"zh-TW":"在滾湯空隙處打入一顆新鮮全蛋，轉中小火不要攪動，讓蛋白慢慢凝固包覆住流心蛋黃，煮約 1.5 分鐘成完美的水波半熟蛋。","en":"Crack an egg gently into bubbling broth. Keep heat on medium-low without stirring, allowing whites to envelop the rich runny yolk for 1.5 mins.","ja":"卵をそっと割り入れ、かき混ぜずに弱火で1.5分加熱し、黄身をとろとろの半熟に仕上げます。","ko":"계란을 깨뜨려 넣고 젓지 않은 채 1.5분간 익혀 노른자가 주르륵 흐르는 반숙을 만듭니다.","vi":"Đập quả trứng gà vào giữa nồi, hạ nhỏ lửa không khuấy để lòng trắng ôm trọn lòng đỏ dẻo quánh trong 1.5 phút."},"durationSeconds":90,"image":"/images/tw/taiwan-pot-burn-noodle-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"放入油炸全蛋意麵吸收精華湯汁","en":"Add Deep-Fried E-Noodles to Absorb Flavor","ja":"揚げたまご意麺を入れ、スープをサッと吸わせる","ko":"튀김 이미엔을 넣고 육수가 스며들도록 익히기","vi":"Thả mì trứng chiên vào cho hút đẫm nước súp ngọt lành"},"instruction":{"zh-TW":"將一團金黃酥脆的炸意麵放入鍋中，用筷子輕輕壓入湯汁中。只需煮 30~45 秒（切勿久煮），讓麵條外層吸飽高湯變軟、內芯仍保留微微酥香彈性！","en":"Place crispy e-noodle nest into pot, gently press into broth with chopsticks. Cook for ONLY 30-45 secs so outer strands soften while core retains bite!","ja":"揚げ意麺を鍋に入れ、箸で軽くスープに沈めます。30〜45秒だけサッと煮て、麺の芯のコシを残します！","ko":"튀긴 면을 넣고 젓가락으로 살짝 눌러 30-45초만 끓입니다. 겉은 부드럽고 속은 꼬들꼬들하게 완성!","vi":"Thả vắt mì trứng chiên vào dùng đũa ấn nhẹ ngập nước súp, chỉ nấu 30-45 giây cho mì mềm mượt mà vẫn giữ độ dai sần sật!"},"durationSeconds":45,"image":"/images/tw/taiwan-pot-burn-noodle-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"擺上炸蝦、移入井字木架上桌！","en":"Top with Tempura Shrimp, Place in Wooden Stand & Serve!","ja":"エビ天ぷらをのせ、井桁木台にセットして熱々を供する！","ko":"새우튀김을 얹고 나무 받침대에 올려 뜨겁게 서빙하기!","vi":"Bày tôm chiên xù lên trên, đặt nồi vào đế gỗ chữ Tỉnh thưởng thức ngay!"},"instruction":{"zh-TW":"關火，在麵條頂部擺上一隻金黃酥香的台式炸蝦天婦羅，撒上翠綠蔥花與一小匙牛頭牌沙茶醬。將滾燙的小鋁鍋端入專屬井字木架中，趁熱大口吸麵喝湯，半熟蛋黃戳破拌入麵中更是神級享受！","en":"Turn off heat, crown with crispy tempura shrimp, scallions and a dab of Shacha paste. Set hot aluminum pot into wooden '#'-frame stand and serve bubbling hot. Break the runny egg yolk into broth for pure bliss!","ja":"火を止め、エビ天ぷら、刻みネギ、沙茶醤をトッピング。熱々の小鍋を井桁の木枠にはめ込んで熱々を提供します。半熟卵を崩して絡めながらどうぞ！","ko":"불을 끄고 바삭한 새우튀김, 파, 사차장을 올립니다. 뜨거운 알루미늄 냄비를 나무 틀에 끼워 상에 냅니다. 반숙 노른자를 톡 터뜨려 면과 함께 드세요!","vi":"Tắt bếp, đặt con tôm chiên xù vàng rụm lên trên, rắc hành hoa và thìa sốt Sa Trà. Đặt nồi vào đế gỗ chữ Tỉnh, chọc vỡ lòng đào trộn đều cùng sợi mì húp xì xụp!"},"durationSeconds":60,"image":"/images/tw/taiwan-pot-burn-noodle-step4.jpg"}],"troubleshooting":[{"id":"noodles-overcooked","problem":{"zh-TW":"意麵煮太久軟爛成泥糊掉了？","en":"Why are my E-noodles completely soggy & mushy?","ja":"意麺が伸びてドロドロになってしまった？","ko":"이미엔이 너무 불어서 푹 퍼졌나요?","vi":"Mì trứng bị nấu quá tay nhũn nát mất độ ngon?"},"cause":{"zh-TW":"炸意麵氣孔極多吸水極快，煮超過 1 分鐘就會過爛。","en":"Fried noodles are porous and absorb liquid in seconds; overcooked past 1 min.","ja":"油揚げ麺は吸水性が高いため、1分以上煮込むと伸びてしまいます。","ko":"튀김면의 미세한 구멍이 국물을 빠르게 흡수하므로 1분 이상 끓이면 퍼집니다.","vi":"Mì trứng chiên xốp hút nước cực nhanh, nấu quá 1 phút sẽ bị nát."},"solution":{"zh-TW":"所有海鮮料煮熟後再下意麵，浸入湯中煮 30 秒即可熄火起鍋！","en":"Add noodles ONLY after toppings are fully cooked, simmer for 30s and turn off heat immediately!","ja":"具材が煮えてから最後に麺を入れ、30秒で火を止めてください！","ko":"모든 재료가 다 익은 후 마지막에 면을 넣고 30초만 끓인 뒤 불을 끄세요!","vi":"Chỉ cho mì vào sau khi mọi nguyên liệu đã chín, đun đúng 30 giây là tắt bếp ngay!"}}],"proTips":[{"zh-TW":"吃鍋燒意麵的靈魂儀式：先吃一條吸飽柴魚湯的微脆意麵，接著用筷子輕輕戳破水波蛋，讓金黃蛋黃流淌在麵條與高湯中攪拌，湯頭瞬間提升至絲滑濃醇的境界！","en":"The sacred ritual: poke the poached yolk to swirl rich golden velvet into the sweet seafood broth!","ja":"半熟卵の黄身をとろりと崩し、出汁と絡めながらすするのが台南流の最高の食べ方です！","ko":"반숙 노른자를 톡 터뜨려 육수에 부드럽게 풀고 면을 적셔 먹는 것이 타이난의 정석!","vi":"Tuyệt kỹ thưởng thức: chọc vỡ lòng đào cho hòa quyện vào nước dùng cá ngừ tạo nên độ béo ngậy ngọt lịm tan chảy!"}]},{"country":"tw","id":"taiwan-braised-dishes","slug":"taiwan-braised-dishes","title":{"zh-TW":"台灣夜市熱燙加熱滷味","en":"Taiwanese Hot Braised Delicacies (Lu Wei Assortment)","ja":"台湾夜市名物 熱々加熱ルーウェイ（滷味盛り合わせ）","ko":"대만 야시장 즉석 열탕 루웨이 (한방 특제 조림 모둠)","vi":"Phá lấu hầm nóng chợ đêm Đài Loan (Lu Wei)"},"subtitle":{"zh-TW":"數十種食材自選・中藥老滷滾燙現煮・爽脆酸菜・蔥花辣油・靈魂王子麵","en":"Custom Picked Delicacies, Boiling Herbal Master Stock, Pickled Mustard Greens & Prince Noodles","ja":"選べる具材・漢方秘伝スープで熱々ボイル・特製高菜・ネギ・辣油・名物王子麺","ko":"골라 담는 재미, 한방 비법 육수에 즉석에서 데쳐낸 모둠 조림, 갓절임, 파, 왕자라면","vi":"Tự chọn nguyên liệu, trụng sôi trong nước lẩu thảo mộc gia truyền, dưa chua, hành hoa và mì Hoàng Tử"},"tagline":{"zh-TW":"師大夜市與各大大學商圈的宵夜霸主！滿滿一滿大竹簍任你挑選現滷","en":"The undisputed midnight feast champion: grab a basket, pile high with goodies, boiled fresh!","ja":"師大夜市をはじめ全土で愛される夜食の王様！カゴいっぱいに選んだ具材を秘伝ダレで熱々に煮込む","ko":"대만 대학가와 야시장의 절대 야식 강자! 바구니에 먹고 싶은 재료를 골라 담아 즉석에서 끓여내는 맛","vi":"Vua ăn đêm các khu chợ sinh viên: tự tay gắp đầy rổ thức ăn rồi trụng nóng hổi đậm đà"},"heroImage":"/images/tw/taiwan-lu-wei-hero.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":30,"defaultServings":3,"caloriesPerServing":480,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"台北師大夜市（燈籠滷味）/ 全台灣夜市","en":"Taipei Shida Night Market (Lantern Lu Wei)","ja":"台北師大夜市（燈籠滷味）","ko":"타이베이 스다 야시장 (등롱 루웨이)","vi":"Chợ đêm Shida Đài Bắc (Đèn Lồng Phá Lấu)"},"famousNightMarkets":[{"zh-TW":"師大夜市（燈籠滷味 / 大台北滷味）","en":"Shida Night Market","ja":"師大夜市","ko":"스다 야시장","vi":"Chợ đêm Shida"},{"zh-TW":"逢甲夜市","en":"Fengjia Night Market","ja":"逢甲夜市","ko":"펑자 야시장","vi":"Chợ đêm Fengjia"}],"historyStory":{"zh-TW":"源自潮汕滷味，在台北師大夜市等學區演變成獨特『加熱滷味』形式。客人拿著紅色塑膠籃夾取心儀食材（花干、豆干、甜不辣、鴨血、大腸、高麗菜、王子麵），老闆丟入大鍋滾沸的中藥老滷汁中燙煮，切盤撒上大量特製炒酸菜與青蔥辣油。","en":"A vibrant Taiwanese street food ritual where customers fill baskets with tofu puffs, meats, veggies and Prince instant noodles, flash-cooked in bubbling Chinese herbal master stock.","ja":"客がカゴに好みの具材（湯葉、厚揚げ、練り物、鴨血、野菜、インスタント麺）を選び、秘伝の漢方醤油出汁でグツグツ煮込んで酸菜とネギを添えて提供するスタイル。","ko":"바구니에 유부, 두부, 어묵, 야채, 라면 등을 직접 골라 담으면 한방 특제 간장 육수에 즉석에서 데쳐 갓절임과 파를 얹어 내는 대만 최고의 길거리 야식입니다.","vi":"Khách tự chọn các loại đậu hũ, chả cá, lòng heo, rau bắp cải và mì gói vào giỏ, đầu bếp thả vào nồi nước dùng thảo mộc sôi sục trụng chín cắt đĩa rắc dưa chua hành hoa."},"taiwaneseHokkien":"Lóo-bī (ㄌㄛˋ ㄅㄧˇ)","mandarinPinyin":"Jiārè Lǔwèi (ㄐㄧㄚ ㄖㄜˋ ㄌㄨˇ ㄨㄟˋ)","audioPronunciationText":"老闆，籃子夾好了，要加一包王子麵、小辣、酸菜多一點"},"ingredients":[{"id":"luwei-ingredients-mix","name":{"zh-TW":"夜市經典滷味食材 (大溪豆干、花干、甜不辣、米血糕、貢丸、高麗菜)","en":"Classic Lu Wei Mix (Tofu Puffs, Dried Bean Curd, Fish Cakes, Blood Cake, Meatballs, Cabbage)","ja":"夜市定番具材（厚揚げ、押し豆腐、さつま揚げ、米血糕、キャベツ等）","ko":"루웨이 모둠 재료 (유부, 두부, 어묵, 찹쌀떡, 고기완자, 양배추)","vi":"Hỗn hợp nguyên liệu (Đậu hũ hoa, đậu hũ khô, chả cá, huyết nếp, bắp cải)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"chineseName":"豆干花干甜不辣米血","chinesePinyin":"Dòugān huāgān"},{"id":"prince-instant-noodles","name":{"zh-TW":"台灣經典滷味專用王子麵","en":"Taiwan Prince Instant Noodles (for Lu Wei)","ja":"台湾名物 王子麺（煮込み専用インスタント麺）","ko":"대만 전통 루웨이 전용 왕자라면 (프린스 누들)","vi":"Mì ăn liền Hoàng Tử chuyên dùng nấu phá lấu"},"amount":2,"unitMetric":"piece","unitUS":"2 packs","isKeyFlavor":true,"chineseName":"滷味王子麵","chinesePinyin":"Wángzǐ miàn"},{"id":"chinese-herbal-master-stock","name":{"zh-TW":"中藥老滷汁 (八角+花椒+桂皮+草果+甘草+冰糖+醬油)","en":"Chinese Herbal Master Braising Stock","ja":"秘伝漢方煮込み醤油スープ（八角・花椒・桂皮・甘草等）","ko":"한방 특제 간장 육수 (팔각, 화조, 계피, 감초, 얼음설탕)","vi":"Nước cốt lẩu thảo mộc ngũ vị (Hoa hồi, quế, thảo quả, cam thảo)"},"amount":1200,"unitMetric":"ml","unitUS":"5 cups","isKeyFlavor":true,"chineseName":"中藥老滷汁","chinesePinyin":"Lǔzhī"},{"id":"taiwan-suancai-scallion","name":{"zh-TW":"炒酸菜、新鮮蔥花、蒜泥、香油、生辣椒油","en":"Taiwanese Sautéed Pickled Greens, Scallions, Garlic Paste & Chili Oil","ja":"炒め高菜（酸菜）、刻みネギ、おろしニンニク、ごま油、特製辣油","ko":"볶은 갓절임 (쑤안차이), 송송 썬 파, 다진 마늘, 참기름, 고추기름","vi":"Dưa cải chua xào thơm, hành hoa tươi, tỏi băm, dầu mè và sa tế"},"amount":100,"unitMetric":"g","unitUS":"1 cup","chineseName":"炒酸菜蔥花辣油","chinesePinyin":"Suāncài cōnghuā"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火熬製濃郁飄香中藥老滷高湯","en":"Simmer Aromatic Chinese Herbal Master Stock","ja":"漢方スパイスと醤油で秘伝の香り高い滷汁を煮出す","ko":"한방 약재와 간장으로 깊고 진한 루웨이 육수 끓이기","vi":"Ninh nước lẩu thảo mộc với hoa hồi quế thảo quả đậm đà thơm ngát"},"instruction":{"zh-TW":"大鍋中加入八角、草果、桂皮、花椒、甘草、青蔥、薑片與蒜頭。注入 1500ml 高湯，加入優質醬油、冰糖、米酒慢火熬煮 20 分鐘至香氣四溢。","en":"Boil 1500ml stock with star anise, cinnamon, sichuan pepper, licorice, scallions, ginger and garlic. Add soy sauce, rock sugar and rice wine; simmer for 20 mins into fragrant master stock.","ja":"鍋に八角、桂皮、花椒、甘草、ネギ、生姜、ニンニク、醤油、氷砂糖、酒を入れ、弱火で20分煮出して風味豊かな滷汁を作ります。","ko":"냄비에 팔각, 계피, 감초, 파, 생강, 마늘과 육수 1.5L, 간장, 얼음설탕을 넣고 20분간 끓여 깊은 향의 비법 육수를 만듭니다.","vi":"Cho hoa hồi, quế, thảo quả, hành gừng tỏi vào nồi đun cùng 1.5L nước dùng, nước tương, đường phèn 20 phút cho dậy mùi thơm nức mũi."},"durationSeconds":1200,"image":"/images/tw/taiwan-lu-wei-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"自選食材入滾沸滷汁大火燙煮入味","en":"Boil Custom Ingredients in Bubbling Master Stock","ja":"選んだ具材を煮立つ滷汁に入れ、しっかり味を染み込ませる","ko":"골라 담은 재료들을 끓는 한방 육수에 넣고 데치기","vi":"Thả các loại nguyên liệu đã chọn vào nồi nước dùng sôi sùng sục trụng chín"},"instruction":{"zh-TW":"將切塊的豆干、花干、甜不辣、米血糕、鴨血、貢丸等耐煮食材放入滾沸的滷汁網杓中，中大火燙煮 3~5 分鐘，讓多孔的花干與豆干吸飽濃郁滷汁。","en":"Drop tofu puffs, dried bean curd, fish cakes, blood rice cake and meatballs into boiling master stock. Simmer for 3-5 mins so porous tofu puffs drink in flavorful stock.","ja":"厚揚げ、豆腐、テンプラ、米血糕、つみれ等を沸騰した滷汁に入れ、強火で3〜5分煮て出汁をしっかり吸わせます。","ko":"두부, 유부, 어묵, 찹쌀떡, 완자 등을 끓는 육수에 넣고 3-5분간 끓여 속까지 양념이 깊게 배어들게 합니다.","vi":"Thả đậu hũ, chả cá, huyết nếp, viên thịt vào vợt nhúng trong nước lẩu sôi 3-5 phút cho ngấm đẫm vị đậm đà."},"durationSeconds":300,"image":"/images/tw/taiwan-lu-wei-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"下高麗菜與靈魂王子麵快煮撈起","en":"Quick-Boil Crisp Cabbage & Prince Instant Noodles","ja":"キャベツと名物王子麺をサッと茹でてアルデンテに仕上げる","ko":"양배추와 왕자라면을 넣고 꼬들꼬들하게 빠르게 끓여내기","vi":"Thả bắp cải giòn và mì Hoàng Tử vào trụng nhanh vừa chín tới"},"instruction":{"zh-TW":"最後放入撕大片的高麗菜與拆封的王子麵。大火滾煮 1.5~2 分鐘（王子麵保持微捲彈牙勿煮過爛），連同所有食材一起用濾網撈出瀝乾。","en":"Add fresh cabbage and Prince instant noodles. Boil on high for 1.5-2 mins (keep noodles al dente). Scoop everything out with strainer basket and drain well.","ja":"最後にキャベツと王子麺を入れ、強火で1.5〜2分サッと煮て麺のコシを残した状態で素早くザルに上げます。","ko":"마지막에 양배추와 왕자라면을 넣고 1.5-2분간 센 불에 끓여 면이 꼬들할 때 모든 재료를 건져 물기를 뺍니다.","vi":"Cho bắp cải và mì Hoàng Tử vào đun lửa lớn 1.5-2 phút cho mì vừa chín tới dai ngon, vớt toàn bộ ra ráo nước."},"durationSeconds":120,"image":"/images/tw/taiwan-lu-wei-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"切盤淋滷汁、撒滿爆香炒酸菜與蔥花辣油！","en":"Slice onto Platter, Ladle Sauce, Heap Pickled Greens & Scallions","ja":"食べやすく切り皿に盛り、特製炒め高菜とネギ・辣油を山盛りに！","ko":"먹기 좋게 썰어 접시에 담고 볶은 갓절임과 파, 고추기름 듬뿍 얹기!","vi":"Cắt miếng vừa ăn xếp ra đĩa, chan chút nước sốt, rắc đẫm dưa chua xào và hành hoa sa tế!"},"instruction":{"zh-TW":"將食材倒在大砧板上快速切成一口大小，盛入大盤中，王子麵鋪底。淋上一勺精華熱滷汁、香油與蒜泥，頂部鋪滿一大坨靈魂炒酸菜、滿滿蔥花與自製生辣椒醬，趁熱拌勻大快朵頤！","en":"Chop braised delicacies into bite-sized pieces on cutting board. Mound over Prince noodles on a huge platter. Drizzle hot master broth, sesame oil and garlic. Crown with mountain of savory stir-fried pickled greens, scallions and fiery chili!","ja":"まな板で一口大に切り、王子麺の上に豪快に盛り付けます。熱い滷汁、ごま油、ニンニクを回しかけ、炒め高菜とネギ、特製ラー油をたっぷり添えて熱々を混ぜていただきます！","ko":"도마에서 한입 크기로 썰어 라면 위에 푸짐하게 담습니다. 뜨거운 육수와 참기름, 마늘을 뿌리고 볶은 갓절임, 파, 고추기름을 산더미처럼 얹어 비벼 먹습니다!","vi":"Chặt nhỏ các nguyên liệu vừa ăn bày lên đĩa trên lớp mì. Rưới nước sốt nóng, dầu mè, tỏi băm rồi phủ ngập dưa chua xào giòn, hành hoa và sa tế thơm cay nức nở!"},"durationSeconds":60,"image":"/images/tw/taiwan-lu-wei-step4.jpg"}],"troubleshooting":[{"id":"prince-noodles-soggy","problem":{"zh-TW":"王子麵泡太軟爛沒有彈性？","en":"Why are my Prince noodles overly soggy?","ja":"王子麺が伸びて柔らかくなりすぎてしまった？","ko":"왕자라면이 너무 불어서 식감이 없나요?","vi":"Mì Hoàng Tử bị nở nhũn mất độ dai giòn?"},"cause":{"zh-TW":"煮超過 2 分鐘，或起鍋後浸泡在熱湯中太久。","en":"Boiled past 2 mins or sat in hot liquid.","ja":"2分以上茹ですぎたか、熱いスープに浸したまま放置したためです。","ko":"2분 이상 끓였거나 뜨거운 국물에 오래 방치되었기 때문입니다.","vi":"Nấu quá 2 phút hoặc để ngâm trong nước nóng quá lâu."},"solution":{"zh-TW":"大火滾煮 1.5 分鐘麵條微捲即刻撈出瀝乾，淋少許香油拌勻防黏！","en":"Boil 90 seconds only while curly, drain immediately and toss with a drop of sesame oil!","ja":"強火で1分半、少し芯が残る程度で引き上げてごま油を絡めてください！","ko":"센 불에서 1분 30초만 끓여 꼬들할 때 건져내 참기름을 살짝 둘러 비비세요!","vi":"Chỉ luộc 1.5 phút cho sợi mì xoăn dai vớt ra ngay, rưới chút dầu mè chống dính!"}}],"proTips":[{"zh-TW":"夜市加熱滷味的靈魂是『炒酸菜』！用蒜碎、辣椒與砂糖小火煸炒鹹酸菜至油亮甘甜，撒在滷味上解膩提鮮，美味瞬間翻倍！","en":"The unsung hero is the sweet-savory stir-fried pickled mustard greens, which balances the rich herbal soy flavors!","ja":"ニンニク、唐辛子、砂糖で香ばしく炒めた特製高菜（酸菜）が味の決め手！","ko":"마늘과 고추, 설탕을 넣고 달콤 짭조름하게 볶아낸 갓절임(쑤안차이)이 루웨이의 핵심 비법입니다!","vi":"Linh hồn món phá lấu chính là dưa chua xào tỏi ớt đường vàng óng chua ngọt cân bằng vị béo!"}]},{"country":"tw","id":"hot-grass-jelly","slug":"hot-grass-jelly","title":{"zh-TW":"九份傳統古早味燒仙草","en":"Jiufen Traditional Hot Grass Jelly","ja":"九份名物 台湾伝統のホット仙草ゼリー（熱々焼仙草）","ko":"대만 지우펀 전통 따뜻한 허브 젤리 탕 (샤오셴차오)","vi":"Thạch sương sáo nóng cổ truyền Cửu Phần (Thiêu Tiên Thảo)"},"subtitle":{"zh-TW":"關西仙草乾慢火熬煮・手工Q彈九份芋圓・蜜紅豆・香脆硬花生","en":"Slow-Simmered Herb Grass Tea, Chewy Taro Balls, Sweet Red Beans & Crunchy Roasted Peanuts","ja":"本場関西産仙草茶・モチモチ九份手作り芋圓・蜜小豆・香ばしいカリカリピーナッツ","ko":"진하게 달인 천연 선초차, 쫀득한 수제 지우펀 위위안(토란떡), 달콤한 팥, 바삭한 볶은 땅콩","vi":"Sương sáo tự nhiên nấu cô đặc, viên khoai dẻo Cửu Phần, đậu đỏ ngọt bùi và đậu phộng rang giòn"},"tagline":{"zh-TW":"冬天台灣街頭最溫暖的治癒系甜品！熱氣騰騰漸漸凝固的濃郁草本清香","en":"Taiwan's ultimate winter warmth: steaming herbal jelly that gently sets as you savor it","ja":"台湾の冬の風物詩！熱々のスープが冷めるとプルプルに固まる、身体に優しい癒しのデザート","ko":"대만의 겨울을 따뜻하게 녹여주는 국민 힐링 디저트! 식으면서 젤리처럼 굳어가는 매력","vi":"Món tráng miệng sưởi ấm mùa đông Đài Loan với hương thơm thảo mộc tự nhiên ngưng đọng dần khi ăn"},"heroImage":"/images/tw/taiwan-hot-grass-jelly-hero.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":25,"defaultServings":3,"caloriesPerServing":260,"category":"desserts","dietaryTags":["classic","vegetarian","vegan","glutenFree"],"supportedCookware":["traditional"],"culture":{"originCity":{"zh-TW":"新竹關西 / 新北九份老街","en":"Hsinchu Guanxi / New Taipei Jiufen","ja":"新竹関西 / 新北九份","ko":"신주 관시 / 신베이 지우펀","vi":"Quan Tây Tân Trúc / Cửu Phần Tân Bắc"},"famousNightMarkets":[{"zh-TW":"九份老街","en":"Jiufen Old Street","ja":"九份老街","ko":"지우펀 라오제","vi":"Phố cổ Cửu Phần"},{"zh-TW":"饒河街觀光夜市","en":"Raohe Night Market","ja":"饒河街夜市","ko":"라오허제 야시장","vi":"Chợ đêm Raohe"},{"zh-TW":"樂華夜市","en":"Lehua Night Market","ja":"樂華夜市","ko":"러화 야시장","vi":"Chợ đêm Lehua"}],"historyStory":{"zh-TW":"源自客家傳統草本智慧，將新竹關西陳年仙草乾加水慢熬數小時成深黑仙草濃汁，加入少許在來米粉漿或樹薯粉勾芡保持微稠流動態。上桌時冒著白煙，搭配九份手工芋圓、地瓜圓、粉圓，最後撒上一小包脆硬花生米，趁熱享用。","en":"Crafted from aged dried mesona herbs simmered into a rich dark elixir lightly thickened with starch. Served piping-hot with handmade chewy taro/sweet potato balls and crunchy roasted peanuts.","ja":"新竹・関西産の乾燥仙草を煮出した薬膳スープ。熱々のスープに九份名物の芋圓（タロ芋団子）やタピオカを入れ、ピーナッツを浮かべて温かいまま食します。","ko":"신주 관시의 말린 선초를 푹 달여 만든 따뜻한 디저트로, 지우펀의 쫀득한 타로볼과 달콤한 팥, 바삭한 땅콩을 곁들여 먹는 전통 보양 간식입니다.","vi":"Nấu từ cây sương sáo khô Guanxi thơm nức, thêm bột năng tạo độ sánh mượt, ăn kèm viên khoai dẻo Cửu Phần và đậu phộng rang giòn thơm phức."},"taiwaneseHokkien":"Sio-sian-tsháu (ㄒㄧㄜ ㄒㄧㄢ ㄘㄠˋ)","mandarinPinyin":"Shāoxiāncǎo (ㄕㄠ ㄒㄧㄢ ㄘㄠˇ)","audioPronunciationText":"老闆，燒仙草熱的一碗，要芋圓、紅豆、珍珠，花生多給一包"},"ingredients":[{"id":"pure-grass-jelly-liquid","name":{"zh-TW":"純正關西濃縮仙草汁 (含微量紅糖)","en":"Pure Guanxi Mesona Grass Tea Concentrate","ja":"新竹関西産 無添加濃縮仙草茶","ko":"신주 관시 순수 농축 선초액","vi":"Nước cốt sương sáo nguyên chất Guanxi"},"amount":600,"unitMetric":"ml","unitUS":"2.5 cups","isKeyFlavor":true,"chineseName":"濃縮仙草汁","chinesePinyin":"Xiāncǎo zhī"},{"id":"tapioca-thickener","name":{"zh-TW":"樹薯澱粉或太白粉水 (微勾芡保溫微凝)","en":"Tapioca Starch Slurry (for Silky Thickening)","ja":"タピオカ澱粉水溶き（とろみ付け用）","ko":"타피오카 전분물 (농도 조절용)","vi":"Nước bột năng tạo độ sánh"},"amount":25,"unitMetric":"g","unitUS":"2 tbsp","chineseName":"樹薯粉芡水","chinesePinyin":"Shùshǔfěn"},{"id":"taro-sweet-potato-balls","name":{"zh-TW":"九份手工Q彈芋圓與地瓜圓","en":"Jiufen Handmade Chewy Taro & Sweet Potato Balls","ja":"九份手作り 芋圓＆地瓜圓（タロ芋・サツマイモ団子）","ko":"지우펀 수제 타로볼 및 고구마볼 (위위안)","vi":"Viên khoai môn và khoai lang dẻo Cửu Phần"},"amount":150,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"chineseName":"九份芋圓地瓜圓","chinesePinyin":"Yùyuán dìguāyuán"},{"id":"toppings-peanuts","name":{"zh-TW":"蜜紅豆、黑糖珍珠、香脆硬花生米","en":"Sweet Red Beans, Boba Pearls & Crispy Roasted Peanuts","ja":"蜜小豆、ブラックタピオカ、香ばしいローストピーナッツ","ko":"달콤한 팥, 흑당 버블, 바삭한 볶은 땅콩","vi":"Đậu đỏ rim đường, trân châu đen và đậu phộng rang giòn"},"amount":100,"unitMetric":"g","unitUS":"1 cup","isKeyFlavor":true,"chineseName":"蜜紅豆硬花生","chinesePinyin":"Mì hóngdòu"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"滾水煮熟九份芋圓地瓜圓至漂浮撈起","en":"Boil Chewy Taro & Sweet Potato Balls until Floating","ja":"芋圓と地瓜圓を熱湯で茹でて浮き上がったらすくう","ko":"끓는 물에 타로볼과 고구마볼을 삶아 떠오르면 건지기","vi":"Luộc viên khoai dẻo trong nước sôi đến khi nổi lên vớt ra"},"instruction":{"zh-TW":"大鍋水燒滾，下入九份手工芋圓與地瓜圓。大火煮約 2.5~3 分鐘至全部膨脹浮於水面，撈起泡入少許砂糖蜜水中保溫防黏並保持極致Q彈。","en":"Bring pot of water to boil, drop in taro and sweet potato balls. Boil for 2.5-3 mins until fully buoyant. Transfer into light sugar syrup to keep chewy.","ja":"沸騰した湯に芋圓と地瓜圓を入れ、浮き上がってから2分ほど茹でます。砂糖水に浸してくっつきを防ぎモチモチ感を保ちます。","ko":"끓는 물에 타로볼을 넣고 2.5-3분간 삶아 떠오르면 건져 설탕물에 담가 쫄깃함을 유지합니다.","vi":"Thả viên khoai vào nước sôi luộc 2.5-3 phút cho nổi bồng bềnh, vớt ra ngâm nước đường loãng cho dẻo thơm không bị dính."},"durationSeconds":180,"image":"/images/tw/taiwan-hot-grass-jelly-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"慢火煮熱仙草汁並淋入澱粉水微勾芡","en":"Simmer Grass Tea & Whisk in Starch Slurry","ja":"仙草茶を温め、水溶き澱粉を加えてなめらかなとろみをつける","ko":"선초액을 데우고 전분물을 풀어 부드러운 농도 맞추기","vi":"Đun nóng nước sương sáo và rót nước bột năng tạo độ sánh mịn"},"instruction":{"zh-TW":"厚底鍋倒入濃縮仙草汁與適量二砂糖微火煮滾。緩緩淋入樹薯澱粉水，用打蛋器快速攪勻，煮至湯汁呈現絲滑透亮、微稠流動狀，熄火保溫。","en":"Heat grass tea concentrate with sugar until simmering. Slowly drizzle in tapioca starch slurry while whisking continuously until glossy, velvety and lightly thickened.","ja":"小鍋に仙草茶と砂糖を入れて温め、水溶きタピオカ粉を少しずつ加えながら混ぜ、なめらかなとろみをつけます。","ko":"냄비에 선초액과 설탕을 넣고 끓이다가 전분물을 조금씩 부어가며 저어 부드럽고 걸쭉한 농도를 만듭니다.","vi":"Đun sôi nước cốt sương sáo với đường nâu, từ từ rót nước bột năng khuấy đều tay cho nước sánh mượt bóng bẩy."},"durationSeconds":300,"image":"/images/tw/taiwan-hot-grass-jelly-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"碗底盛入滿滿芋圓、地瓜圓、蜜紅豆與珍珠","en":"Layer Chewy Toppings, Sweet Red Beans & Boba in Bowl","ja":"器に芋圓、地瓜圓、蜜小豆、タピオカをたっぷり盛り付ける","ko":"대접에 타로볼, 고구마볼, 팥, 타피오카펄을 듬뿍 담기","vi":"Xếp các loại viên khoai dẻo, đậu đỏ và trân châu vào đáy bát"},"instruction":{"zh-TW":"在溫熱的甜品碗底，大勺舀入煮好的九份芋圓、地瓜圓、軟爛蜜紅豆與黑糖珍珠粉圓，配料豐富滿溢。","en":"Spoon warm taro balls, sweet potato balls, sweet red beans and brown sugar boba pearls into serving bowl.","ja":"温めた器に、茹でたての芋圓、地瓜圓、甘い小豆、黒糖タピオカを彩りよく盛り付けます。","ko":"따뜻한 그릇에 삶아둔 타로볼, 달콤한 팥, 흑당 버블을 듬뿍 담습니다.","vi":"Múc viên khoai môn, khoai lang, đậu đỏ rim ngọt và trân châu đường nâu vào lòng bát sâu."},"durationSeconds":60,"image":"/images/tw/taiwan-hot-grass-jelly-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"澆入滾燙濃醇燒仙草、撒上香脆硬花生！","en":"Pour Piping-Hot Grass Jelly Soup & Scatter Crisp Peanuts!","ja":"熱々の焼仙草スープを注ぎ、香ばしいピーナッツを浮かべる！","ko":"뜨거운 선초탕을 붓고 바삭한 볶은 땅콩을 띄워 완성!","vi":"Chan nước sương sáo nóng hổi và rắc đậu phộng rang giòn rụm lên trên!"},"instruction":{"zh-TW":"將滾燙冒煙的濃郁燒仙草汁緩緩澆入碗中淹沒所有配料。上桌前撕開一包香脆烘烤硬花生米撒在表面，趁熱大口舀取，軟Q、甘甜、香脆在口中交融，隨溫度冷卻更會漸漸凝固如果凍！","en":"Pour steaming hot grass jelly soup over all toppings. Scatter a generous handful of crunchy roasted peanuts on top. Savor hot as the soup slowly sets into soft tender jelly as you eat!","ja":"熱々の焼仙草スープをたっぷり注ぎ、カリカリのピーナッツをトッピングして熱々をいただきます！冷めると自然にゼリー状に固まっていく食感の変化も絶品です！","ko":"김이 모락모락 나는 뜨거운 선초액을 가득 붓고 바삭한 볶은 땅콩을 뿌립니다. 식으면서 말랑한 젤리로 변해가는 재미를 느끼며 드세요!","vi":"Rót nước sương sáo sôi bốc khói vào ngập bát, rắc gói đậu phộng rang giòn thơm phức lên trên. Vừa ăn vừa cảm nhận thạch đông dẻo dần theo thời gian!"},"durationSeconds":60,"image":"/images/tw/taiwan-hot-grass-jelly-step4.jpg"}],"troubleshooting":[{"id":"not-thickening","problem":{"zh-TW":"燒仙草煮出來像水一樣完全不濃稠？","en":"Why is my hot grass jelly as thin as water?","ja":"焼仙草にとろみがつかずサラサラのまま？","ko":"선초탕이 걸쭉해지지 않고 물처럼 묽은가요?","vi":"Nước sương sáo bị loãng như nước lọc không có độ sánh?"},"cause":{"zh-TW":"樹薯澱粉勾芡量太少，或沒有煮滾激活澱粉糊化。","en":"Not enough starch slurry, or didn't boil to activate gelatinization.","ja":"澱粉の量が少なかったか、沸騰させて糊化させていませんでした。","ko":"전분물 양이 적었거나 충분히 끓여 활성화하지 않았기 때문입니다.","vi":"Cho quá ít bột năng hoặc chưa đun sôi để bột chín tạo độ sánh."},"solution":{"zh-TW":"淋入樹薯澱粉水後務必維持微滾攪拌 1 分鐘，起鍋時略有稠度，冷卻後就會漸漸凝固！","en":"Boil and stir for 1 full minute after adding slurry; it will naturally firm up as it cools!","ja":"水溶き粉を加えたらしっかり1分弱火で沸騰させてください。冷めると自然にとろみが強まります！","ko":"전분물을 넣고 1분간 저어가며 충분히 끓여주세요. 식으면서 점차 굳어집니다!","vi":"Rót bột năng đun sôi khuấy đều 1 phút cho hồ hóa, khi để nguội sẽ sánh đặc lại như ý!"}}],"proTips":[{"zh-TW":"一定要附上一小包『硬花生』！剛撒上去時硬脆香濃，在熱仙草中浸泡幾秒後外酥內脆，是整碗燒仙草的點睛之筆！","en":"Crunchy roasted peanuts are non-negotiable! The crispy crunch against velvety warm herbal jelly is perfection!","ja":"ローストピーナッツは必須！温かい仙草ゼリーと香ばしいナッツの食感の対比が格別です！","ko":"바삭한 볶은 땅콩은 절대 빠질 수 없는 핵심! 부드러운 젤리와 바삭한 땅콩의 조화가 환상적입니다!","vi":"Đậu phộng rang giòn là linh hồn không thể thiếu! Độ bùi giòn rụm đối lập với thạch sương sáo mềm mướt tạo nên trải nghiệm tuyệt hảo!"}]}];
